#!/usr/bin/env python3

import argparse
import time
import datetime
import json
import logging
import signal
import sys
import random
import urllib.request
import urllib.error
from collections import deque

try:
    import spidev
except ImportError:
    spidev = None

try:
    from gpiozero import OutputDevice
except ImportError:
    OutputDevice = None

DEFAULT_SAMPLE_RATE = 500
DEFAULT_THRESHOLD = 0.5
DEFAULT_HYSTERESIS = 0.05
DEFAULT_LOG_FILE = "sound_data.log"
DEFAULT_CLOUD_URL = "https://example.com/api/data"
DEFAULT_WINDOW_SIZE = 10
DEFAULT_OUTPUT_PIN = 0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_mcp3008(spi, channel):
    if channel < 0 or channel > 7:
        raise ValueError("Channel must be 0-7")
    r = spi.xfer2([1, (8 + channel) << 4, 0])
    return ((r[1] & 3) << 8) + r[2]

def simulate_sound_level():
    return random.uniform(0.0, 1.0)

def moving_average(data, window_size):
    if len(data) < window_size:
        return sum(data) / len(data) if data else 0.0
    return sum(list(data)[-window_size:]) / window_size

def main():
    global running

    parser = argparse.ArgumentParser(description="Sound Level Monitoring System")
    parser.add_argument("--sample_rate", type=int, default=DEFAULT_SAMPLE_RATE, help="Sampling rate in Hz")
    parser.add_argument("--threshold", type=float, default=DEFAULT_THRESHOLD, help="Sound level threshold (0.0-1.0)")
    parser.add_argument("--hysteresis", type=float, default=DEFAULT_HYSTERESIS, help="Hysteresis value (0.0-1.0)")
    parser.add_argument("--log_file", type=str, default=DEFAULT_LOG_FILE, help="Path to log file")
    parser.add_argument("--cloud_url", type=str, default=DEFAULT_CLOUD_URL, help="Cloud service URL")
    parser.add_argument("--window_size", type=int, default=DEFAULT_WINDOW_SIZE, help="Moving average window size")
    parser.add_argument("--duration", type=int, help="Run for a specific duration in seconds")
    parser.add_argument("--output_pin", type=int, default=DEFAULT_OUTPUT_PIN, help="GPIO pin for output (BCM)")
    args = parser.parse_args()

    if args.sample_rate <= 0:
        print("Error: sample_rate must be positive.", file=sys.stderr)
        sys.exit(1)
    if not 0.0 <= args.threshold <= 1.0:
        print("Error: threshold must be between 0.0 and 1.0.", file=sys.stderr)
        sys.exit(1)
    if not 0.0 <= args.hysteresis <= 1.0:
        print("Error: hysteresis must be between 0.0 and 1.0.", file=sys.stderr)
        sys.exit(1)
    if args.window_size <= 0:
        print("Error: window_size must be positive.", file=sys.stderr)
        sys.exit(1)

    logging.basicConfig(filename=args.log_file, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')
    logging.info("Starting Sound Level Monitoring System")

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    spi = None
    output = None
    use_simulation = False

    if spidev is not None:
        try:
            spi = spidev.SpiDev()
            spi.open(0, 0)
            spi.max_speed_hz = 1000000
            spi.mode = 0
            logging.info("SPI initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize SPI: {e}. Falling back to simulation.")
            spi = None
            use_simulation = True
    else:
        logging.warning("spidev not available. Falling back to simulation.")
        use_simulation = True

    if OutputDevice is not None and args.output_pin > 0:
        try:
            output = OutputDevice(args.output_pin)
            output.off()
            logging.info(f"Output pin {args.output_pin} initialized.")
        except Exception as e:
            logging.error(f"Failed to initialize output pin {args.output_pin}: {e}. Output disabled.")
            output = None
    else:
        logging.info("Output pin not specified or gpiozero not available. Output disabled.")

    sound_data = deque(maxlen=args.window_size)
    last_cloud_upload = 0.0
    last_cloud_upload_attempt = 0.0
    cloud_upload_retries = 0
    max_retries = 3

    start_time = time.time()

    try:
        while running:
            if args.duration and (time.time() - start_time) >= args.duration:
                logging.info("Duration reached. Exiting.")
                break

            if use_simulation:
                sound_level = simulate_sound_level()
            else:
                try:
                    adc_value = read_mcp3008(spi, 0)
                    sound_level = adc_value / 1023.0
                except Exception as e:
                    logging.error(f"SPI read error: {e}. Using simulated data.")
                    sound_level = simulate_sound_level()

            sound_data.append(sound_level)
            filtered_sound_level = moving_average(sound_data, args.window_size)

            if filtered_sound_level > args.threshold:
                if output:
                    output.on()
                    logging.info(f"Output pin {args.output_pin} set HIGH.")
            elif filtered_sound_level < (args.threshold - args.hysteresis):
                if output:
                    output.off()
                    logging.info(f"Output pin {args.output_pin} set LOW.")

            data = {
                "timestamp": datetime.datetime.now().isoformat(),
                "sound_level": filtered_sound_level,
                "threshold": args.threshold,
                "hysteresis": args.hysteresis,
                "output_state": "HIGH" if output and output.is_active else "LOW" if output else "N/A"
            }
            logging.info(json.dumps(data))

            if time.time() - last_cloud_upload_attempt >= 10.0:
                try:
                    data_json = json.dumps(data).encode('utf-8')
                    req = urllib.request.Request(args.cloud_url, data=data_json,
                                                 headers={'Content-Type': 'application/json'})
                    with urllib.request.urlopen(req, timeout=10) as response:
                        if 200 <= response.status < 300:
                            logging.info("Data uploaded to cloud successfully.")
                            last_cloud_upload = time.time()
                            cloud_upload_retries = 0
                        else:
                            logging.error(f"Cloud upload failed with status {response.status}.")
                            cloud_upload_retries += 1
                except urllib.error.URLError as e:
                    logging.error(f"Cloud upload network error: {e}")
                    cloud_upload_retries += 1
                except Exception as e:
                    logging.error(f"Cloud upload error: {e}")
                    cloud_upload_retries += 1

                if cloud_upload_retries > max_retries:
                    logging.warning("Max cloud upload retries reached. Disabling cloud upload.")
                    cloud_upload_retries = 0
                else:
                    last_cloud_upload_attempt = time.time()

            time.sleep(1.0 / args.sample_rate)

    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if spi:
            try:
                spi.close()
                logging.info("SPI closed.")
            except Exception as e:
                logging.error(f"Error closing SPI: {e}")
        if output:
            try:
                output.close()
                logging.info("Output pin closed.")
            except Exception as e:
                logging.error(f"Error closing output pin: {e}")
        logging.info("Exiting Sound Level Monitoring System")

if __name__ == "__main__":
    main()

