#!/usr/bin/env python3
"""
LoadCellReader for Raspberry Pi 4 Model B.

Reads a 10-bit analog value from an MCP3002 ADC over SPI0/CE0
and converts it to a weight estimate.

Wiring:
  MCP3002 VDD  -> 3.3 V (Pin 1)
  MCP3002 VREF -> 3.3 V (Pin 1)
  MCP3002 AGND -> GND  (Pin 9)
  MCP3002 DGND -> GND  (Pin 9)
  MCP3002 CLK  -> GPIO11 (SCLK, Pin 23)
  MCP3002 DOUT -> GPIO9  (MISO,  Pin 21)
  MCP3002 DIN  -> GPIO10 (MOSI, Pin 19)
  MCP3002 CS   -> GPIO8  (CE0,   Pin 24)
  MCP3002 CH0  -> Load Cell (via 10k-20k voltage divider)

SPI: bus 0, device 0, max_speed_hz=50 kHz, mode=0b00, bits_per_word=8.
"""

import signal
import sys
import time

import spidev


class LoadCellReader:
    """Reads weight from an MCP3002 ADC over SPI and prints it."""

    def __init__(self, spi_bus: int = 0, spi_device: int = 0,
                 max_speed_hz: int = 50000, mode: int = 0b00,
                 bits_per_word: int = 8) -> None:
        self.spi_bus = spi_bus
        self.spi_device = spi_device
        self.max_speed_hz = max_speed_hz
        self.mode = mode
        self.bits_per_word = bits_per_word
        self.spi: spidev.SpiDev | None = None

    def open(self) -> None:
        """Open the SPI device; raise on failure."""
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(self.spi_bus, self.spi_device)
            self.spi.max_speed_hz = self.max_speed_hz
            self.spi.mode = self.mode
            self.spi.bits_per_word = self.bits_per_word
        except (OSError, IOError) as exc:
            self.spi = None
            raise RuntimeError(
                f"Failed to open SPI{self.spi_bus}.{self.spi_device}: {exc}"
            ) from exc

    def read_raw_data(self) -> int:
        """Read a 10-bit value from the MCP3002 and return it as an int."""
        if self.spi is None:
            raise RuntimeError("SPI device is not open")
        try:
            response = self.spi.xfer2([0x01, 0x80, 0x00])
        except (OSError, IOError) as exc:
            raise RuntimeError(f"SPI transfer failed: {exc}") from exc
        return self.extract_10bit(response)

    @staticmethod
    def extract_10bit(response: list[int]) -> int:
        """Extract the 10-bit value from the 3-byte SPI response."""
        if len(response) < 3:
            raise ValueError(f"Response too short: {response}")
        return ((response[1] & 0x03) << 8) | response[2]

    def convert_to_weight(self, raw_data: int) -> float:
        """Convert raw ADC value to a weight estimate (kg)."""
        return float(raw_data) * (5.0 / 1023.0)

    def close(self) -> None:
        """Close the SPI device if open."""
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception:
                pass
            finally:
                self.spi = None


def main() -> None:
    reader = LoadCellReader()
    running = True

    def _handle_signal(signum, _frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        reader.open()
        print("LoadCellReader started. Press Ctrl+C to stop.")
        while running:
            try:
                raw_data = reader.read_raw_data()
                weight = reader.convert_to_weight(raw_data)
                print(f"Weight: {weight:.2f} kg")
            except RuntimeError as exc:
                print(f"Error: {exc}", file=sys.stderr)
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except RuntimeError as exc:
        print(f"Fatal error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        reader.close()
        print("SPI device closed.")


if __name__ == "__main__":
    main()

