import spidev
import time
import datetime
import csv
import socket
import json
import signal
import sys
from gpiozero import Buzzer

# Configuration
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1000000
ADC_CHANNELS = {
    "MQ-4": 0,
    "MQ-7": 1,
    "MQ-135": 2
}
ALERT_THRESHOLDS = {
    "MQ-4": 50.0,
    "MQ-7": 25.0,
    "MQ-135": 100.0
}
BUZZER_PIN = 17
SERVER_IP = "127.0.0.1"
SERVER_PORT = 12345
CALIBRATION_READINGS = 10
CALIBRATION_DELAY = 3
DATA_LOGGING_INTERVAL = 60

# Global state
spi = None
buzzer = None
running = True

def signal_handler(sig, frame):
    global running
    running = False

def init_spi():
    global spi
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        print("SPI initialized successfully.")
    except Exception as e:
        print(f"Error initializing SPI: {e}")
        sys.exit(1)

def read_adc(channel):
    if not 0 <= channel <= 7:
        raise ValueError("ADC channel must be between 0 and 7")
    try:
        # MCP3008 single-ended mode command: start bit, single/diff=1, channel bits
        cmd = [1, (8 + channel) << 4, 0]
        reply = spi.xfer2(cmd)
        # 10-bit result: bits 0-1 of reply[1] and all of reply[2]
        value = ((reply[1] & 0x03) << 8) | reply[2]
        return value
    except Exception as e:
        print(f"SPI communication error on channel {channel}: {e}")
        return None

def calculate_resistance(adc_value):
    if adc_value is None:
        return None
    # MCP3008 outputs 10-bit (0-1023). Assuming 3.3V reference, 1023 = 3.3V
    voltage = (adc_value / 1023.0) * 3.3
    # Sensor resistance formula (simplified for MQ-4, MQ-7, MQ-135)
    # For MQ-4: R = 10k + (10k * (1 + A/B)) where A = 10^(0.034*V), B = 10^(0.042*V)
    # For MQ-7: R = 10k + (10k * (1 + A/B)) where A = 10^(0.034*V), B = 10^(0.042*V)
    # For MQ-135: R = 10k + (10k * (1 + A/B)) where A = 10^(0.034*V), B = 10^(0.042*V)
    # Using simplified formula: R = 10k * (1 + 10^(0.034*V))
    if voltage <= 0:
        return None
    resistance = 10000.0 * (1.0 + 10.0 ** (0.034 * voltage))
    return resistance

