import time
import signal
import sys
import board
import busio
import adafruit_lsm303_accel
import adafruit_lsm303dlh_mag
import Adafruit_ADS1x15
import pigpio

try:
    from motor_driver import MotorController
    from sensor_manager import SensorManager
except ImportError as e:
    print(f"Error importing required libraries: {e}")
    print("Please ensure these modules are installed and available in the Python path.")
    sys.exit(1)

# Constants
MOTOR_DIR_PIN = 20
MOTOR_STEP_PIN = 21
MOTOR_MS0_PIN = 14
MOTOR_MS1_PIN = 15
MOTOR_CW = True
MOTOR_CCW = False
MOTOR_RESOLUTION = {
    'Full': (False, False),
    'Half': (True, False),
    '1/4': (False, True),
    '1/8': (True, True)
}

ADC_GAIN = 1
ADC_CHANNEL = 0

# Global state for signal handling
_running = True
_pi = None

def signal_handler(sig, frame):
    global _running
    print(f"\nReceived signal {sig}, shutting down gracefully...")
    _running = False

def initialize_motor(pi, dir_pin, step_pin, ms0_pin, ms1_pin, resolution='Full', cw=True):
    if resolution not in MOTOR_RESOLUTION:
        raise ValueError(f"Invalid motor resolution: {resolution}")
    ms0, ms1 = MOTOR_RESOLUTION[resolution]
    return MotorController(pi, dir_pin, step_pin, ms0_pin, ms1_pin, cw, ms0, ms1)

def initialize_sensors(i2c):
    try:
        accelerometer = adafruit_lsm303_accel.LSM303_Accel(i2c)
        magnetometer = adafruit_lsm303dlh_mag.LSM303DLH_Mag(i2c)
        return SensorManager(accelerometer, magnetometer)
    except Exception as e:
        print(f"Error initializing sensors: {e}")
        return None

def initialize_adc(i2c, address=0x48, gain=1, channel=0):
    try:
        adc = Adafruit_ADS1x15.ADS1015(i2c=i2c, address=address)
        return adc, channel, gain
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None, None, None

def read_adc_voltage(adc, channel, gain):
    try:
        return adc.read_adc(channel, gain=gain)
    except Exception as e:
        print(f"Error reading ADC: {e}")
        return None

def map_voltage_to_duty_cycle(voltage, voltage_range=(0, 3.3), duty_cycle_range=(0, 255)):
    if voltage is None:
        return None
    v_min, v_max = voltage_range
    dc_min, dc_max = duty_cycle_range
    return int((voltage - v_min) * (dc_max - dc_min) / (v_max - v_min) + dc_min)

def apply_pwm_duty_cycle(motor, duty_cycle, frequency=500):
    if motor is None or duty_cycle is None:
        return
    try:
        motor.set_pwm_frequency(frequency)
        motor.set_pwm_duty_cycle(duty_cycle)
    except Exception as e:
        print(f"Error setting PWM duty cycle: {e}")

def read_sensor_data(sensor_manager):
    if sensor_manager is None:
        return None, None, None, None
    try:
        acceleration = sensor_manager.get_acceleration()
        inclination = sensor_manager.get_inclination()
        magnetic_field = sensor_manager.get_magnetic_field()
        heading = sensor_manager.get_heading()
        return acceleration, inclination, magnetic_field, heading
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None, None

def print_sensor_data(acceleration, inclination, magnetic_field, heading):
    if all(v is not None for v in [acceleration, inclination, magnetic_field, heading]):
        print(f"Acceleration: {acceleration[0]:.2f}, {acceleration[1]:.2f}, {acceleration[2]:.2f} m/s^2")
        print(f"Inclination: XZ: {inclination[0]:.2f} deg, YZ: {inclination[1]:.2f} deg")
        print(f"Magnetic Field: {magnetic_field[0]:.2f}, {magnetic_field[1]:.2f}, {magnetic_field[2]:.2f} gauss")
        print(f"Heading: {heading[0]:.2f}, {heading[1]:.2f} deg")

def main():
    global _pi
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    _pi = pigpio.pi()
    if not _pi.connected:
        print("Failed to connect to pigpio daemon. Is pigpiod running?")
        sys.exit(1)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        _pi.stop()
        sys.exit(1)

    motor = None
    sensor_manager = None
    adc = None
    adc_channel = None
    adc_gain = None

    try:
        motor = initialize_motor(_pi, MOTOR_DIR_PIN, MOTOR_STEP_PIN, MOTOR_MS0_PIN, MOTOR_MS1_PIN, 'Full', MOTOR_CCW)
        sensor_manager = initialize_sensors(i2c)
        adc, adc_channel, adc_gain = initialize_adc(i2c, address=0x48, gain=ADC_GAIN, channel=ADC_CHANNEL)

        if motor is None:
            print("Motor initialization failed.")
            return

        while _running:
            voltage = read_adc_voltage(adc, adc_channel, adc_gain)
            duty_cycle = map_voltage_to_duty_cycle(voltage, voltage_range=(0, 3.3), duty_cycle_range=(0, 255))
            apply_pwm_duty_cycle(motor, duty_cycle, frequency=500)

            acceleration, inclination, magnetic_field, heading = read_sensor_data(sensor_manager)
            print_sensor_data(acceleration, inclination, magnetic_field, heading)

            time.sleep(1)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if motor is not None:
            try:
                motor.set_pwm_duty_cycle(0)
            except Exception:
                pass
        if _pi is not None and _pi.connected:
            _pi.stop()
        print("Cleanup complete. Exiting.")

if __name__ == "__main__":
    main()

