import sys

SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1350000
ADC_CHANNEL = 0
NUM_READINGS = 5
DELAY_SECONDS = 2


def read_mcp3008(spi, channel):
    """Read a single-ended channel from an MCP3008 ADC.

    Returns the 10-bit raw value (0-1023), or raises on SPI error.
    """
    if not 0 <= channel <= 7:
        raise ValueError(f"Invalid MCP3008 channel {channel}; must be 0-7")
    # MCP3008 single-ended read: start bit, config byte, padding byte
    tx = [0x01, (0x08 | channel) << 4, 0x00]
