SPI_DEVICE = 0
SPI_SPEED_HZ = 1350000
WATERING_PIN = 18
DRY_THRESHOLD = 450
PUMP_RUN_SECONDS = 2


class SmartGardenController:
    """Reads soil moisture from an MCP3008 ADC and controls a watering pump."""

    def __init__(self, spi_bus, spi_device, spi_speed_hz, watering_pin):
        self.spi_bus = spi_bus
        self.spi_device = spi_device
        self.spi_speed_hz = spi_speed_hz
        self.watering_pin = watering_pin
        self.spi = None
        self._setup_gpio()
        self._setup_spi()

    def _setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.watering_pin, GPIO.OUT, initial=GPIO.LOW)
        except Exception as e:
            logging.error("GPIO setup failed: %s", e)
            raise

    def _setup_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(self.spi_bus, self.spi_device)
            self.spi.max_speed_hz = self.spi_speed_hz
            self.spi.mode = 0
        except Exception as e:
            logging.error("SPI setup failed: %s", e)
            self._cleanup_gpio()
            raise

