import RPi.GPIO as GPIO
import time
import logging
import argparse
import queue
import threading
import spidev
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.stop_event = threading.Event()
        self.spi = None
        self._lock = threading.Lock()
        self._initialized = False

        if self.sensor_type == 'digital':
            if not self.gpio_pins:
                logging.error(f"Sensor {self.sensor_id}: No GPIO pins provided for digital sensor.")
                return
            try:
                GPIO.setmode(GPIO.BCM)
                for pin in self.gpio_pins:
                    GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
                self._initialized = True
                logging.info(f"Sensor {self.sensor_id}: Digital sensor initialized on GPIO pins {self.gpio_pins}.")
            except Exception as e:
                logging.error(f"Sensor {self.sensor_id}: Failed to initialize digital sensor on GPIO pins {self.gpio_pins}: {e}")
        elif self.sensor_type == 'analog':
            if not self.channels:
                logging.error(f"Sensor {self.sensor_id}: No MCP3008 channels provided for analog sensor.")
                return
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
                self._initialized = True
                logging.info(f"Sensor {self.sensor_id}: Analog sensor initialized on MCP3008 channels {self.channels}.")
            except Exception as e:
                logging.error(f"Sensor {self.sensor_id}: Failed to initialize analog sensor on channels {self.channels}: {e}")
                if self.spi:
                    self.spi.close()
                    self.spi = None
        else:
            logging.error(f"Sensor {self.sensor_id}: Invalid sensor type '{self.sensor_type}'. Must be 'digital' or 'analog'.")

    def read_digital(self):
        try:
            return GPIO.input(self.gpio_pins[0])
        except Exception as e:
            logging.error(f"Sensor {self.sensor_id}: Error reading digital sensor on GPIO pin {self.gpio_pins[0]}: {e}")
            return None

    def read_analog(self):
        if not self.spi:
            logging.error(f"Sensor {self.sensor_id}: SPI device not initialized.")
            return None
        try:
            for ch in self.channels:
                if ch < 0 or ch > 7:
                    logging.error(f"Sensor {self.sensor_id}: Invalid MCP3008 channel {ch}. Must be 0-7.")
                    return None
                cmd = [1, (8 + ch) << 4, 0]
                reply = self.spi.xfer2(cmd)
                value = ((reply[1] & 3) << 8) + reply[2]
                return value
        except Exception as e:
            logging.error(f"Sensor {self.sensor_id}: Error reading analog sensor on MCP3008 channel {self.channels}: {e}")
            return None

    def detect_sound(self):
        if self.sensor_type == 'digital':
            return self.read_digital() == 1
        elif self.sensor_type == 'analog':
            return self.read_analog() >= self.threshold
        return False

    def run(self):
        if not self._initialized:
            logging.error(f"Sensor {self.sensor_id}: Sensor not initialized. Exiting run loop.")
            return
        try:
            while not self.stop_event.is_set():
                if self.detect_sound():
                    timestamp = time.time()
                    log_message = f"Sensor {self.sensor_id}: Sound detected at {timestamp}"
                    if self.log_queue:
                        try:
                            self.log_queue.put((timestamp, log_message))
                        except Exception as e:
                            logging.error(f"Sensor {self.sensor_id}: Error putting log message in queue: {e}")
                    else:
                        logging.info(log_message)
                    time.sleep(0.1)
                time.sleep(1 / self.sample_rate)
        except Exception as e:
            logging.error(f"Sensor {self.sensor_id}: Error in run loop: {e}")
        finally:
            if self.sensor_type == 'digital':
                try:
                    for pin in self.gpio_pins:
                        GPIO.cleanup(pin)
                    logging.info(f"Sensor {self.sensor_id}: GPIO pins cleaned up.")
                except Exception as e:
                    logging.error(f"Sensor {self.sensor_id}: Error cleaning up GPIO pins: {e}")
            elif self.sensor_type == 'analog':
                if self.spi:
                    try:
                        self.spi.close()
                        logging.info(f"Sensor {self.sensor_id}: SPI device closed.")
                    except Exception as e:
                        logging.error(f"Sensor {self.sensor_id}: Error closing SPI device: {e}")

    def stop(self):
        self.stop_event.set()

def log_worker(log_queue, log_file):
    try:
        while True:
            try:
                timestamp, message = log_queue.get(timeout=1)
                logging.info(message)
                with open(log_file, 'a') as f:
                    f.write(f"{timestamp} - {message}\n")
            except queue.Empty:
                continue
            except Exception as e:
                logging.error(f"Error in log worker: {e}")
    except Exception as e:
        logging.error(f"Fatal error in log worker: {e}")

def main():
    parser = argparse.ArgumentParser(description="Raspberry Pi Sound Sensor System")
    parser.add_argument("--sensor_type", required=True, choices=['digital', 'analog'], help="Sensor type: digital or analog")
    parser.add_argument("--threshold", type=int, required=True, help="Sound level threshold (digital: 0/1, analog: ADC value)")
    parser.add_argument("--sample_rate", type=float, required=True, help="Sampling rate in Hz")
    parser.add_argument("--log_file", required=True, help="Path to the log file")
    parser.add_argument("--gpio_pins", nargs='+', type=int, help="GPIO pins for digital sensors")
    parser.add_argument("--channels", nargs='+', type=int, help="MCP3008 channels for analog sensors")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed in Hz")
    parser.add_argument("--sensor_ids", nargs='+', required=True, help="Unique IDs for each sensor")
    args = parser.parse_args()

    if args.sensor_type == 'digital' and not args.gpio_pins:
        print("Error: --gpio_pins is required for digital sensors.")
        sys.exit(1)
    if args.sensor_type == 'analog' and not args.channels:
        print("Error: --channels is required for analog sensors.")
        sys.exit(1)

    log_queue = queue.Queue()
    log_thread = threading.Thread(target=log_worker, args=(log_queue, args.log_file), daemon=True)
    log_thread.start()

    sensors = []
    threads = []
    for i, sensor_id in enumerate(args.sensor_ids):
        gpio_pins = [args.gpio_pins[i]] if args.gpio_pins else None
        channels = [args.channels[i]] if args.channels else None
        sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, gpio_pins, channels, args.spi_speed, log_queue)
        sensors.append(sensor)
        thread = threading.Thread(target=sensor.run, daemon=True)
        threads.append(thread)
        thread.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Shutting down...")
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join(timeout=2)
        log_queue.put((None, None))
        log_thread.join(timeout=2)
        logging.info("Shutdown complete.")

if __name__ == "__main__":
    main()

