import time
import signal
import sys
import board
import busio
import adafruit_max30102

LOG_FILE = 'heart_rate_log.txt'
WINDOW_SECONDS = 4.0
SAMPLE_INTERVAL = 1.0

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

def _format_timestamp():
    return time.strftime('%Y-%m-%dT%H:%M:%S')

def _format_value(value):
    if isinstance(value, (int, float)):
        return str(value)
    try:
        return str(int(value))
    except (TypeError, ValueError):
        return 'N/A'

def _log_reading(timestamp, heart_rate, spo2):
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(f'{timestamp},{heart_rate},{spo2}\n')
    except OSError as e:
        print(f'[WARN] Failed to write log: {e}', file=sys.stderr)

def _print_reading(timestamp, heart_rate, spo2):
    print(f'{timestamp}  HR={heart_rate} bpm  SpO2={spo2} %')

def _init_sensor():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f'[ERROR] I2C bus init failed: {e}', file=sys.stderr)
        sys.exit(1)
    try:
        sensor = adafruit_max30102.MAX30102(i2c, address=0x57)
    except ValueError as e:
        print(f'[ERROR] MAX30102 not found at 0x57: {e}', file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f'[ERROR] Sensor init failed: {e}', file=sys.stderr)
        sys.exit(1)
    return sensor

def _compute_heart_rate(sensor, window_seconds):
    """Peak-counting heart-rate estimator. Returns (hr_bpm, spo2_pct) or (None, None)."""
    ir_samples = []
    red_samples = []
    deadline = time.monotonic() + window_seconds
    while time.monotonic() < deadline:
        try:
            ir = sensor.ir
            red = sensor.red
        except Exception as e:
            print(f'[WARN] Transient read error: {e}', file=sys.stderr)
            time.sleep(0.05)
            continue
        if ir is not None and red is not None:
            ir_samples.append(ir)
            red_samples.append(red)
        time.sleep(0.05)

    if not ir_samples:
        return None, None

    # Peak-counting over the IR channel
    threshold = sum(ir_samples) / len(ir_samples)
    peaks = 0
    rising = False
    for s in ir_samples:
        if s > threshold and not rising:
            peaks += 1
            rising = True
        elif s <= threshold:
            rising = False
    # 2 peaks per full cycle => beats/window
    beats = peaks / 2.0
    hr_bpm = int(beats / (window_seconds / 60.0))
    # Spo2 estimation: assume 0-100% linearly from threshold
    spo2_pct = int(max(0, min(100, (threshold / 3000.0) * 100.0)))
    return hr_bpm, spo2_pct

def main():
    signal.signal(signal.SIGINT, _handle_sigint)
    sensor = _init_sensor()
    print('MAX30102 heart-rate logger started. Press Ctrl-C to stop.')
    try:
        while _running:
            timestamp = _format_timestamp()
            hr, spo2 = _compute_heart_rate(sensor, WINDOW_SECONDS)
            if hr is not None and spo2 is not None:
                _log_reading(timestamp, _format_value(hr), _format_value(spo2))
                _print_reading(timestamp, _format_value(hr), _format_value(spo2))
            else:
                print(f'{timestamp}  Sensor read failed, skipping.', file=sys.stderr)
            time.sleep(SAMPLE_INTERVAL)
    finally:
        print('\nShutting down...')

if __name__ == '__main__':
    main()

