import cv2
import signal
import sys
import time
from picamera2 import Picamera2

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera():
    """Initializes the Picamera2 camera with 640x480 resolution and BGR888 format."""
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"format": 'BGR888', "size": (640, 480)}
        )
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None

def load_cascades():
    """Loads Haar cascade classifiers for face and eye detection."""
    try:
        face_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
        eye_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_eye.xml')
        if face_cascade.empty() or eye_cascade.empty():
            raise RuntimeError("Failed to load one or more cascade classifiers.")
        return face_cascade, eye_cascade
    except Exception as e:
        print(f"Error loading cascade classifiers: {e}", file=sys.stderr)
        return None, None

def detect_faces_and_eyes(image, face_cascade, eye_cascade):
    """Detects faces and eyes in a given image."""
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))

    for (x, y, w, h) in faces:
        cv2.rectangle(image, (x, y), (x + w, y + h), (0, 255, 0), 2)
        roi_gray = gray[y:y+h, x:x+w]
        roi_color = image[y:y+h, x:x+w]
        eyes = eye_cascade.detectMultiScale(roi_gray, scaleFactor=1.1, minNeighbors=3, minSize=(20, 20))
        for (ex, ey, ew, eh) in eyes:
            cv2.rectangle(roi_color, (ex, ey), (ex+ew, ey+eh), (0, 0, 255), 2)

def main():
    """Main function to run face and eye detection."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    picam2 = initialize_camera()
    if picam2 is None:
        return

    face_cascade, eye_cascade = load_cascades()
    if face_cascade is None or eye_cascade is None:
        picam2.stop()
        return

    cv2.namedWindow("Face and Eye Detection", cv2.WINDOW_NORMAL)

    try:
        while _running:
            frame = picam2.capture_array()
            if frame is None:
                print("Warning: Captured empty frame, skipping...", file=sys.stderr)
                continue

            detect_faces_and_eyes(frame, face_cascade, eye_cascade)
            cv2.imshow("Face and Eye Detection", frame)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break
    except Exception as e:
        print(f"An error occurred during execution: {e}", file=sys.stderr)
    finally:
        cv2.destroyAllWindows()
        try:
            picam2.stop()
        except Exception as e:
            print(f"Error stopping camera: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()

