        blob = cv2.dnn.blobFromImage(image, 1.0, (224, 224), (0, 0, 0), swapRB=False, crop=False)
        net.setInput(blob)
        return net.forward()
    except Exception as e:
        logging.error(f'Error during inference: {e}')
        return None

def indicate_bird(led_pin):
    try:
        led = OutputDevice(led_pin)
        led.on()
        time.sleep(1)
        led.off()
        led.close()
    except Exception as e:
        logging.error(f'Error controlling LED: {e}')

def control_door(config, door_state):
    try:
        if not config.get('gpio_door_control'):
            return door_state

        if door_state:
            device = OutputDevice(config['gpio_door_pin'])
            device.on()
            device.close()
            logging.info('Door opened.')
            return False
        else:
            device = OutputDevice(config['gpio_door_pin'])
            device.off()
            device.close()
            logging.info('Door closed.')
            return True
    except Exception as e:
        logging.error(f'Error controlling door: {e}')
        return door_state

