import time
import sqlite3
import logging
import signal
import sys
import os

try:
    import board
    import busio
    import adafruit_bmp280
    import adafruit_bme280
    import adafruit_ms8607
except ImportError as e:
    print(f"Missing dependency: {e}")
    sys.exit(0)

CONFIG_FILE = "config.txt"
ERROR_LOG = "error.log"
DATABASE_FILE = "wildlife_data.db"

logging.basicConfig(
    filename=ERROR_LOG,
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

running = True

def signal_handler(sig, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)

def load_config(config_file):
    config = {}
    try:
        with open(config_file, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    continue
                key, value = line.split("=", 1)
                config[key.strip()] = value.strip()
    except FileNotFoundError:
        logging.error(f"Config file not found: {config_file}")
        print(f"Error: Config file not found: {config_file}")
        return None
    except Exception as e:
        logging.error(f"Error loading config: {e}")
        print(f"Error loading config: {e}")
        return None
    return config

def init_sensor(sensor_type, sensor_id, sensor_address):
    try:
        address = int(sensor_address, 0)
    except ValueError:
        logging.error(f"Invalid address {sensor_address} for sensor {sensor_id}")
        return None
    if sensor_type == "BMP280":
        try:
            sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c, address=address)
            chip_id = sensor._read_byte(0xD0)
            if chip_id != 0x58:
                logging.error(f"BMP280 chip ID mismatch at 0x{address:02X}: got 0x{chip_id:02X}")
                return None
            return sensor
        except Exception as e:
            logging.error(f"BMP280 init failed at 0x{address:02X}: {e}")
            return None
    elif sensor_type == "BME280":
        try:
            sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c, address=address)
            chip_id = sensor._read_byte(0xD0)
            if chip_id != 0x60:
                logging.error(f"BME280 chip ID mismatch at 0x{address:02X}: got 0x{chip_id:02X}")
                return None
            return sensor
        except Exception as e:
            logging.error(f"BME280 init failed at 0x{address:02X}: {e}")
            return None
    elif sensor_type == "MS8607":
        try:
            sensor = adafruit_ms8607.MS8607(i2c, address=address)
            return sensor
        except Exception as e:
            logging.error(f"MS8607 init failed at 0x{address:02X}: {e}")
            return None
    else:
        logging.error(f"Unknown sensor type: {sensor_type}")
        return None

def read_sensor(sensor, sensor_type):
    try:
        if sensor_type == "BMP280":
            return sensor.pressure, sensor.temperature, None
        elif sensor_type == "BME280":
            return sensor.pressure, sensor.temperature, sensor.humidity
        elif sensor_type == "MS8607":
            return sensor.pressure, sensor.temperature, sensor.humidity
        else:
            return None, None, None
    except Exception as e:
        logging.error(f"Read error: {e}")
        return None, None, None

def validate_data(pressure, temperature, humidity, sensor_type):
    if pressure is None or temperature is None:
        return False
    if not (70000 <= pressure <= 110000):
        logging.warning(f"Invalid pressure {pressure} Pa (sensor type: {sensor_type})")
        return False
    if not (-20 <= temperature <= 50):
        logging.warning(f"Invalid temperature {temperature} C (sensor type: {sensor_type})")
        return False
    if humidity is not None and not (0 <= humidity <= 100):
        logging.warning(f"Invalid humidity {humidity} % (sensor type: {sensor_type})")
        return False
    return True

def store_data(timestamp, sensor_type, sensor_id, pressure, temperature, humidity):
    try:
        conn = sqlite3.connect(DATABASE_FILE)
        cursor = conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT,
                sensor_type TEXT,
                sensor_id TEXT,
                pressure_pa REAL,
                temperature_c REAL,
                humidity_percent REAL
            )
        """)
        cursor.execute("""
            INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent)
            VALUES (?, ?, ?, ?, ?, ?)
        """, (timestamp, sensor_type, sensor_id, pressure, temperature, humidity))
        conn.commit()
        conn.close()
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")

def main():
    global running
    config = load_config(CONFIG_FILE)
    if config is None:
        print("Failed to load config. Exiting.")
        return
    try:
        sampling_interval = int(config.get("Sampling_Interval_Seconds", "60"))
    except ValueError:
        logging.error("Invalid Sampling_Interval_Seconds in config")
        sampling_interval = 60
    sensors = []
    for i in range(1, 4):
        sensor_type = config.get(f"Sensor{i}_Type")
        sensor_address = config.get(f"Sensor{i}_Address")
        sensor_id = config.get(f"Sensor{i}_ID")
        if sensor_type and sensor_address and sensor_id:
            sensor = init_sensor(sensor_type, sensor_id, sensor_address)
            if sensor:
                sensors.append((sensor, sensor_type, sensor_id))
    if not sensors:
        print("No sensors initialized. Exiting.")
        return
    print(f"Initialized {len(sensors)} sensor(s). Sampling every {sampling_interval}s.")
    while running:
        timestamp = time.strftime("%Y-%m-%dT%H:%M:%S")
        for sensor, sensor_type, sensor_id in sensors:
            pressure, temperature, humidity = read_sensor(sensor, sensor_type)
            if validate_data(pressure, temperature, humidity, sensor_type):
                store_data(timestamp, sensor_type, sensor_id, pressure, temperature, humidity)
        for _ in range(sampling_interval):
            if not running:
                break
            time.sleep(1)
    print("Shutting down.")

if __name__ == "__main__":
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        logging.error(f"I2C init failed: {e}")
        print(f"I2C init failed: {e}")
        sys.exit(0)
    main()

