import time
import signal
import sys
import random
import board
import busio
import adafruit_amg88xx
from gpiozero import Buzzer

# Configuration
BUZZER_PIN = 17
I2C_ADDRESS = 0x69
THRESHOLD_TEMP = 30.0
POLL_INTERVAL = 0.1
ALERT_DURATION = 1.0

# Global resources for cleanup
buzzer = None
i2c = None
sensor = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def init_sensor():
    """Initialize the AMG8833 thermal camera sensor. Returns sensor or None."""
    global i2c, sensor
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_amg88xx.AMG88XX(i2c, addr=I2C_ADDRESS)
        # Force a read to confirm the sensor is responding
        _ = sensor.pixels
        print(f"AMG8833 thermal camera initialized at I2C address 0x{I2C_ADDRESS:02X}.")
        return sensor
    except (ValueError, OSError, RuntimeError) as e:
        print(f"Warning: AMG8833 not found at 0x{I2C_ADDRESS:02X}: {e}")
        print("Falling back to simulated thermal data.")
        sensor = None
        return None


def simulate_thermal_data():
    """Generate simulated 8x8 thermal data."""
    return [[random.uniform(20.0, 45.0) for _ in range(8)] for _ in range(8)]


def detect_human(thermal_data):
    """Detect a human presence based on temperature threshold."""
    if thermal_data is None:
        return False
    for row in thermal_data:
        for temp in row:
            if temp > THRESHOLD_TEMP:
                return True
    return False


def trigger_alert(buzzer_obj):
    """Trigger the buzzer alert for a set duration."""
    if buzzer_obj is None:
        return
    try:
        buzzer_obj.on()
        time.sleep(ALERT_DURATION)
        buzzer_obj.off()
    except Exception as e:
        print(f"Error during buzzer alert: {e}")


def cleanup():
    """Release all resources."""
    global buzzer, i2c
    if buzzer is not None:
        try:
            buzzer.off()
            buzzer.close()
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
    print("Resources cleaned up.")


def main():
    global buzzer, sensor, running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize buzzer
    try:
        buzzer = Buzzer(BUZZER_PIN)
        print(f"Buzzer initialized on GPIO{BUZZER_PIN}.")
    except Exception as e:
        print(f"Fatal: Could not initialize buzzer on GPIO{BUZZER_PIN}: {e}")
        sys.exit(1)

    # Initialize thermal sensor
    sensor = init_sensor()

    print("Thermal security system started. Press Ctrl+C to exit.")

    try:
        while running:
            try:
                if sensor is not None:
                    thermal_data = sensor.pixels
                else:
                    thermal_data = simulate_thermal_data()

                if detect_human(thermal_data):
                    print("Human detected! Triggering alert.")
                    trigger_alert(buzzer)
                else:
                    print("No human detected.")

            except (OSError, RuntimeError) as e:
                print(f"I2C bus error: {e}")
                # Attempt to reinitialize sensor
                sensor = init_sensor()

            time.sleep(POLL_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

