        sensor = None
        return None


def simulate_thermal_data():
    """Generate simulated 8x8 thermal data."""
    return [[random.uniform(20.0, 45.0) for _ in range(8)] for _ in range(8)]


def detect_human(thermal_data):
    """Detect a human presence based on temperature threshold."""
    if thermal_data is None:
        return False
    for row in thermal_data:
        for temp in row:
            if temp > THRESHOLD_TEMP:
                return True
    return False


def trigger_alert(buzzer_obj):
    """Trigger the buzzer alert for a set duration."""
    if buzzer_obj is None:
        return
    try:
        buzzer_obj.on()
        time.sleep(ALERT_DURATION)
        buzzer_obj.off()
    except Exception as e:
        print(f"Error during buzzer alert: {e}")


def cleanup():
    """Release all resources."""
    global buzzer, i2c
    if buzzer is not None:
        try:
            buzzer.off()
            buzzer.close()
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
    print("Resources cleaned up.")


def main():
    global buzzer, sensor, running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize buzzer
    try:
        buzzer = Buzzer(BUZZER_PIN)
        print(f"Buzzer initialized on GPIO{BUZZER_PIN}.")
    except Exception as e:
        print(f"Fatal: Could not initialize buzzer on GPIO{BUZZER_PIN}: {e}")
        sys.exit(1)

