    sensor = init_sensor()

    print("Thermal security system started. Press Ctrl+C to exit.")

    try:
        while running:
            try:
                if sensor is not None:
                    thermal_data = sensor.pixels
                else:
                    thermal_data = simulate_thermal_data()

                if detect_human(thermal_data):
                    print("Human detected! Triggering alert.")
                    trigger_alert(buzzer)
                else:
                    print("No human detected.")

            except (OSError, RuntimeError) as e:
                print(f"I2C bus error: {e}")
                # Attempt to reinitialize sensor
                sensor = init_sensor()

            time.sleep(POLL_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

