import argparse
import json
import logging
import os
import queue
import signal
import threading
import time
from datetime import datetime

import numpy as np
from picamera2 import Picamera2

try:
    from tflite_runtime.interpreter import Interpreter
    try:
        from edgetpu.interpreter import Interpreter as EdgeTpuInterpreter
        EDGETPU_AVAILABLE = True
    except ImportError:
        EDGETPU_AVAILABLE = False
except ImportError:
    try:
        from tensorflow.lite.python.interpreter import Interpreter
        EDGETPU_AVAILABLE = False
    except ImportError:
        Interpreter = None
        EDGETPU_AVAILABLE = False


GESTURE_LABELS = [
    "Open Hand",
    "Closed Fist",
    "Pointing Up",
    "Pointing Down",
    "Peace Sign",
]


class GestureRecognizer:
    def __init__(self, model_path, use_coral=False):
        self.model_path = model_path
        self.use_coral = use_coral
        self.interpreter = None
        self.input_details = None
        self.output_details = None
        self._load_model()

    def _load_model(self):
        if Interpreter is None:
            raise RuntimeError("No TFLite interpreter available.")
        if not os.path.isfile(self.model_path):
            raise FileNotFoundError(f"Model file not found: {self.model_path}")
        if self.use_coral and EDGETPU_AVAILABLE:
            try:
                self.interpreter = EdgeTpuInterpreter(model_path=self.model_path)
                logging.info("Loaded TFLite model with Edge TPU delegate.")
            except Exception as e:
                logging.warning(f"Edge TPU unavailable ({e}); falling back to CPU.")
                self.use_coral = False
                self.interpreter = Interpreter(model_path=self.model_path)
        else:
            self.interpreter = Interpreter(model_path=self.model_path)
        self.interpreter.allocate_tensors()
        self.input_details = self.interpreter.get_input_details()
        self.output_details = self.interpreter.get_output_details()
        logging.info(f"Loaded TFLite model from {self.model_path}.")

    def preprocess_frame(self, frame):
        try:
            input_shape = self.input_details[0]["shape"]
            target_h, target_w = input_shape[1], input_shape[2]
            resized = np.resize(frame, (target_h, target_w, 3))
            normalized = (resized.astype(np.float32) / 127.5) - 1.0
            return normalized
        except Exception as e:
            logging.error(f"Error preprocessing frame: {e}")
            return None

    def recognize_gesture(self, frame):
        try:
            input_data = self.preprocess_frame(frame)
            if input_data is None:
                return None
            self.interpreter.set_tensor(self.input_details[0]["index"], [input_data])
            self.interpreter.invoke()
            output_data = self.interpreter.get_tensor(self.output_details[0]["index"])
            return output_data[0]
        except Exception as e:
            logging.error(f"Error recognizing gesture: {e}")
            return None


class SmartHomeController:
    def __init__(self):
        self.light = False
        self.thermostat_temp = 20
        self.tv = False
        self.last_gesture_time = 0.0
        self.gesture_cooldown = 2.0
        self.confidence_threshold = 0.7

    def update_state(self, gesture, confidence):
        if confidence < self.confidence_threshold:
            logging.debug(f"Gesture '{gesture}' below confidence threshold ({self.confidence_threshold}).")
            return None
        now = time.time()
        if now - self.last_gesture_time < self.gesture_cooldown:
            logging.debug(f"Gesture '{gesture}' within cooldown period.")
            return None
        self.last_gesture_time = now
        try:
            if gesture == "Open Hand":
                self.light = not self.light
                logging.info(f"Light toggled to {self.light}")
            elif gesture == "Closed Fist":
                self.light = False
                logging.info("Light turned off")
            elif gesture == "Pointing Up":
                if self.thermostat_temp < 30:
                    self.thermostat_temp += 1
                    logging.info(f"Thermostat increased to {self.thermostat_temp}")
            elif gesture == "Pointing Down":
                if self.thermostat_temp > 15:
                    self.thermostat_temp -= 1
                    logging.info(f"Thermostat decreased to {self.thermostat_temp}")
            elif gesture == "Peace Sign":
                self.tv = not self.tv
                logging.info(f"TV toggled to {self.tv}")
            return self.get_state()
        except Exception as e:
            logging.error(f"Error updating smart home state: {e}")
            return None

    def get_state(self):
        return {
            "light": self.light,
            "thermostat_temp": self.thermostat_temp,
            "tv": self.tv,
        }


def capture_frames(picam2, frame_queue, stop_event):
    try:
        picam2.start()
        logging.info("Camera started.")
        while not stop_event.is_set():
            frame = picam2.capture_array()
            if frame is None:
                logging.warning("Captured empty frame, skipping.")
                continue
            try:
                frame_queue.put(frame, timeout=1)
            except queue.Full:
                logging.warning("Frame queue full, dropping frame.")
    except Exception as e:
        logging.error(f"Error capturing frames: {e}")
    finally:
        try:
            picam2.stop()
            logging.info("Camera stopped.")
        except Exception as e:
            logging.error(f"Error stopping camera: {e}")


def run_inference(frame_queue, gesture_recognizer, result_queue, stop_event):
    while not stop_event.is_set():
        try:
            frame = frame_queue.get(timeout=1)
        except queue.Empty:
            continue
        try:
            results = gesture_recognizer.recognize_gesture(frame)
            if results is not None:
                top_idx = int(np.argmax(results))
                if 0 <= top_idx < len(GESTURE_LABELS):
                    gesture = GESTURE_LABELS[top_idx]
                    confidence = float(results[top_idx])
                    result_queue.put((gesture, confidence))
                else:
                    logging.warning(f"Invalid gesture index: {top_idx}")
        except Exception as e:
            logging.error(f"Error during inference: {e}")
        finally:
            frame_queue.task_done()


def log_cloud_data(result_queue, smart_home_controller, user_id, stop_event):
    while not stop_event.is_set():
        try:
            gesture, confidence = result_queue.get(timeout=1)
            logging.info(f"Gesture: {gesture}, Confidence: {confidence:.4f}")
            state = smart_home_controller.update_state(gesture, confidence)
            if state:
                log_entry = {
                    "timestamp": datetime.now().isoformat(),
                    "user_id": user_id,
                    "gesture": gesture,
                    "state": state,
                }
                try:
                    with open("cloud_data.json", "a") as f:
                        f.write(json.dumps(log_entry) + "\n")
                except IOError as e:
                    logging.error(f"Error writing to cloud_data.json: {e}")
        except queue.Empty:
            continue


def main():
    parser = argparse.ArgumentParser(description="Gesture-Controlled Smart Home")
    parser.add_argument("--model_path", default="gesture_model_quantized.tflite", help="Path to TFLite model")
    parser.add_argument("--use_coral", action="store_true", help="Use Coral USB Accelerator")
    parser.add_argument("--user_id", default="user1", help="User ID for logging")
    args = parser.parse_args()

    logging.basicConfig(
        filename="smart_home.log",
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.getLogger().addHandler(logging.StreamHandler())

    picam2 = None
    stop_event = threading.Event()
    frame_queue = queue.Queue(maxsize=30)
    result_queue = queue.Queue(maxsize=30)
    gesture_recognizer = None
    smart_home_controller = SmartHomeController()

    def signal_handler(signum, frame):
        logging.info(f"Signal {signum} received, shutting down...")
        stop_event.set()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        gesture_recognizer = GestureRecognizer(args.model_path, args.use_coral)
    except (FileNotFoundError, RuntimeError) as e:
        logging.error(f"Model initialization failed: {e}")
        return 0

    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"},
            controls={"FrameRate": 30.0},
        )
        picam2.configure(config)
        logging.info("Camera initialized.")
    except Exception as e:
        logging.error(f"Camera initialization failed: {e}")
        return 0

    threads = [
        threading.Thread(target=capture_frames, args=(picam2, frame_queue, stop_event), daemon=True),
        threading.Thread(target=run_inference, args=(frame_queue, gesture_recognizer, result_queue, stop_event), daemon=True),
        threading.Thread(target=log_cloud_data, args=(result_queue, smart_home_controller, args.user_id, stop_event), daemon=True),
    ]

    for t in threads:
        t.start()

    try:
        while not stop_event.is_set():
            time.sleep(0.1)
    except KeyboardInterrupt:
        stop_event.set()

    for t in threads:
        t.join(timeout=5)

    logging.info("Shutdown complete.")
    return 0


if __name__ == "__main__":
    exit(main())

