import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys
import time

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def find_serial_port():
    available = [p.device for p in serial.tools.list_ports.comports()]
    candidates = ['/dev/ttyACM0', '/dev/ttyUSB0']
    for port in candidates:
        if port in available:
            return port
    return None

def send_serial(ser, cmd):
    if ser is None:
        return
    try:
        ser.write(cmd.encode('utf-8'))
        ser.flush()
    except serial.SerialException as e:
        print(f"Serial write error: {e}")

def main():
    global running

    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        print("Error: Could not open camera (index 0).")
        return

    ser = None
    serial_port = find_serial_port()
    if serial_port:
        try:
            ser = serial.Serial(serial_port, 9600, timeout=1)
            print(f"Serial port {serial_port} opened at 9600 baud.")
        except serial.SerialException as e:
            print(f"Warning: could not open {serial_port}: {e}")
            print("Continuing without serial communication.")
            ser = None
    else:
        print("Warning: no serial ports detected. Continuing without serial.")

    try:
        while running:
            ret, frame = cap.read()
            if not ret or frame is None:
                print("Error: Could not read frame from camera.")
                break

            h_frame, w_frame, _ = frame.shape
            cx, cy = w_frame // 2, h_frame // 2
            half = 50
            roi = frame[cy - half:cy + half, cx - half:cx + half]

            hsv_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
            hsv_roi = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)

            min_HSV = np.array([hsv_roi[:, :, 0].min(), hsv_roi[:, :, 1].min(), hsv_roi[:, :, 2].min()])
            max_HSV = np.array([hsv_roi[:, :, 0].max(), hsv_roi[:, :, 1].max(), hsv_roi[:, :, 2].max()])

            cv2.imshow("Frame", frame)
            cv2.imshow("ROI", roi)

            key = cv2.waitKey(1) & 0xFF
            if key == ord('s'):
                print("Color range saved.")
            elif key == ord('o'):
                print("Color tracking disabled.")
            elif key == 27:
                break

            if (min_HSV[0] != max_HSV[0]).any():
                mask = cv2.inRange(hsv_frame, min_HSV, max_HSV)
                contours, _ = cv2.findContours(mask, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)

                for contour in contours:
                    if cv2.contourArea(contour) > 500:
                        x, y, w, h = cv2.boundingRect(contour)
                        cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

                        ball_x = x + w // 2
                        ball_y = y + h // 2

                        if ball_x > cx + half and ball_y > cy + half:
                            send_serial(ser, '1')
                            print("Ball in Bottom-Right")
                        elif ball_x > cx + half and ball_y < cy - half:
                            send_serial(ser, '2')
                            print("Ball in Top-Right")
                        elif ball_x < cx - half and ball_y > cy + half:
                            send_serial(ser, '3')
                            print("Ball in Bottom-Left")
                        elif ball_x < cx - half and ball_y < cy - half:
                            send_serial(ser, '4')
                            print("Ball in Top-Left")
                        else:
                            send_serial(ser, '5')
                            print("Ball in Center")

    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        cap.release()
        if ser is not None:
            try:
                ser.close()
            except serial.SerialException:
                pass
        cv2.destroyAllWindows()
