import os
import sys
import time
import signal
import random
import logging
from datetime import datetime

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
LIGHT_PIN = 17
DHT_PIN = 4
CAMERA_RESOLUTION = (640, 480)
WAKE_WORD = "Greenhouse"
COMMANDS = ["turn on the lights", "turn off the lights", "what is the temperature", "take a picture"]

# Global state
lights_on = False
camera = None
dht_device = None
gpio_available = False

# --- GPIO Setup with Error Handling ---
try:
    import RPi.GPIO as GPIO
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
    gpio_available = True
    logging.info("GPIO initialized successfully.")
except (ImportError, RuntimeError) as e:
    logging.warning(f"GPIO initialization failed: {e}. Switching to simulated GPIO mode.")
    gpio_available = False

# --- Simulated GPIO Functions ---
def simulated_gpio_setup(pin, mode):
    logging.info(f"Simulated GPIO setup: Pin {pin}, Mode {mode}")

def simulated_gpio_output(pin, state):
    logging.info(f"Simulated GPIO output: Pin {pin}, State {state}")

def simulated_gpio_cleanup():
    logging.info("Simulated GPIO cleanup.")

# --- GPIO Function Wrappers ---
def setup_gpio(pin, mode):
    if gpio_available:
        GPIO.setup(pin, mode)
    else:
        simulated_gpio_setup(pin, mode)

def output_gpio(pin, state):
    if gpio_available:
        GPIO.output(pin, state)
    else:
        simulated_gpio_output(pin, state)

def cleanup_gpio():
    if gpio_available:
        GPIO.cleanup()
    else:
        simulated_gpio_cleanup()

# --- Light Control Functions ---
def turn_lights_on():
    global lights_on
    if not lights_on:
        output_gpio(LIGHT_PIN, GPIO.HIGH)
        lights_on = True
        logging.info("Lights turned ON.")
    else:
        logging.info("Lights are already ON.")

def turn_lights_off():
    global lights_on
    if lights_on:
        output_gpio(LIGHT_PIN, GPIO.LOW)
        lights_on = False
        logging.info("Lights turned OFF.")
    else:
        logging.info("Lights are already OFF.")

# --- Temperature Sensor Functions ---
def read_temperature():
    global dht_device
    if dht_device is not None:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                logging.info(f"Temperature: {temperature:.1f}°C")
                return temperature
            else:
                logging.warning("DHT11 returned None for temperature.")
        except RuntimeError as e:
            logging.warning(f"DHT11 read error (checksum or timing): {e}")
        except Exception as e:
            logging.error(f"Unexpected DHT11 error: {e}")

    # Fallback to simulated temperature
    temperature = random.uniform(15, 35)
    logging.info(f"Simulated Temperature: {temperature:.1f}°C")
    return temperature

# --- Camera Functions ---
def capture_image():
    global camera
    if camera is not None:
        try:
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            camera.capture(filename)
            logging.info(f"Image captured and saved as {filename}")
            return filename
        except Exception as e:
            logging.error(f"Camera capture error: {e}")
            return None
    else:
        logging.warning("Camera not available.")
        return None

# --- Voice Recognition Functions ---
def recognize_voice():
    try:
        import speech_recognition as sr
        recognizer = sr.Recognizer()

        with sr.Microphone() as source:
            print("Say something!")
            recognizer.adjust_for_ambient_noise(source, duration=0.5)
            audio = recognizer.listen(source, timeout=5)

        try:
            text = recognizer.recognize_google(audio)
            print(f"You said: {text}")
            return text.lower()
        except sr.UnknownValueError:
            logging.warning("Google Speech Recognition could not understand audio")
            return None
        except sr.RequestError as e:
            logging.error(f"Could not request results from Google Speech Recognition service; {e}")
            return None
    except ImportError:
        logging.warning("speech_recognition library not installed.")
        return None

# --- Signal Handler ---
def signal_handler(sig, frame):
    logging.info("Exiting program...")
    cleanup()
    sys.exit(0)

# --- Cleanup Function ---
def cleanup():
    global camera, dht_device
    if camera is not None:
        try:
            camera.stop()
            camera.close()
            logging.info("Camera closed.")
        except Exception as e:
            logging.error(f"Error closing camera: {e}")
    if dht_device is not None:
        try:
            dht_device.exit()
            logging.info("DHT11 device exited.")
        except Exception as e:
            logging.error(f"Error exiting DHT11: {e}")
    cleanup_gpio()

# --- Main Program ---
def main():
    global camera, dht_device

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize DHT11 sensor
    try:
        import adafruit_dht
        dht_device = adafruit_dht.DHT11(DHT_PIN)
        logging.info("DHT11 sensor initialized.")
    except (ImportError, RuntimeError) as e:
        logging.warning(f"DHT11 initialization failed: {e}. Temperature will be simulated.")
        dht_device = None

    # Initialize PiCamera2
    try:
        from picamera2 import Picamera2
        camera = Picamera2()
        camera.configure(camera.create_still_configuration(main={"size": CAMERA_RESOLUTION}))
        camera.start()
        logging.info("Camera initialized.")
    except (ImportError, RuntimeError) as e:
        logging.warning(f"Camera initialization failed: {e}. Image capture will be simulated.")
        camera = None

    try:
        while True:
            voice_input = recognize_voice()
            if voice_input:
                if WAKE_WORD.lower() in voice_input:
                    command = voice_input.replace(WAKE_WORD.lower(), "").strip()
                    if command in COMMANDS:
                        if command == "turn on the lights":
                            turn_lights_on()
                        elif command == "turn off the lights":
                            turn_lights_off()
                        elif command == "what is the temperature":
                            read_temperature()
                        elif command == "take a picture":
                            capture_image()
                        time.sleep(1)
                    else:
                        logging.warning(f"Unknown command: {command}")
            time.sleep(0.1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

