import io
import time
import datetime
import os
import signal
import sys
import configparser
import threading
import logging
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
import RPi.GPIO as GPIO
import smbus

CONFIG_FILE = 'config.ini'
DEFAULT_CONFIG = {
    'camera': {
        'resolution_width': '640',
        'resolution_height': '480',
        'framerate': '24'
    },
    'motion_detection': {
        'motion_threshold': '15',
        'motion_sensitivity': '0.05',
        'debounce_time': '2'
    },
    'recording': {
        'recording_duration': '10'
    },
    'storage': {
        'disk_space_limit': '1024'
    },
    'logging': {
        'log_level': 'INFO'
    }
}

class SecurityCamera:
    def __init__(self, config_file=CONFIG_FILE):
        self.config = self.load_config(config_file)
        self.logger = self.setup_logging()
        self.resolution = (int(self.config['camera']['resolution_width']), int(self.config['camera']['resolution_height']))
        self.framerate = int(self.config['camera']['framerate'])
        self.motion_threshold = int(self.config['motion_detection']['motion_threshold'])
        self.motion_sensitivity = float(self.config['motion_detection']['motion_sensitivity'])
        self.debounce_time = int(self.config['motion_detection']['debounce_time'])
        self.recording_duration = int(self.config['recording']['recording_duration'])
        self.disk_space_limit = int(self.config['storage']['disk_space_limit'])
        self.footage_dir = '/home/pi/security_footage'
        self.camera = None
        self.encoder = None
        self.output = None
        self.last_frame = None
        self.motion_detected = False
        self.motion_start_time = None
        self.last_motion_time = 0
        self.running = True
        self.lock = threading.Lock()
        self.bus = None
        self.light_sensor_available = False
        self.light_sensor_thread = None
        self.light_reading = None
        self.light_lock = threading.Lock()
        self.gpio_initialized = False
        self.circular_buffer = []
        self.buffer_size = self.framerate * 3
        self.setup_gpio()
        self.setup_i2c()
        self.start_light_sensor_thread()
        self.setup_camera()
        self.logger.info("Security camera initialized.")

    def load_config(self, config_file):
        config = configparser.ConfigParser()
        if not os.path.exists(config_file):
            self.logger.warning(f"Config file {config_file} not found. Using defaults.")
            for section, defaults in DEFAULT_CONFIG.items():
                if section not in config:
                    config[section] = {}
                for key, value in defaults.items():
                    config[section][key] = value
            try:
                with open(config_file, 'w') as f:
                    config.write(f)
            except Exception as e:
                self.logger.error(f"Failed to write default config: {e}")
        else:
            config.read(config_file)
            for section, defaults in DEFAULT_CONFIG.items():
                if section not in config:
                    config[section] = {}
                for key, value in defaults.items():
                    if key not in config[section]:
                        config[section][key] = value
        return config

    def setup_logging(self):
        log_level = getattr(logging, self.config['logging']['log_level'].upper(), logging.INFO)
        logging.basicConfig(level=log_level, format='%(asctime)s - %(levelname)s - %(message)s')
        return logging.getLogger(__name__)

    def setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(17, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            self.gpio_initialized = True
            self.logger.info("GPIO initialized for future sensor integration.")
        except Exception as e:
            self.logger.error(f"Failed to initialize GPIO: {e}")

    def setup_i2c(self):
        try:
            self.bus = smbus.SMBus(1)
            self.bus.write_byte_data(0x23, 0x10, 0)
            self.light_sensor_available = True
            self.logger.info("BH1750 light sensor initialized.")
        except Exception as e:
            self.logger.error(f"Failed to initialize BH1750 light sensor: {e}")
            self.light_sensor_available = False

    def start_light_sensor_thread(self):
        if self.light_sensor_available:
            self.light_sensor_thread = threading.Thread(target=self.read_light_sensor, daemon=True)
            self.light_sensor_thread.start()

    def read_light_sensor(self):
        while self.running:
            try:
                data = self.bus.read_i2c_block_data(0x23, 0x00, 2)
                lux = (data[1] + 256 * data[0]) / 1.2
                with self.light_lock:
                    self.light_reading = lux
                self.logger.debug(f"Ambient light: {lux:.2f} lux")
                time.sleep(5)
            except Exception as e:
                self.logger.error(f"Error reading light sensor: {e}")
                time.sleep(10)

    def setup_camera(self):
        try:
            self.camera = Picamera2()
            config = self.camera.create_video_configuration(
                main={"size": self.resolution, "format": "YUV420"},
                lores={"size": (self.resolution[0] // 2, self.resolution[1] // 2), "format": "YUV420"}
            )
            self.camera.configure(config)
            self.encoder = H264Encoder(bitrate=10000000)
            self.camera.start()
            self.logger.info("Camera initialized successfully.")
        except Exception as e:
            self.logger.error(f"Failed to initialize camera: {e}")
            self.running = False

    def detect_motion(self, current_frame):
        if self.last_frame is None:
            self.last_frame = current_frame
            return False
        diff = np.abs(current_frame.astype(np.int16) - self.last_frame.astype(np.int16))
        avg_diff = np.mean(diff)
        changed_pixels = np.count_nonzero(diff > self.motion_threshold)
        percentage_changed = changed_pixels / diff.size
        self.last_frame = current_frame
        return avg_diff > self.motion_threshold and percentage_changed > self.motion_sensitivity

    def record_video(self, filename):
        try:
            os.makedirs(self.footage_dir, exist_ok=True)
            filepath = os.path.join(self.footage_dir, filename)
            with open(filepath, 'wb') as f:
                self.encoder.output = f
                self.encoder.start()
                start_time = time.time()
                while time.time() - start_time < self.recording_duration and self.running:
                    frame = self.camera.capture_array("lores")
                    self.encoder.encode(frame)
                    time.sleep(1.0 / self.framerate)
                self.encoder.stop()
                self.logger.info(f"Video recorded: {filename}")
                self.manage_disk_space()
        except Exception as e:
            self.logger.error(f"Error recording video: {e}")

    def manage_disk_space(self):
        try:
            total_size = 0
            for dirpath, dirnames, filenames in os.walk(self.footage_dir):
                for f in filenames:
                    fp = os.path.join(dirpath, f)
                    total_size += os.path.getsize(fp)
            total_size_mb = total_size / (1024 * 1024)
            if total_size_mb > self.disk_space_limit:
                files = []
                for f in os.listdir(self.footage_dir):
                    fp = os.path.join(self.footage_dir, f)
                    if os.path.isfile(fp):
                        files.append((os.path.getmtime(fp), fp))
                files.sort()
                for _, fp in files:
                    try:
                        os.remove(fp)
                        total_size_mb -= os.path.getsize(fp) / (1024 * 1024)
                        if total_size_mb <= self.disk_space_limit:
                            break
                    except Exception as e:
                        self.logger.error(f"Error deleting file {fp}: {e}")
        except Exception as e:
            self.logger.error(f"Error managing disk space: {e}")

    def run(self):
        try:
            while self.running:
                frame = self.camera.capture_array("lores")
                with self.lock:
                    self.circular_buffer.append(frame)
                    if len(self.circular_buffer) > self.buffer_size:
                        self.circular_buffer.pop(0)
                if self.detect_motion(frame):
                    if not self.motion_detected:
                        self.motion_detected = True
                        self.motion_start_time = time.time()
