                            self.logger.info(f"Ambient light: {lux:.2f} lux")
                    else:
                        self.last_motion_time = time.time()
                else:
                    if self.motion_detected and (time.time() - self.last_motion_time > self.debounce_time):
                        self.motion_detected = False
                        elapsed = time.time() - self.motion_start_time
                        if elapsed > 0:
