import cv2
import numpy as np
import time
import logging
import signal
import sys
from gpiozero import OutputDevice
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

RESOLUTION = (320, 240)
FRAMERATE = 10
ROI = (slice(10, 150), slice(40, 280))
GPIO_PIN = 17

running = True

def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down...")
    running = False

def initialize_camera():
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": RESOLUTION, "format": "BGR888"},
            controls={"FrameRate": FRAMERATE}
        )
        picam2.configure(config)
        picam2.start()
        time.sleep(1)
        logging.info("Camera initialized successfully.")
        return picam2
    except Exception as e:
        logging.error(f"Camera initialization failed: {e}")
        return None

def initialize_gpio():
    try:
        led = OutputDevice(GPIO_PIN, active_high=True, initial_value=True)
        logging.info(f"GPIO pin {GPIO_PIN} initialized as output HIGH.")
        return led
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        return None

def process_frame(frame):
    if frame is None or frame.size == 0:
        logging.warning("Empty frame received.")
        return None
    try:
        roi = frame[ROI]
        return roi
    except Exception as e:
        logging.error(f"ROI extraction failed: {e}")
        return None

def display_image(image):
    try:
        cv2.imshow('Output Image', image)
    except Exception as e:
        logging.error(f"Display update failed: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    picam2 = initialize_camera()
    if picam2 is None:
        sys.exit(1)

    led = initialize_gpio()
    if led is None:
        picam2.stop()
        sys.exit(1)

    try:
        while running:
            frame = picam2.capture_array()
            if frame is None:
                logging.warning("Capture returned None, skipping.")
                continue
            roi = process_frame(frame)
            if roi is not None:
                display_image(roi)
            key = cv2.waitKey(1) & 0xFF
            if key == 10:
                logging.info("Enter key pressed, exiting.")
                break
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Cleaning up resources...")
        try:
            picam2.stop()
            logging.info("Camera stopped.")
        except Exception as e:
            logging.error(f"Error stopping camera: {e}")
        try:
            cv2.destroyAllWindows()
            logging.info("OpenCV windows closed.")
        except Exception as e:
            logging.error(f"Error closing windows: {e}")
        if led is not None:
            try:
                led.off()
                led.close()
                logging.info("GPIO released.")
            except Exception as e:
                logging.error(f"Error releasing GPIO: {e}")
        logging.info("Cleanup complete.")

if __name__ == "__main__":
    main()

