import io
import time
import datetime
import logging
import signal
import sys
import os
from PIL import Image, ImageChops
from picamera2 import Picamera2
from gpiozero import CPUTemperature

CONFIG_FILE = "config.txt"

class Camera:
    def __init__(self, config):
        self.config = config
        self.camera = None
        self._running = True
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)
        try:
            self.camera = Picamera2()
            self.camera.configure(self.camera.create_preview_configuration(
                main={"format": 'RGB888', "size": (640, 480)}
            ))
            self.camera.start()
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize camera: {e}")
            self.camera = None

    def _signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received, shutting down...")
        self._running = False

    def capture_frame(self):
        if not self.camera:
            return None
        try:
            return self.camera.capture_array()
        except Exception as e:
            logging.error(f"Error capturing frame: {e}")
            return None

    def capture_jpeg(self):
        if not self.camera:
            return None
        try:
            buf = io.BytesIO()
            self.camera.capture_file(buf, format='jpeg')
            buf.seek(0)
            return buf
        except Exception as e:
            logging.error(f"Error capturing JPEG: {e}")
            return None

    def save_snapshot(self, filename):
        if not self.camera:
            return False
        try:
            buf = self.capture_jpeg()
            if buf:
                with open(filename, 'wb') as f:
                    f.write(buf.read())
                logging.info(f"Snapshot saved to {filename}")
                return True
            return False
        except Exception as e:
            logging.error(f"Error saving snapshot: {e}")
            return False

    def close(self):
        if self.camera:
            try:
                self.camera.stop()
                self.camera.close()
                logging.info("Camera closed.")
            except Exception as e:
                logging.error(f"Error closing camera: {e}")

class MotionDetector:
    def __init__(self, config):
        self.config = config
        self.last_frame = None
        self.motion_detected = False
        self.motion_start_time = None

    def detect_motion(self, frame):
        if frame is None:
            return False
        try:
            roi_x1 = self.config.getint("roi_x1")
            roi_y1 = self.config.getint("roi_y1")
            roi_x2 = self.config.getint("roi_x2")
            roi_y2 = self.config.getint("roi_y2")
            motion_threshold = self.config.getint("motion_threshold")
            confirmation_delay = self.config.getint("confirmation_delay")

            if not (0 <= roi_x1 < roi_x2 < frame.shape[1] and 0 <= roi_y1 < roi_y2 < frame.shape[0]):
                logging.warning("Invalid ROI coordinates.")
                return False

            roi = frame[roi_y1:roi_y2, roi_x1:roi_x2]

            if self.last_frame is None:
                self.last_frame = roi.copy()
                return False

            diff = ImageChops.difference(
                Image.fromarray(roi), Image.fromarray(self.last_frame)
            )
            pixels_changed = np.sum(np.array(diff) > 10)
            percentage_changed = (pixels_changed * 100) / (roi.shape[0] * roi.shape[1])

            self.last_frame = roi.copy()

            if percentage_changed > motion_threshold:
                if not self.motion_detected:
                    self.motion_detected = True
                    self.motion_start_time = time.time()
                    logging.info(f"Motion detected: {percentage_changed:.2f}% change.")
                elif time.time() - self.motion_start_time >= confirmation_delay:
                    logging.info("Motion confirmed.")
                    return True
            else:
                self.motion_detected = False
                self.motion_start_time = None

            return False
        except Exception as e:
            logging.error(f"Error in motion detection: {e}")
            return False

class TemperatureMonitor:
    def __init__(self, config):
        self.config = config
        self.simulated_temperature = config.getboolean("simulated_temperature")
        self.cpu_temp = None
        if not self.simulated_temperature:
            try:
                self.cpu_temp = CPUTemperature()
                logging.info("Temperature monitor initialized.")
            except Exception as e:
                logging.error(f"Failed to initialize temperature monitor: {e}")
                self.cpu_temp = None

    def get_temperature(self):
        if self.simulated_temperature:
            return 50.0 + (time.time() % 10)
        if self.cpu_temp:
            try:
                return self.cpu_temp.temperature
            except Exception as e:
                logging.error(f"Error reading temperature: {e}")
                return None
        return None

class AlertSystem:
    def __init__(self, config):
        self.config = config

    def send_alert(self, message):
        logging.warning(f"ALERT: {message}")
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
        snapshot_dir = self.config.get("snapshot_dir", ".")
        snapshot_filename = os.path.join(snapshot_dir, f"{timestamp}_alert.jpg")
        if camera.save_snapshot(snapshot_filename):
            logging.info(f"Snapshot saved for alert: {snapshot_filename}")

def load_config(config_file):
    import configparser
    config = configparser.ConfigParser()
    if not os.path.exists(config_file):
        logging.error(f"Config file not found: {config_file}")
        return None
    config.read(config_file)
    return config

def main():
    global camera
    config = load_config(CONFIG_FILE)
    if not config:
        sys.exit(1)

    logging.basicConfig(
        filename=config.get("logging", "log_file", fallback="security.log"),
        level=getattr(logging, config.get("logging", "log_level", fallback="INFO").upper(), logging.INFO),
        format='%(asctime)s - %(levelname)s - %(message)s'
    )

    camera = Camera(config)
    if not camera.camera:
        sys.exit(1)

    motion_detector = MotionDetector(config)
    temperature_monitor = TemperatureMonitor(config)
    alert_system = AlertSystem(config)

