from picamera2 import Picamera2

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera():
    """Initialize the Picamera2 with XRGB8888 format at 640x480."""
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"format": 'XRGB8888', "size": (640, 480)}
        )
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None

def load_face_cascade():
    """Load the Haar Cascade classifier for frontal face detection."""
    cascade_path = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
    try:
        face_cascade = cv2.CascadeClassifier(cascade_path)
        if face_cascade.empty():
            print(f"Error: Failed to load cascade classifier from {cascade_path}", file=sys.stderr)
            return None
        return face_cascade
    except Exception as e:
        print(f"Error loading face cascade: {e}", file=sys.stderr)
        return None

def detect_faces(image, face_cascade):
    """Detect faces in the given BGR image using the Haar Cascade classifier."""
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    return face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5)

def draw_rectangles(image, faces):
    """Draw blue rectangles around detected faces (BGR color (255, 0, 0))."""
    for (x, y, w, h) in faces:
        cv2.rectangle(image, (x, y), (x + w, y + h), (255, 0, 0), 2)

def main():
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    picam2 = initialize_camera()
    if picam2 is None:
        sys.exit(1)

    face_cascade = load_face_cascade()
    if face_cascade is None:
        picam2.stop()
        sys.exit(1)

    cv2.namedWindow("Real-time Face Detection", cv2.WINDOW_NORMAL)

    try:
        while _running:
            # Capture frame; handle transient errors gracefully
            try:
                image = picam2.capture_array()
            except Exception as e:
                print(f"Frame capture error: {e}", file=sys.stderr)
                time.sleep(0.1)
                continue

            if image is None:
                print("Warning: Captured empty frame", file=sys.stderr)
                continue

            # Detect faces
            faces = detect_faces(image, face_cascade)
            if len(faces) > 0:
                print('Face detected!')

            # Draw rectangles
            draw_rectangles(image, faces)

            # Display the annotated frame
            cv2.imshow("Real-time Face Detection", image)

            # Check for 'q' key press (1 ms delay)
            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)

    finally:
        # Clean up resources on every exit path
        cv2.destroyAllWindows()
        try:
            picam2.stop()
        except Exception:
            pass
        print("Resources released. Exiting.")

if __name__ == "__main__":
    main()

