import time
import logging
import signal
import sys
import cv2
import numpy as np
import RPi.GPIO as GPIO
from picamera2 import Picamera2
import serial

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

SERVO_PIN_1 = 7
SERVO_PIN_2 = 13
SERVO_FREQ = 50
SERVO_CENTER_DUTY = 7.0
SERIAL_PORT = '/dev/ttyACM0'
SERIAL_BAUDRATE = 115200
CAMERA_RESOLUTION = (160, 120)
CAMERA_FRAMERATE = 16
X_THRESHOLD = 24
MIN_TARGET_AREA = 10

arduino = None
camera = None
servo1 = None
servo2 = None
running = True

def signal_handler(sig, frame):
    global running
    logging.info("Shutdown signal received.")
    running = False

def cleanup():
    global arduino, camera, servo1, servo2
    logging.info("Cleaning up resources...")
    if camera is not None:
        try:
            camera.stop()
            camera.close()
        except Exception as e:
            logging.error(f"Error closing camera: {e}")
    if servo1 is not None:
        try:
            servo1.stop()
        except Exception as e:
            logging.error(f"Error stopping servo1: {e}")
    if servo2 is not None:
        try:
            servo2.stop()
        except Exception as e:
            logging.error(f"Error stopping servo2: {e}")
    if arduino is not None and arduino.is_open:
        try:
            arduino.close()
            logging.info("Serial port closed.")
        except Exception as e:
            logging.error(f"Error closing serial port: {e}")
    try:
        GPIO.cleanup()
        logging.info("GPIO cleaned up.")
    except Exception as e:
        logging.error(f"Error cleaning up GPIO: {e}")

def initialize_camera():
    global camera
    try:
        cam = Picamera2()
        config = cam.create_preview_configuration(
            main={"size": CAMERA_RESOLUTION, "format": "BGR888"},
            controls={"FrameRate": CAMERA_FRAMERATE}
        )
        cam.configure(config)
        cam.start()
        time.sleep(2)
        camera = cam
        logging.info("Camera initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        return False

def initialize_arduino():
    global arduino
    for attempt in range(3):
        try:
            ard = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=1)
            arduino = ard
            time.sleep(2)
            logging.info("Arduino initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"Error initializing Arduino (attempt {attempt + 1}/3): {e}")
            if arduino is not None and arduino.is_open:
                arduino.close()
            time.sleep(5)
    logging.error("Failed to initialize Arduino after 3 attempts.")
    return False

def initialize_gpio():
    try:
        GPIO.setmode(GPIO.BOARD)
        GPIO.setup(SERVO_PIN_1, GPIO.OUT)
        GPIO.setup(SERVO_PIN_2, GPIO.OUT)
        global servo1, servo2
        servo1 = GPIO.PWM(SERVO_PIN_1, SERVO_FREQ)
        servo2 = GPIO.PWM(SERVO_PIN_2, SERVO_FREQ)
        servo1.start(SERVO_CENTER_DUTY)
        servo2.start(SERVO_CENTER_DUTY)
        logging.info("GPIO and servos initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Error initializing GPIO: {e}")
        return False

def segment_red(frame):
    hsv_roi = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    mask_1 = cv2.inRange(hsv_roi, np.array([160, 160, 10]), np.array([190, 255, 255]))
    ycr_roi = cv2.cvtColor(frame, cv2.COLOR_BGR2YCrCb)
    mask_2 = cv2.inRange(ycr_roi, np.array([0, 165, 0]), np.array([255, 255, 255]))
    mask = mask_1 | mask_2
    kernel = np.ones((5, 5), np.uint8)
    mask = cv2.erode(mask, kernel)
    mask = cv2.dilate(mask, kernel)
    return mask

def find_blob(mask):
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    if not contours:
        return None, None
    largest_contour = max(contours, key=cv2.contourArea)
    area = cv2.contourArea(largest_contour)
    if area < MIN_TARGET_AREA:
        return None, None
    x, y, w, h = cv2.boundingRect(largest_contour)
    return (x + w//2, y + h//2), area

def control_servos(center_x, center_y, arduino):
    if center_x is None or arduino is None:
        return
    try:
        if center_x > X_THRESHOLD:
            servo1.ChangeDutyCycle(SERVO_CENTER_DUTY + 5)
            arduino.write(b'r')
        elif center_x < -X_THRESHOLD:
            servo1.ChangeDutyCycle(SERVO_CENTER_DUTY - 5)
            arduino.write(b'l')
        else:
            servo1.ChangeDutyCycle(SERVO_CENTER_DUTY)
            arduino.write(b's')
        if center_y > X_THRESHOLD:
            servo2.ChangeDutyCycle(SERVO_CENTER_DUTY + 5)
        elif center_y < -X_THRESHOLD:
            servo2.ChangeDutyCycle(SERVO_CENTER_DUTY - 5)
        else:
            servo2.ChangeDutyCycle(SERVO_CENTER_DUTY)
    except Exception as e:
        logging.error(f"Error controlling servos: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    if not initialize_camera():
        sys.exit(1)
    if not initialize_arduino():
        sys.exit(1)
    if not initialize_gpio():
        sys.exit(1)
    try:
        while running:
            frame = camera.capture_array()
            if frame is None:
                logging.warning("Empty frame received.")
                continue
            mask = segment_red(frame)
            center, area = find_blob(mask)
            if center:
                logging.info(f"Target found at {center}, area: {area}")
            control_servos(center[0] if center else None, center[1] if center else None, arduino)
            time.sleep(0.03)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

