from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Buffers MJPEG stream data from picamera2 and flushes complete H.264 frames to a sink."""

    def __init__(self, c: Picamera2):
        if not isinstance(c, Picamera2):
            raise TypeError("c must be a Picamera2 instance")
        self.c = c
        self.b = io.BytesIO()
        self.sink = None
        self._frame_complete = False
        self._frame_type = 0

    def flush(self):
        """Flush any buffered bytes to the sink and reset the buffer."""
        if self.sink is None:
            return
        data = self.b.getvalue()
        if data:
            try:
                self.sink(data)
            except Exception as e:
                logger.error(f"Error writing to sink: {e}")
        self.b.close()
        self.b = io.BytesIO()

    def write(self, d: bytes):
        """Accumulate bytes d into the buffer.

        When a complete H.264 frame (frame_type != 1) is detected via picamera2 metadata,
        flush the buffer to the sink and reset.  Otherwise, keep accumulating.
        """
        try:
            self.b.write(d)
            if self.c.current_configuration() is not None:
                meta = self.c.current_configuration().get('encode', {})
                self._frame_complete = meta.get('frame_complete', False)
                self._frame_type = meta.get('frame_type', 0)
            if self._frame_complete and self._frame_type != 1:
                self.flush()
        except Exception as e:
            logger.error(f"Error in CameraStreamBuffer.write: {e}")

    def set_sink(self, sink):
        """Set the sink function for flushed frames."""
        self.sink = sink


class MotionDetectionBuffer:
    """Buffers MJPEG stream data and runs motion detection via a callback."""

    def __init__(self, f):
        if not callable(f):
            raise TypeError("f must be callable")
        self.f = f
        self.b = io.BytesIO()
        self._prev_frame = None
        self._first_frame = True

    def _decode_jpeg(self, data: bytes):
        """Decode JPEG bytes into a BGR NumPy array."""
        try:
            arr = np.frombuffer(data, dtype=np.uint8)
            img = cv2.imdecode(arr, cv2.IMREAD_COLOR)
            if img is None:
                logger.warning("cv2.imdecode returned None; skipping frame")
                return None
            return img
        except Exception as e:
            logger.error(f"Error decoding JPEG frame: {e}")
            return None

    def write(self, d: bytes):
        """Accumulate bytes d into the buffer.

        When a new JPEG SOI marker is encountered, decode the previously accumulated
        frame, invoke the motion-detection callback with previous and current frames,
        and start accumulating the new frame.
        """
        try:
            if d.startswith(b'\xff\xd8'):
                prev_data = self.b.getvalue()
                if prev_data:
                    current_frame = self._decode_jpeg(prev_data)
                    if current_frame is not None:
                        if not self._first_frame:
                            self.f(self._prev_frame, current_frame)
                        else:
                            self._first_frame = False
                        self._prev_frame = current_frame
                self.b.close()
                self.b = io.BytesIO()
            self.b.write(d)
        except Exception as e:
            logger.error(f"Error in MotionDetectionBuffer.write: {e}")

