class DoorController:
    def __init__(self):
        self.button = None
        self.door = None
        self.camera = None
        self.mixer = None
        self.sounds = {}
        self.model = None
        self._running = True

        try:
            self.button = Button(17, pull_up=True, bounce_time=0.05)
            self.door = OutputDevice(18, active_high=True, initial_value=False)
        except Exception as e:
            print(f"GPIO init failed: {e}", file=sys.stderr)
            self.cleanup()
            sys.exit(1)

        try:
            self.mixer = pygame.mixer.init(frequency=48000, size=-16, channels=1, buffer=1024)
            self.sounds = {
                "welcome": pygame.mixer.Sound("welcome.wav"),
                "wait": pygame.mixer.Sound("wait.wav"),
                "later": pygame.mixer.Sound("later.wav"),
            }
        except Exception as e:
            print(f"Mixer/sound init failed: {e}", file=sys.stderr)
            self.cleanup()
            sys.exit(1)

        try:
            self.model = cv2.face.EigenFaceRecognizer_create()
            self.model.read(config.TRAINING_FILE)
        except Exception as e:
            print(f"Model load failed: {e}", file=sys.stderr)
            self.cleanup()
            sys.exit(1)

        try:
            self.camera = Picamera2()
            self.camera.configure(self.camera.create_preview_configuration(main={"format": "BGR888"}))
            self.camera.start()
        except Exception as e:
            print(f"Camera init failed: {e}", file=sys.stderr)
            self.cleanup()
            sys.exit(1)

    def cleanup(self):
        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception:
                pass
        if self.door is not None:
            try:
                self.door.close()
            except Exception:
                pass
        if self.button is not None:
            try:
                self.button.close()
            except Exception:
                pass
        if self.mixer is not None:
            try:
                pygame.mixer.quit()
            except Exception:
                pass

    def handle_signal(self, signum, frame):
        print(f"\nSignal {signum} received, shutting down...")
        self._running = False

    def run(self):
        signal.signal(signal.SIGINT, self.handle_signal)
        signal.signal(signal.SIGTERM, self.handle_signal)

