import signal
import sys
import time
import board
import busio
import adafruit_ssd1306
import adafruit_bme280
import adafruit_tsl2561

OLED_ADDR = 0x3C
BME280_ADDR = 0x76
TSL2561_ADDR = 0x39

running = True

def handle_sigint(signum, frame):
    global running
    running = False

def init_i2c():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        while not i2c.try_lock():
            time.sleep(0.01)
        i2c.unlock()
        return i2c
    except Exception as e:
        print(f"Failed to initialize I2C bus: {e}", file=sys.stderr)
        return None

def init_oled(i2c):
    try:
        return adafruit_ssd1306.SSD1306_I2C(128, 64, i2c, addr=OLED_ADDR)
    except Exception as e:
        print(f"Failed to initialize OLED at 0x{OLED_ADDR:02X}: {e}", file=sys.stderr)
        return None

def init_bme280(i2c):
    try:
        return adafruit_bme280.Adafruit_BME280_I2C(i2c, address=BME280_ADDR)
    except Exception as e:
        print(f"Failed to initialize BME280 at 0x{BME280_ADDR:02X}: {e}", file=sys.stderr)
        return None

def init_tsl2561(i2c):
    try:
        return adafruit_tsl2561.TSL2561(i2c, address=TSL2561_ADDR)
    except Exception as e:
        print(f"Failed to initialize TSL2561 at 0x{TSL2561_ADDR:02X}: {e}", file=sys.stderr)
        return None

def read_sensors(bme280, tsl2561):
    try:
        temp = bme280.temperature
        hum = bme280.humidity
        pres = bme280.pressure
    except Exception as e:
        print(f"BME280 read error: {e}", file=sys.stderr)
        temp = hum = pres = None
    try:
        lux = tsl2561.lux
    except Exception as e:
        print(f"TSL2561 read error: {e}", file=sys.stderr)
        lux = None
    return temp, hum, pres, lux

def update_display(oled, temp, hum, pres, lux):
    try:
        oled.fill(0)
        oled.text(f"Temp: {temp:.1f} C" if temp is not None else "Temp: N/A", 0, 0, 1)
        oled.text(f"Humidity: {hum:.1f} %" if hum is not None else "Humidity: N/A", 0, 16, 1)
        oled.text(f"Pressure: {pres:.1f} hPa" if pres is not None else "Pressure: N/A", 0, 32, 1)
        oled.text(f"Light: {lux:.1f} lux" if lux is not None else "Light: N/A", 0, 48, 1)
        oled.show()
    except Exception as e:
        print(f"Display update error: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, handle_sigint)
    i2c = init_i2c()
    if i2c is None:
        sys.exit(1)
    oled = init_oled(i2c)
    bme280 = init_bme280(i2c)
    tsl2561 = init_tsl2561(i2c)
    if oled is None or bme280 is None or tsl2561 is None:
        print("One or more sensors failed to initialize. Exiting.", file=sys.stderr)
        try:
            i2c.deinit()
        except Exception:
            pass
        sys.exit(1)
    try:
        while running:
            temp, hum, pres, lux = read_sensors(bme280, tsl2561)
            update_display(oled, temp, hum, pres, lux)
            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        try:
            oled.fill(0)
            oled.show()
        except Exception:
            pass
        try:
            i2c.deinit()
        except Exception:
            pass
        print("Resources released. Exiting.")

if __name__ == "__main__":
    main()

