import time
import signal
import sys
import board
import busio
import adafruit_character_lcd.character_lcd_i2c as character_lcd
import adafruit_dht

# --- Configuration -----------------------------------------------------------
I2C_ADDR = 0x27          # PCF8574 I2C backpack address
I2C_BUS = board.SCL      # board.SCL = GPIO3, board.SDA = GPIO2
DHT_PIN = board.D4       # GPIO4 (board.D4)
UPDATE_INTERVAL = 2.0    # seconds between LCD refreshes

# --- Globals for cleanup -----------------------------------------------------
lcd = None
dht = None
running = True


def cleanup():
    """Clear the LCD and release sensor resources on exit."""
    global lcd, dht
    if lcd is not None:
        try:
            lcd.clear()
        except Exception:
            pass
    if dht is not None:
        try:
            dht.exit()
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    global running
    running = False


def init_i2c():
    """Initialize the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(I2C_BUS, frequency=100000)
    except Exception as exc:
        print(f"[ERROR] I2C bus initialization failed: {exc}", file=sys.stderr)
        return None


def init_lcd(i2c_bus):
    """Initialize the 16x2 I2C LCD at address 0x27; return the LCD or None."""
    try:
        return character_lcd.Character_LCD_I2C(i2c_bus, 16, 2, addr=I2C_ADDR)
    except Exception as exc:
        print(f"[ERROR] LCD initialization failed: {exc}", file=sys.stderr)
        return None


def init_dht():
    """Initialize the DHT22 sensor; return the sensor object or None."""
    try:
        return adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"[ERROR] DHT22 initialization failed: {exc}", file=sys.stderr)
        return None


def read_sensor():
    """Return (temperature, humidity) or (None, None) on failure."""
    global dht
    if dht is None:
        return None, None
    try:
        temperature = dht.temperature
        humidity = dht.humidity
        if temperature is None or humidity is None:
            print("[WARN] DHT22 returned None reading.", file=sys.stderr)
            return None, None
        return temperature, humidity
    except RuntimeError as exc:
        # adafruit_dht raises RuntimeError on checksum / timing glitches
        print(f"[WARN] DHT22 read error: {exc}", file=sys.stderr)
        return None, None
    except Exception as exc:
        print(f"[ERROR] Unexpected DHT22 error: {exc}", file=sys.stderr)
        return None, None


def update_lcd(temperature, humidity):
    """Write temperature and humidity to the LCD, or a blank line on failure."""
    global lcd
    if lcd is None:
        return
    try:
        if temperature is not None and humidity is not None:
            lcd.message = f"Temp: {temperature:.1f} C\nHumidity: {humidity:.1f}%"
        else:
            lcd.message = "Sensor Error\n  Retrying..."
    except Exception as exc:
        print(f"[ERROR] LCD write failed: {exc}", file=sys.stderr)


def main():
    global lcd, dht, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = init_i2c()
    if i2c_bus is None:
        sys.exit(1)

    lcd = init_lcd(i2c_bus)
    if lcd is None:
        sys.exit(1)

    dht = init_dht()
    if dht is None:
        sys.exit(1)

    try:
        while running:
            temperature, humidity = read_sensor()
            update_lcd(temperature, humidity)
            time.sleep(UPDATE_INTERVAL)
    except Exception as exc:
        print(f"[ERROR] Unexpected runtime error: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

