import os
import sys
import time
import signal
import logging
from typing import List, Optional

from PIL import Image, ImageOps

try:
    from luma.core.interface.serial import i2c
    from luma.core.render import canvas
    from luma.oled.device import ssd1306
except ImportError:
    print("Missing dependencies. Install with: pip install luma.oled pillow")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class GifPlayer:
    """
    Plays animated GIF files on an SSD1306 OLED display via I2C.
    """

    def __init__(self, i2c_port: int = 1, i2c_address: int = 0x3C, width: int = 128, height: int = 64):
        self.width = width
        self.height = height
        self.gif_files: List[str] = []
        self.current_gif_index = 0
        self.is_running = True
        self.device = None

        try:
            serial = i2c(port=i2c_port, address=i2c_address)
            self.device = ssd1306(serial, width=width, height=height)
            logger.info(f"SSD1306 initialized on I2C bus {i2c_port} at address 0x{i2c_address:02X}")
        except Exception as e:
            logger.error(f"Failed to initialize SSD1306 display: {e}")
            raise

    def find_gif_files(self, folder_path: str) -> None:
        if not os.path.isdir(folder_path):
            logger.warning(f"Folder not found: {folder_path}")
            return
        try:
            self.gif_files = sorted(
                os.path.join(folder_path, f)
                for f in os.listdir(folder_path)
                if f.lower().endswith('.gif')
            )
            if not self.gif_files:
                logger.warning(f"No GIF files found in {folder_path}")
            else:
                logger.info(f"Found {len(self.gif_files)} GIF file(s).")
        except Exception as e:
            logger.error(f"Error searching folder {folder_path}: {e}")
            self.gif_files = []

    def play_gif(self, gif_path: str, loop_count: int = 0) -> None:
        if not gif_path or not os.path.isfile(gif_path):
            logger.error(f"GIF file not found: {gif_path}")
            return

        try:
            with Image.open(gif_path) as image:
                n_frames = image.n_frames
                duration_ms = []
                for frame_idx in range(n_frames):
                    image.seek(frame_idx)
                    duration_ms.append(image.info.get('duration', 100))

                loop_index = 0
                loop_counter = 0
                while self.is_running:
                    image.seek(loop_index)
                    frame = image.convert('RGB')
                    resized = ImageOps.fit(frame, (self.width, self.height), method='lanczos')
                    padded = ImageOps.pad(resized, (self.width, self.height), color='black')

                    with canvas(self.device) as draw:
                        draw.bitmap((0, 0), padded)

                    time.sleep(duration_ms[loop_index] / 1000.0)
                    loop_index = (loop_index + 1) % n_frames

                    if loop_index == 0:
                        loop_counter += 1
                        if loop_count > 0 and loop_counter >= loop_count:
                            break

        except Exception as e:
            logger.error(f"Error playing GIF {gif_path}: {e}")

    def play_all_gifs(self, loop_count: int = 0) -> None:
        if not self.gif_files:
            logger.warning("No GIF files loaded. Call find_gif_files() first.")
            return

        while self.is_running:
            gif_path = self.gif_files[self.current_gif_index]
            logger.info(f"Playing: {gif_path}")
            self.play_gif(gif_path, loop_count)
            if not self.is_running:
                break
