            logger.info(f"Playing: {gif_path}")
            self.play_gif(gif_path, loop_count)
            if not self.is_running:
                break
            self.current_gif_index = (self.current_gif_index + 1) % len(self.gif_files)

    def stop(self) -> None:
        self.is_running = False

    def cleanup(self) -> None:
        if self.device:
            try:
                self.device.cleanup()
                logger.info("Display resources released.")
            except Exception as e:
                logger.error(f"Error during display cleanup: {e}")


def main():
