import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1          # Raspberry Pi default I2C bus (physical pins 3/5)
PCF8574_ADDR = 0x20  # PCF8574 default I2C address (A0-A2 tied to GND)
POLL_INTERVAL = 0.1  # 100 milliseconds
RETRY_DELAY = 1.0    # seconds to wait before retrying after an error

# --- Globals for cleanup -----------------------------------------------------
_running = True
_bus = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _write_port(bus, value):
    """Write a byte to the PCF8574 output port register (P0-P7)."""
    bus.write_byte(PCF8574_ADDR, value)


def _read_port(bus):
    """Read the PCF8574 input port register (P0-P7)."""
    return bus.read_byte(PCF8574_ADDR)


def _configure_expander(bus):
    """
    Configure the PCF8574:
      - Write 0xFF to the output port (all pins HIGH, idle)
      - Read back the input port (reads current pin states)
    """
    _write_port(bus, 0xFF)  # idle output = all HIGH (active-low sensors)
    return _read_port(bus)


def _read_sensors(bus):
    """
    Read the eight proximity sensors.
    Returns a list of (sensor_index, is_obstacle) tuples.
    """
    port_state = _read_port(bus)
    return [
        (bit, (port_state >> bit) & 0x01 == 0)
        for bit in range(8)
    ]


def main():
    global _bus

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        _bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                port_state = _configure_expander(_bus)
                sensors = _read_sensors(_bus)

                for idx, is_obstacle in sensors:
                    if is_obstacle:
                        print(f"Obstacle detected by sensor {idx}")

                time.sleep(POLL_INTERVAL)

            except OSError as e:
                print(f"I2C error: {e}", file=sys.stderr)
                time.sleep(RETRY_DELAY)
            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)
                time.sleep(RETRY_DELAY)

    finally:
        if _bus is not None:
            try:
                _bus.close()
            except Exception:
                pass
        print("\nExiting program.")


if __name__ == "__main__":
    main()

