import time
import logging
import smbus2

logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 temperature/humidity sensor over I2C."""

    I2C_BUS = 1
    I2C_ADDR = 0x38
    REG_STATUS = 0x71
    REG_MEASURE = 0xAC
    MEASURE_CMD = [0x33, 0x00]
    MEASURE_DELAY = 0.1
    RETRY_DELAY = 2.0
    MAX_RETRIES = 5

    def __init__(self, bus_num=I2C_BUS, addr=I2C_ADDR):
        self.addr = addr
        self._bus = None
        self._open_bus(bus_num)

    def _open_bus(self, bus_num):
        try:
            self._bus = smbus2.SMBus(bus_num)
        except OSError as exc:
            logger.error("Failed to open I2C bus %d: %s", bus_num, exc)
            self._bus = None
            return False

        time.sleep(0.5)  # allow sensor to stabilize after power-on

        try:
            status = self._bus.read_byte_data(self.addr, self.REG_STATUS)
        except OSError as exc:
            logger.error("No sensor detected at 0x%02X on bus %d: %s", self.addr, bus_num, exc)
            self._bus.close()
            self._bus = None
            return False

        if (status & 0x18) != 0x18:
            logger.error("Sensor status 0x%02X does not indicate ready (bits 3-4 not set).", status)
            self._bus.close()
            self._bus = None
            return False

        logger.info("DHT20 initialized at 0x%02X on bus %d.", self.addr, bus_num)
        return True

    def _crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def get_temperature_and_humidity(self):
        if self._bus is None:
            logger.error("I2C bus not initialized.")
            return None, None, True

        for attempt in range(1, self.MAX_RETRIES + 1):
            try:
                self._bus.write_i2c_block_data(self.addr, self.REG_MEASURE, self.MEASURE_CMD)
            except OSError as exc:
                logger.error("I2C write error on attempt %d: %s", attempt, exc)
                time.sleep(self.RETRY_DELAY)
                continue

            time.sleep(self.MEASURE_DELAY)

            try:
                status = self._bus.read_byte_data(self.addr, self.REG_STATUS)
            except OSError as exc:
                logger.error("I2C read status error on attempt %d: %s", attempt, exc)
                time.sleep(self.RETRY_DELAY)
                continue

            if (status & 0x80) == 0:
                logger.warning("Measurement not complete on attempt %d (status 0x%02X).", attempt, status)
                time.sleep(self.RETRY_DELAY)
                continue

            try:
                data = self._bus.read_i2c_block_data(self.addr, self.REG_STATUS, 7)
            except OSError as exc:
                logger.error("I2C read data error on attempt %d: %s", attempt, exc)
                time.sleep(self.RETRY_DELAY)
                continue

            if self._crc8(data[:6]) != data[6]:
                logger.warning("CRC mismatch on attempt %d.", attempt)
                time.sleep(self.RETRY_DELAY)
                continue

            raw_h = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
            raw_t = ((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]
            temperature = raw_t / 5242.88 - 50.0
            humidity = raw_h / 1048576.0 * 100.0

            logger.info("Temperature: %.2f C, Humidity: %.2f %%", temperature, humidity)
            return temperature, humidity, False

        logger.error("Failed to read DHT20 after %d retries.", self.MAX_RETRIES)
        return None, None, True

    def close(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            self._bus = None

    def __del__(self):
        self.close()


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    sensor = DHT20()
    if sensor._bus is not None:
        for _ in range(5):
            temp, hum, err = sensor.get_temperature_and_humidity()
            if err:
                logger.error("Measurement failed.")
            else:
                logger.info("Reading: %.2f C, %.2f %%", temp, hum)
            time.sleep(1.0)
    sensor.close()

