import signal
import sys
import time

from gpiozero import LED

try:
    from hcsr04sensor import HCSR04
except ImportError:
    print("Error: hcsr04sensor library not found. Install with: pip install hcsr04sensor")
    sys.exit(1)

# Define GPIO pins
TRIGGER_PIN = 17
ECHO_PIN = 18
LED_PIN = 2

# Define safe distance (cm)
SAFE_DISTANCE = 20

# Global resources for cleanup
led = None
sensor = None
running = True


def cleanup(signum=None, frame=None):
    """Release resources on exit or signal."""
    global running, led, sensor
    running = False
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if sensor is not None:
        try:
            sensor.close()
        except Exception:
            pass
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting.")
    else:
        print("\nExiting program.")


# Register signal handlers for graceful shutdown
signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

# Initialize the LED
try:
    led = LED(LED_PIN)
except Exception as e:
    print(f"Error initializing LED on GPIO{LED_PIN}: {e}")
    sys.exit(1)

# Initialize the HCSR04 sensor
try:
    sensor = HCSR04(
        trigger_pin=TRIGGER_PIN,
        echo_pin=ECHO_PIN,
        temperature=20,
    )
except Exception as e:
    print(f"Error initializing HCSR04 on trigger=GPIO{TRIGGER_PIN}, echo=GPIO{ECHO_PIN}: {e}")
    cleanup()
    sys.exit(1)

print("Parking Sensor Program Started")

try:
    while running:
        try:
            distance = sensor.get_distance()
        except Exception as e:
            print(f"Error reading sensor: {e}")
            distance = SAFE_DISTANCE + 10  # Force LED off on failure

        print(f"Distance: {distance} cm, LED: {'ON' if distance <= SAFE_DISTANCE else 'OFF'}")

        if distance <= SAFE_DISTANCE:
            led.on()
        else:
            led.off()

        time.sleep(0.1)

finally:
    cleanup()

