import time
import random
import sqlite3
import logging
import signal
import sys
from gpiozero import LED

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

STATUS_LED_PIN = 23
DATABASE_PATH = '/tmp/wearable_health.db'
ALERT_THRESHOLD = 100.0
WINDOW_SIZE = 20
NUM_ITERATIONS = 30

running = True

def signal_handler(signum, frame):
    global running
    running = False

def get_vibration_reading():
    return random.uniform(0.1, 0.9)

def get_temperature_reading():
    return random.uniform(30.0, 70.0)

def calculate_degradation_score(vibration_history, temperature_history):
    if not vibration_history or not temperature_history:
        return 0.0
    mean_vibration = sum(vibration_history) / len(vibration_history)
    mean_temperature = sum(temperature_history) / len(temperature_history)
    return 0.6 * mean_vibration + 0.4 * (mean_temperature / 100.0)

def estimate_remaining_life(degradation_score):
    return max(0.0, 500.0 * (2.71828 ** (-3.0 * degradation_score)))

def store_alert(conn, remaining_life):
    try:
        cursor = conn.cursor()
        cursor.execute('INSERT INTO alerts (remaining_life, ts) VALUES (?, ?)', (remaining_life, time.time()))
        conn.commit()
        logging.info(f'Alert stored: remaining life = {remaining_life:.2f} hours')
    except sqlite3.Error as e:
        logging.error(f'Database error storing alert: {e}')

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        led = LED(STATUS_LED_PIN)
    except Exception as e:
        logging.error(f'Failed to initialize GPIO pin {STATUS_LED_PIN}: {e}')
        sys.exit(1)

    try:
        conn = sqlite3.connect(DATABASE_PATH)
        cursor = conn.cursor()
        cursor.execute('''CREATE TABLE IF NOT EXISTS alerts (
                            id INTEGER PRIMARY KEY AUTOINCREMENT,
                            remaining_life REAL,
                            ts REAL
                        )''')
        conn.commit()
    except sqlite3.Error as e:
        logging.error(f'Database error: {e}')
        led.close()
        sys.exit(1)

    vibration_history = []
    temperature_history = []
    alert_active = False

    try:
        for i in range(NUM_ITERATIONS):
            if not running:
                break

            try:
                vibration = get_vibration_reading()
                temperature = get_temperature_reading()
            except Exception as e:
                logging.error(f'Sensor read error: {e}')
                time.sleep(0.05)
                continue

            vibration_history.append(vibration)
            temperature_history.append(temperature)
            if len(vibration_history) > WINDOW_SIZE:
                vibration_history.pop(0)
            if len(temperature_history) > WINDOW_SIZE:
                temperature_history.pop(0)

            degradation_score = calculate_degradation_score(vibration_history, temperature_history)
            remaining_life = estimate_remaining_life(degradation_score)

            if remaining_life < ALERT_THRESHOLD and not alert_active:
                logging.warning(f'Alert: remaining life = {remaining_life:.2f} hours')
                store_alert(conn, remaining_life)
                alert_active = True
                try:
                    led.blink(on_time=1, off_time=1, background=True)
                except Exception as e:
                    logging.error(f'Failed to start LED blink: {e}')

            if remaining_life >= ALERT_THRESHOLD and alert_active:
                alert_active = False
                try:
                    led.off()
                except Exception as e:
                    logging.error(f'Failed to turn off LED: {e}')

            time.sleep(0.05)

    except Exception as e:
        logging.error(f'Unexpected error: {e}')
    finally:
        try:
            led.off()
            led.close()
        except Exception:
            pass
        try:
            conn.close()
        except Exception:
            pass
        logging.info('Cleanup complete. Exiting.')

if __name__ == '__main__':
    main()

