#!/usr/bin/env python3
"""
Read and print CPU temperature every 5 seconds on Raspberry Pi 4 Model B.

Uses gpiozero.CPUTemperature (modern Linux sysfs backend).  The
temperature file is lazily opened so missing /sys/class/thermal/thermal_zone0/temp
is caught per-read and does not crash the program at startup.
"""

import time
import sys

from gpiozero import CPUTemperature


def read_cpu_temp() -> float:
    """Return CPU temperature in °C, raising on any read failure."""
    cpu = CPUTemperature()
    try:
        return float(cpu.temperature)
    finally:
        # gpiozero objects are lightweight; close is safe and fast.
        cpu.close()


def main() -> int:
    print("Starting CPU temperature monitoring...")
    try:
        while True:
            try:
                temp_c = read_cpu_temp()
                print(f"CPU Temperature: {temp_c:.2f} °C")
            except FileNotFoundError:
                # Transient failure: thermal zone not present yet, or sensor absent.
                print("Error: CPU temperature file not found.")
            except Exception as exc:
                # Covers OSError, ValueError, and any other unexpected read failure.
                print(f"Error reading CPU temperature: {exc}")
            time.sleep(5)
    except KeyboardInterrupt:
        print("\nProgram terminated")
        return 0
    except Exception as exc:
        print(f"An unexpected error occurred: {exc}")
        return 1


if __name__ == "__main__":
    sys.exit(main())

