#!/usr/bin/env python3
"""
Greenhouse Vent Controller using RPi.GPIO
Controls two SG90 servos based on simulated temperature readings.
"""

import RPi.GPIO as GPIO
import time
import random
import logging
import sys

# Configure logging
logging.basicConfig(
    filename='greenhouse_vent.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# GPIO pin definitions (BCM numbering)
SERVO_PIN_1 = 17
SERVO_PIN_2 = 18

# Servo parameters
PWM_FREQUENCY = 50  # Hz
TEMP_MIN = 15.0
TEMP_MAX = 35.0
FAILURE_RATE = 0.10  # 10%

# SG90 duty-cycle mapping: 0°=2.5%, 90°=7.5%, 180°=12.5%
DUTY_0 = 2.5
DUTY_90 = 7.5
DUTY_180 = 12.5

# Global state
servo1_pwm = None
servo2_pwm = None
servo1_failed = False
servo1_failure_count = 0
servo2_active = False


def angle_to_duty(angle):
    """Convert angle (0-180) to SG90 duty cycle percentage."""
    if angle <= 0:
        return DUTY_0
    elif angle >= 180:
        return DUTY_180
    else:
        return DUTY_0 + (angle / 180.0) * (DUTY_180 - DUTY_0)


def move_servo(pwm, target_angle, step=5, delay=0.1):
    """Move servo smoothly to target angle in 5-degree steps."""
    try:
        current_duty = pwm._duty_cycle
        current_angle = (current_duty - DUTY_0) / (DUTY_180 - DUTY_0) * 180.0
        if current_angle < 0:
            current_angle = 0
        elif current_angle > 180:
            current_angle = 180

        if target_angle < 0:
            target_angle = 0
        elif target_angle > 180:
            target_angle = 180

        if target_angle > current_angle:
            angles = range(int(current_angle), int(target_angle) + 1, step)
        else:
            angles = range(int(current_angle), int(target_angle) - 1, -step)

        for angle in angles:
            duty = angle_to_duty(angle)
            pwm.ChangeDutyCycle(duty)
            time.sleep(delay)

        # Ensure final position
        pwm.ChangeDutyCycle(angle_to_duty(target_angle))
        logging.info(f"Servo moved to {target_angle} degrees")
    except Exception as e:
        logging.error(f"Error moving servo: {e}")


def simulate_temperature():
    """Simulate temperature reading with random fluctuations."""
    base = random.uniform(TEMP_MIN, TEMP_MAX)
    fluctuation = random.uniform(-2.0, 2.0)
    return base + fluctuation


def set_vent_position(temperature):
    """Set servo position based on temperature with smooth movement."""
    global servo1_failure_count, servo2_active

    if temperature < 20:
        target = 0
    elif 20 <= temperature < 25:
        target = 45
    elif 25 <= temperature < 30:
        target = 90
    elif 30 <= temperature < 35:
        target = 135
    else:
        target = 180

    if servo1_failed and not servo2_active:
        logging.warning("Servo 1 failed; switching to Servo 2")
        servo2_active = True
        if servo2_pwm is not None:
            move_servo(servo2_pwm, target)
        return

    if not servo1_failed:
        if random.random() < FAILURE_RATE:
            logging.error("Servo 1 failed")
            servo1_failed = True
            servo1_failure_count += 1
            if servo1_failure_count >= 3:
                logging.warning("3 consecutive Servo 1 failures; switching to Servo 2")
                servo2_active = True
                if servo2_pwm is not None:
                    move_servo(servo2_pwm, target)
            else:
                logging.warning(f"Servo 1 failure #{servo1_failure_count}")
        else:
            if servo1_pwm is not None:
                move_servo(servo1_pwm, target)
    else:
        if servo2_pwm is not None:
            move_servo(servo2_pwm, target)


def cleanup():
    """Clean up GPIO and PWM resources."""
    global servo1_pwm, servo2_pwm
    logging.info("Cleaning up GPIO...")
    try:
        if servo1_pwm is not None:
            servo1_pwm.stop()
            servo1_pwm = None
        if servo2_pwm is not None:
            servo2_pwm.stop()
            servo2_pwm = None
        GPIO.cleanup()
        logging.info("GPIO cleanup complete")
    except Exception as e:
        logging.error(f"Error during cleanup: {e}")


def main():
    global servo1_pwm, servo2_pwm

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(SERVO_PIN_1, GPIO.OUT)
        GPIO.setup(SERVO_PIN_2, GPIO.OUT)

        servo1_pwm = GPIO.PWM(SERVO_PIN_1, PWM_FREQUENCY)
        servo2_pwm = GPIO.PWM(SERVO_PIN_2, PWM_FREQUENCY)
        servo1_pwm.start(0)
        servo2_pwm.start(0)

        logging.info("Greenhouse vent controller started")

        while True:
            temperature = simulate_temperature()
            logging.info(f"Temperature: {temperature:.2f}°C")
            set_vent_position(temperature)
            time.sleep(5)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        cleanup()
        sys.exit(0)


if __name__ == "__main__":
    main()

