import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

def main():
    # Initialize I2C bus on board.SCL (GPIO3) and board.SDA (GPIO2)
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return

    # Initialize TCA9548A I2C multiplexer at default address 0x70
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus, address=0x70)
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer at 0x70: {e}")
        return

    # Initialize BME280 sensor on multiplexer channel 0 (default address 0x76 or 0x77)
    try:
        bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0], address=0x76)
    except Exception as e:
        print(f"Error initializing BME280 sensor on channel 0: {e}")
        return

    # Initialize TSL2591 sensor on multiplexer channel 1 (default address 0x29)
    try:
        tsl2591_sensor = adafruit_tsl2591.TSL2591(multiplexer[1])
    except Exception as e:
        print(f"Error initializing TSL2591 sensor on channel 1: {e}")
        return

    # Main loop for reading sensor data
    try:
        while True:
            try:
                # Read temperature and humidity from BME280
                temperature = bme280_sensor.temperature
                humidity = bme280_sensor.humidity

                # Read light intensity from TSL2591
                light_intensity = tsl2591_sensor.lux

                # Print sensor readings with two decimal places
                print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Light: {light_intensity:.2f} lux")

            except Exception as e:
                print(f"Error reading sensor data: {e}")

            # Wait for 2 seconds before the next reading
            time.sleep(2)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")

if __name__ == "__main__":
    main()

