import time
import datetime
import json
import logging
import random
import signal
import sys
import urllib.request
import urllib.error

try:
    import adafruit_dht
    import board
except ImportError:
    adafruit_dht = None
    board = None

CONFIG_FILE = 'config.json'
LOG_FILE = 'greenhouse.log'

DEFAULT_CONFIG = {
    'webhook_url': 'https://example.com/webhook',
    'temperature_threshold': 30.0,
    'humidity_threshold': 80.0,
    'vent_fan_threshold': 30.0,
    'water_pump_threshold': 60.0,
    'heater_threshold': 15.0,
    'dht_pin': 4,
    'data_acquisition_interval': 60,
    'moving_average_window': 5,
    'webhook_retries': 3,
    'webhook_retry_backoff': [1, 3, 9],
    'sensor_failure_timeout': 300,
    'simulate_sensor_data': True,
    'log_level': 'INFO'
}

running = True


def signal_handler(signum, frame):
    global running
    running = False


def load_config(config_file=CONFIG_FILE):
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        merged = DEFAULT_CONFIG.copy()
        merged.update(config)
        return merged
    except FileNotFoundError:
        logging.warning(f"Configuration file '{config_file}' not found. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Error decoding JSON from '{config_file}': {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()


def setup_logging(log_level):
    numeric_level = getattr(logging, log_level.upper(), None)
    if not isinstance(numeric_level, int):
        numeric_level = logging.INFO
    logging.basicConfig(
        filename=LOG_FILE,
        level=numeric_level,
        format='%(asctime)s - %(levelname)s - %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S'
    )
    logging.info("Logging initialized.")


def simulate_sensor_data():
    temperature = round(random.uniform(20, 30), 1)
    humidity = round(random.uniform(60, 80), 1)
    return temperature, humidity


def read_dht22_sensor(dht_device, simulate):
    if simulate:
        return simulate_sensor_data()
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None")
        return round(temperature, 1), round(humidity, 1)
    except RuntimeError as e:
        logging.error(f"DHT22 read error: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Unexpected DHT22 error: {e}")
        return None, None


def validate_data(temperature, humidity):
    if temperature is None or humidity is None:
        return False
    if not (-40 <= temperature <= 80):
        logging.warning(f"Invalid temperature: {temperature}. Discarding.")
        return False
    if not (0 <= humidity <= 100):
        logging.warning(f"Invalid humidity: {humidity}. Discarding.")
        return False
    return True


def calculate_moving_average(data, window_size):
    if not data:
        return None
    if len(data) < window_size:
        return sum(data) / len(data)
    return sum(data[-window_size:]) / window_size


def send_webhook(webhook_url, temperature, humidity, retries, backoff):
    payload = {
        'temperature': temperature,
        'humidity': humidity,
        'timestamp': datetime.datetime.now().isoformat()
    }
    json_data = json.dumps(payload).encode('utf-8')
    headers = {'Content-Type': 'application/json'}
    for attempt in range(retries):
        try:
            req = urllib.request.Request(webhook_url, data=json_data, headers=headers, method='POST')
            with urllib.request.urlopen(req, timeout=10) as response:
                if 200 <= response.status < 300:
                    logging.info(f"Webhook sent successfully. Status: {response.status}")
                    return True
                else:
                    logging.error(f"Webhook failed. Status: {response.status}")
        except urllib.error.URLError as e:
            logging.error(f"Webhook URL error: {e}")
        except Exception as e:
            logging.error(f"Webhook error: {e}")
        if attempt < retries - 1:
            time.sleep(backoff[attempt])
    logging.error("Webhook failed after all retries.")
    return False


def control_actuators(temperature, humidity, config):
    if temperature > config['vent_fan_threshold']:
        logging.info("Activating vent fan.")
    else:
        logging.info("Deactivating vent fan.")
    if humidity < config['water_pump_threshold']:
        logging.info("Activating water pump.")
    else:
        logging.info("Deactivating water pump.")
    if temperature < config['heater_threshold']:
        logging.info("Activating heater.")
    else:
        logging.info("Deactivating heater.")


def main():
    global running
    config = load_config()
    setup_logging(config['log_level'])
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    logging.info("Starting greenhouse monitoring system.")
    dht_device = None
    if adafruit_dht is not None and board is not None:
        try:
            pin = getattr(board, f'D{config["dht_pin"]}')
            dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
            logging.info(f"DHT22 initialized on GPIO{config['dht_pin']}.")
        except Exception as e:
            logging.error(f"Failed to initialize DHT22: {e}")
            dht_device = None
    else:
        logging.warning("adafruit-circuitpython-dht or board not available. Running in simulation mode.")
    temperature_readings = []
    humidity_readings = []
    sensor_failure_count = 0
    last_failure_time = None
    try:
        while running:
            temperature, humidity = read_dht22_sensor(dht_device, config['simulate_sensor_data'])
            if temperature is not None and humidity is not None:
                if validate_data(temperature, humidity):
                    temperature_readings.append(temperature)
                    humidity_readings.append(humidity)
                    logging.info(f"Temperature: {temperature}°C, Humidity: {humidity}%")
                    sensor_failure_count = 0
                    last_failure_time = None
                else:
                    logging.warning("Invalid sensor data. Skipping.")
            else:
                sensor_failure_count += 1
                if last_failure_time is None:
                    last_failure_time = time.time()
                logging.warning(f"Sensor read failed. Count: {sensor_failure_count}")
                if sensor_failure_count >= 3:
                    logging.warning("3 consecutive sensor failures. Pausing data acquisition.")
                    time.sleep(config['sensor_failure_timeout'])
                    logging.info("Resetting sensor failure count.")
                    sensor_failure_count = 0
                    last_failure_time = None
            temperature_avg = calculate_moving_average(temperature_readings, config['moving_average_window'])
            humidity_avg = calculate_moving_average(humidity_readings, config['moving_average_window'])
            if temperature_avg is not None and humidity_avg is not None:
                logging.info(f"Moving Avg Temp: {temperature_avg:.1f}°C, Avg Humidity: {humidity_avg:.1f}%")
                if temperature_avg > config['temperature_threshold'] or humidity_avg > config['humidity_threshold']:
                    logging.info("Threshold exceeded. Sending webhook.")
                    send_webhook(
                        config['webhook_url'],
                        temperature_avg,
                        humidity_avg,
                        config['webhook_retries'],
                        config['webhook_retry_backoff']
                    )
                control_actuators(temperature_avg, humidity_avg, config)
            else:
                logging.info("Not enough data for moving average.")
            for _ in range(config['data_acquisition_interval']):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if dht_device is not None:
            try:
                dht_device.exit()
                logging.info("DHT22 device released.")
            except Exception as e:
                logging.error(f"Error releasing DHT22: {e}")
        logging.info("Exiting greenhouse monitoring system.")


if __name__ == "__main__":
    main()

