                    humidity_readings.append(humidity)
                    logging.info(f"Temperature: {temperature}°C, Humidity: {humidity}%")
                    sensor_failure_count = 0
                    last_failure_time = None
                else:
                    logging.warning("Invalid sensor data. Skipping.")
            else:
                sensor_failure_count += 1
                if last_failure_time is None:
                    last_failure_time = time.time()
                logging.warning(f"Sensor read failed. Count: {sensor_failure_count}")
                if sensor_failure_count >= 3:
                    logging.warning("3 consecutive sensor failures. Pausing data acquisition.")
                    time.sleep(config['sensor_failure_timeout'])
                    logging.info("Resetting sensor failure count.")
                    sensor_failure_count = 0
                    last_failure_time = None
            temperature_avg = calculate_moving_average(temperature_readings, config['moving_average_window'])
            humidity_avg = calculate_moving_average(humidity_readings, config['moving_average_window'])
            if temperature_avg is not None and humidity_avg is not None:
                logging.info(f"Moving Avg Temp: {temperature_avg:.1f}°C, Avg Humidity: {humidity_avg:.1f}%")
                if temperature_avg > config['temperature_threshold'] or humidity_avg > config['humidity_threshold']:
                    logging.info("Threshold exceeded. Sending webhook.")
                    send_webhook(
                        config['webhook_url'],
                        temperature_avg,
                        humidity_avg,
                        config['webhook_retries'],
                        config['webhook_retry_backoff']
                    )
                control_actuators(temperature_avg, humidity_avg, config)
            else:
                logging.info("Not enough data for moving average.")
            for _ in range(config['data_acquisition_interval']):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if dht_device is not None:
            try:
                dht_device.exit()
                logging.info("DHT22 device released.")
            except Exception as e:
                logging.error(f"Error releasing DHT22: {e}")
        logging.info("Exiting greenhouse monitoring system.")


if __name__ == "__main__":
    main()

