import logging

import paho.mqtt.client as mqtt
import adafruit_dht
import board

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)

DEGREE_CELSIUS = '\u00B0C'

running = True


def signal_handler(signum, frame):
    global running
    logger.info('Signal %s received, shutting down...', signum)
    running = False


def publish(client, topic, payload):
    try:
        full_topic = f'homie/{config.homieclientid}/{topic}'
        info = client.publish(full_topic, str(payload), qos=1)
        info.wait_for_publish(timeout=5)
    except Exception as e:
        logger.error('MQTT publish error on %s: %s', topic, e)


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info('Connected to MQTT broker')
    else:
        logger.error('MQTT connection failed with reason code %s', reason_code)


def on_disconnect(client, userdata, flags, reason_code, properties):
    if reason_code != 0:
        logger.warning('Unexpected MQTT disconnect (rc=%s); will auto-reconnect', reason_code)
    else:
        logger.info('MQTT disconnected cleanly')


def publish_homie_discovery(client):
    publish(client, '$' + prop for prop, val in (
        ('homie', '4.0'),
        ('name', config.homieclientname),
        ('nodes', config.homienodes),
    ))
    publish(client, f'{config.homienodes}/$name', 'DHT22 Sensor')
    publish(client, f'{config.homienodes}/$properties', 'temperature,humidity')
    for prop, name, unit in (
        ('temperature', 'Temperature', DEGREE_CELSIUS),
        ('humidity', 'Humidity', '%'),
    ):
        publish(client, f'{config.homienodes}/{prop}/$name', name)
        publish(client, f'{config.homienodes}/{prop}/$unit', unit)
        publish(client, f'{config.homienodes}/{prop}/$datatype', 'float')
        publish(client, f'{config.homienodes}/{prop}/$settable', 'false')


def main():
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

