        pin = getattr(board, f'D{config.dhtgpiopin}', None)
        if pin is None:
            raise ValueError(f'Invalid GPIO pin: {config.dhtgpiopin}')
        dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
    except Exception as e:
        logger.error('Failed to initialize DHT22 on GPIO%s: %s', config.dhtgpiopin, e)
        sys.exit(1)

    time.sleep(2)  # DHT22 warm-up

    client = mqtt.Client(
        callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
        client_id=config.mqttclientid,
    )
    if config.mqttusername:
        client.username_pw_set(config.mqttusername, config.mqttpassword)
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect

    try:
        client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
    except Exception as e:
        logger.error('Initial MQTT connect failed: %s', e)
        dht_device.exit()
        sys.exit(1)

    client.loop_start()
    publish_homie_discovery(client)

    try:
        while running:
            if not client.is_connected():
                logger.warning('MQTT not connected; attempting reconnect...')
                try:
                    client.reconnect()
                except Exception as e:
                    logger.error('Reconnect failed: %s', e)
                    time.sleep(5)
                    continue

            temperature = None
            humidity = None

            for attempt in range(3):
                try:
                    temperature = dht_device.temperature
                    humidity = dht_device.humidity
                    if temperature is not None and humidity is not None:
                        break
                except RuntimeError as e:
                    logger.warning('DHT22 read attempt %d failed: %s', attempt + 1, e)
                except Exception as e:
                    logger.error('Unexpected DHT22 error: %s', e)
                time.sleep(2)

            if temperature is not None and humidity is not None:
                logger.info('Temperature = %.1f %s, Humidity = %.1f %%', temperature, DEGREE_CELSIUS, humidity)
                publish(client, f'{config.homienodes}/temperature', f'{temperature:.1f}')
                publish(client, f'{config.homienodes}/humidity', f'{humidity:.1f}')
            else:
                logger.error('DHT22 read failed after 3 attempts')

            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)
    finally:
        logger.info('Cleaning up...')
        client.loop_stop()
        client.disconnect()
        dht_device.exit()
        logger.info('Done.')


if __name__ == '__main__':
    main()

