import time
import board
import adafruit_dht

# Configuration
DHT_PIN = board.D22  # GPIO22 (BCM) — physical pin 15
READ_INTERVAL = 3.0  # seconds between readings
RETRY_DELAY = 0.1    # seconds between retries
MAX_RETRIES = 2


def read_dht22_sensor(sensor):
    """
    Read temperature (°C) and humidity (%) from the DHT22 sensor.
    Retries up to MAX_RETRIES times on transient errors.
    Returns (temperature, humidity) or (None, None) on failure.
    """
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity

            # Validate readings are within DHT22 operational ranges
            if temperature is None or humidity is None:
                raise RuntimeError("Sensor returned None for temperature or humidity")
            if not (-40.0 <= temperature <= 80.0):
                raise RuntimeError(f"Temperature out of range: {temperature}")
            if not (0.0 <= humidity <= 100.0):
                raise RuntimeError(f"Humidity out of range: {humidity}")

            return temperature, humidity

        except RuntimeError as e:
            # Common DHT errors: checksum mismatch, timeout, or device not present
            print(f"Read error (attempt {attempt}/{MAX_RETRIES}): {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
        except Exception as e:
            # Unexpected error — log and stop retrying
            print(f"Unexpected error reading DHT22: {e}")
            return None, None

    return None, None


def display_sensor_data(temperature, humidity):
    """Print temperature and humidity with one decimal place."""
    if temperature is not None and humidity is not None:
        print(f"Temperature: {temperature:.1f} °C")
        print(f"Humidity: {humidity:.1f} %")
    else:
        print("Failed to retrieve valid data from the DHT22 sensor.")


def main():
    """Initialize the DHT22 sensor, then continuously read and display data."""
    sensor = None
    try:
        # Initialize the DHT22 sensor on GPIO22
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        print("DHT22 sensor initialized on GPIO22.")

        # Allow the sensor to stabilize after power-up
        time.sleep(1.0)

        while True:
            temperature, humidity = read_dht22_sensor(sensor)
            display_sensor_data(temperature, humidity)
            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        # Clean up sensor resources
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass
        print("Exiting program.")


if __name__ == "__main__":
    main()

