# Global sensor handle so the signal handler can release it.
_sensor = None

def cleanup():
    """Release the sensor resource if it exists."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print(f"\nReceived signal {signum}, exiting...")
    cleanup()
    sys.exit(0)

def main():
    global _sensor

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize the DHT11 sensor on GPIO4 (board.D4)
    try:
        _sensor = adafruit_dht.DHT11(board.D4, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 sensor on GPIO4: {e}")
        sys.exit(1)

    print("DHT11 sensor initialized on GPIO4. Reading every 5 seconds. Press Ctrl+C to stop.")

    try:
        while True:
            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity

                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
