                print(f"Unexpected error during read: {e}")

            time.sleep(5)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        cleanup()
        print("Sensor resources released. Exiting.")

if __name__ == "__main__":
