import time
import board
import busio
import adafruit_bmp280

# Constants
I2C_ADDRESS = 0x76  # Default I2C address for most BMP280 breakout boards
BASELINE_DURATION = 10  # Seconds to collect baseline pressure
BASELINE_INTERVAL = 1   # Seconds between baseline readings
READ_INTERVAL = 1        # Seconds between altitude readings
NUM_BASELINE_SKIPS = 2  # Number of initial readings to skip for stability


def initialize_i2c():
    """Initializes the I2C bus using board.I2C()."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_bmp280(i2c_bus, address=I2C_ADDRESS):
    """Initializes the BMP280 sensor at the specified I2C address."""
    try:
        sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=address)
        return sensor
    except ValueError as e:
        print(f"BMP280 not found at address 0x{address:02X}. Check wiring and address. Details: {e}")
        return None
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return None


def read_pressure(sensor):
    """Reads the pressure from the BMP280 sensor."""
    try:
        return sensor.pressure
    except OSError as e:
        print(f"OSError reading pressure: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading pressure: {e}")
        return None


def calculate_altitude(sensor, sea_level_pressure):
    """Calculates the altitude based on the current pressure and sea level pressure."""
    current_pressure = read_pressure(sensor)
    if current_pressure is None:
        return None
    try:
        altitude = 44330 * (1 - (current_pressure / sea_level_pressure) ** (1 / 5.255))
        return altitude
    except Exception as e:
        print(f"Error calculating altitude: {e}")
        return None


def collect_baseline_pressure(sensor, duration=BASELINE_DURATION, interval=BASELINE_INTERVAL, num_skips=NUM_BASELINE_SKIPS):
    """Collects baseline pressure readings and calculates the average."""
    print("Collecting baseline pressure...")
    pressure_readings = []
    start_time = time.monotonic()

    while time.monotonic() - start_time < duration:
        pressure = read_pressure(sensor)
        if pressure is not None:
            pressure_readings.append(pressure)
            print(f"Baseline reading: {pressure:.2f} hPa")
        else:
            print("Failed to read pressure.")

        time.sleep(interval)

    # Exclude the first few readings to avoid early instability
    valid_readings = pressure_readings[num_skips:]

    if not valid_readings:
        print("Error: No valid baseline readings collected.")
        return None

    average_pressure = sum(valid_readings) / len(valid_readings)
    print(f"Baseline pressure: {average_pressure:.2f} hPa")
    return average_pressure


def main():
    """Main function to read and display altitude."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    bmp280_sensor = initialize_bmp280(i2c_bus)
    if bmp280_sensor is None:
        return

    try:
        sea_level_pressure = collect_baseline_pressure(bmp280_sensor)
        if sea_level_pressure is None:
            return

        print("Starting altitude readings...")
        while True:
            altitude = calculate_altitude(bmp280_sensor, sea_level_pressure)
            if altitude is not None:
                print(f"Altitude: {altitude:.2f} meters")
            else:
                print("Failed to calculate altitude.")
            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")


if __name__ == "__main__":
    main()

