import time
import logging
import signal
import sys
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class DHT20:
    """Driver for the Aosong DHT20 temperature/humidity sensor on I2C."""

    I2C_BUS = 1
    I2C_ADDR = 0x38
    REG_STATUS = 0x71
    REG_MEASURE = 0xAC
    MEASURE_CMD = [0x33, 0x00]
    CRC_POLYNOMIAL = 0x31
    CRC_INITIAL = 0xFF
    MIN_MEASUREMENT_INTERVAL = 2.0
    MAX_MEASUREMENT_ATTEMPTS = 5
    MAX_STATUS_POLL_ATTEMPTS = 10
    STATUS_POLL_DELAY = 0.08
    POWER_ON_DELAY = 0.5

    def __init__(self, i2c_bus=I2C_BUS, i2c_address=I2C_ADDR):
        self.i2c_bus = i2c_bus
        self.i2c_address = i2c_address
        self._bus = None
        self._last_measurement_time = 0.0
        self._last_temperature = None
        self._last_humidity = None
        self._running = True

    def begin(self):
        try:
            self._bus = SMBus(self.i2c_bus)
        except OSError as e:
            logging.error(f"Failed to open I2C bus {self.i2c_bus}: {e}")
            return False

        try:
            time.sleep(self.POWER_ON_DELAY)
            status = self._read_register(self.REG_STATUS, 1)[0]
            if (status & 0x18) != 0x18:
                logging.error(f"DHT20 status check failed: 0x{status:02X}")
                self.close()
                return False
        except OSError as e:
            logging.error(f"Failed to read DHT20 status register: {e}")
            self.close()
            return False

        logging.info("DHT20 initialized successfully.")
        return True

    def _read_register(self, register, length):
        if self._bus is None:
            raise OSError("I2C bus is not initialized.")
        return self._bus.read_i2c_block_data(self.i2c_address, register, length)

    def _write_register(self, register, data):
        if self._bus is None:
            raise OSError("I2C bus is not initialized.")
        self._bus.write_i2c_block_data(self.i2c_address, register, data)

    def _calculate_crc8(self, data):
        crc = self.CRC_INITIAL
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ self.CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _trigger_measurement(self):
        self._write_register(self.REG_MEASURE, self.MEASURE_CMD)

    def _wait_for_measurement_ready(self):
        for _ in range(self.MAX_STATUS_POLL_ATTEMPTS):
            time.sleep(self.STATUS_POLL_DELAY)
            status = self._read_register(self.REG_STATUS, 1)[0]
            if (status & 0x80) == 0:
                return True
        return False

    def _read_measurement_data(self):
        data = self._read_register(self.REG_STATUS, 7)
        calculated_crc = self._calculate_crc8(data[:6])
        received_crc = data[6]
        if calculated_crc != received_crc:
            logging.warning(
                f"CRC mismatch: calculated 0x{calculated_crc:02X}, received 0x{received_crc:02X}"
            )
            return None, None
        humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
        humidity = float(humidity_raw) / (1 << 20) * 100.0
        temperature = float(temperature_raw) / (1 << 19) * 200.0 - 50.0
        return temperature, humidity

    def get_temperature_and_humidity(self):
        if not self._running:
            return None, None, True

        current_time = time.time()
        if current_time - self._last_measurement_time < self.MIN_MEASUREMENT_INTERVAL:
            logging.info("Returning cached temperature and humidity.")
            return self._last_temperature, self._last_humidity, False

        for attempt in range(self.MAX_MEASUREMENT_ATTEMPTS):
            try:
                self._trigger_measurement()
                if not self._wait_for_measurement_ready():
                    logging.warning("Measurement timed out.")
                    time.sleep(0.01)
                    continue
                temperature, humidity = self._read_measurement_data()
                if temperature is not None and humidity is not None:
                    self._last_measurement_time = current_time
                    self._last_temperature = temperature
                    self._last_humidity = humidity
                    logging.info(
                        f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%"
                    )
                    return temperature, humidity, False
                time.sleep(0.01)
            except OSError as e:
                logging.error(f"I2C error during measurement: {e}")
                time.sleep(0.01)

        logging.error("Failed to get valid measurement after multiple attempts.")
        return None, None, True

    def close(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            self._bus = None

    def __enter__(self):
        if not self.begin():
            raise RuntimeError("DHT20 initialization failed.")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()


def _signal_handler(signum, frame):
    raise KeyboardInterrupt


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        with DHT20() as sensor:
            while sensor._running:
                try:
                    temperature, humidity, error = sensor.get_temperature_and_humidity()
                    if error:
                        logging.error("Measurement failed.")
                    time.sleep(1.0)
                except KeyboardInterrupt:
                    logging.info("Exiting program.")
                    break
    except RuntimeError as e:
        logging.error(str(e))
        sys.exit(0)
    except KeyboardInterrupt:
        logging.info("Exiting program.")


if __name__ == "__main__":
    main()

