import time
import logging
import signal
import sys
import board
import adafruit_dht

# Configure logging to both console and a file
logging.basicConfig(
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.StreamHandler(sys.stdout),
        logging.FileHandler('wildlife_monitoring.log')
    ]
)

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Shutdown signal received. Exiting gracefully...")

def read_dht22(pin, retries=3, retry_delay=2):
    """
    Reads temperature and humidity from a DHT22 sensor using adafruit-circuitpython-dht.
    Handles transient read errors by retrying up to retries times.
    Returns (temperature, humidity) or (None, None) on failure.
    """
    dht_device = None
    try:
        # Map BCM pin number to board pin name
        pin_map = {
            4: board.D4,
            17: board.D17
        }
        if pin not in pin_map:
            logging.error(f"Invalid pin number: {pin}")
            return None, None

        dht_device = adafruit_dht.DHT22(pin_map[pin], use_pulseio=False)

        for attempt in range(1, retries + 1):
            try:
                temperature = dht_device.temperature
                humidity = dht_device.humidity

                # Validate readings
                if temperature is None or humidity is None:
                    raise RuntimeError("Sensor returned None")

                if not (-40 <= temperature <= 80):
                    raise RuntimeError(f"Temperature out of range: {temperature}")
                if not (0 <= humidity <= 100):
                    raise RuntimeError(f"Humidity out of range: {humidity}")

                return temperature, humidity

            except RuntimeError as e:
                logging.error(f"DHT22 read error on pin {pin}, attempt {attempt}/{retries}: {e}")
                if attempt < retries:
                    time.sleep(retry_delay)
            except Exception as e:
                logging.error(f"Unexpected error reading DHT22 on pin {pin}, attempt {attempt}/{retries}: {e}")
                if attempt < retries:
                    time.sleep(retry_delay)

    except Exception as e:
        logging.error(f"Failed to initialize DHT22 on pin {pin}: {e}")
        return None, None
    finally:
        if dht_device:
            try:
                dht_device.exit()
            except Exception:
                pass

    return None, None

def check_anomalies(temperature, humidity, pin):
    """
    Checks for temperature and humidity anomalies and logs them.
    """
    if temperature is None or humidity is None:
        return

    if temperature > 35:
        logging.error(f"Temperature anomaly: {temperature:.1f}C on pin {pin}")
    if temperature < 5:
        logging.error(f"Temperature anomaly: {temperature:.1f}C on pin {pin}")
    if humidity > 90:
        logging.error(f"Humidity anomaly: {humidity:.1f}% on pin {pin}")

def main():
    """
    Main function to read DHT22 sensors and check for anomalies.
    """
    global running

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    logging.info("Wildlife Monitoring System started.")

    try:
        while running:
            # Read from sensor 1 (GPIO4)
            temp1, hum1 = read_dht22(4)
            if temp1 is not None and hum1 is not None:
                logging.info(f"Sensor 1 (GPIO4): Temp={temp1:.1f}C, Hum={hum1:.1f}%")
                check_anomalies(temp1, hum1, 4)
            else:
                logging.error("Failed to read sensor 1 (GPIO4) after retries.")

            # Read from sensor 2 (GPIO17)
            temp2, hum2 = read_dht22(17)
            if temp2 is not None and hum2 is not None:
                logging.info(f"Sensor 2 (GPIO17): Temp={temp2:.1f}C, Hum={hum2:.1f}%")
                check_anomalies(temp2, hum2, 17)
            else:
                logging.error("Failed to read sensor 2 (GPIO17) after retries.")

            # Wait 60 seconds before next reading
            for _ in range(60):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Wildlife Monitoring System stopped.")

if __name__ == "__main__":
    main()

