import subprocess
import time
import signal
import sys
import re
from gpiozero import PWMOutputDevice

FAN_PIN = 14
PWM_FREQ = 100
POLL_INTERVAL = 5

TEMP_THRESHOLDS = [70, 60, 50, 40, 32, 25]
TEMP_DUTIES = [100, 85, 70, 50, 25, 15]

fan = None
running = True

def get_cpu_temp():
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True, text=True, timeout=5, check=True
        )
        match = re.search(r'temp=(\d+\.\d+)', result.stdout)
        if not match:
            print(f"Error: could not parse vcgencmd output: {result.stdout.strip()}", file=sys.stderr)
            return None
        return float(match.group(1))
    except subprocess.CalledProcessError as e:
        print(f"Error: vcgencmd failed (exit {e.returncode}): {e.stderr.strip()}", file=sys.stderr)
    except subprocess.TimeoutExpired:
        print("Error: vcgencmd timed out", file=sys.stderr)
    except Exception as e:
        print(f"Error: unexpected failure reading temperature: {e}", file=sys.stderr)
    return None

def set_fan_speed(temp):
    for i, threshold in enumerate(TEMP_THRESHOLDS):
        if temp > threshold:
            duty = TEMP_DUTIES[i]
            break
    else:
        duty = 0
    try:
        fan.value = duty / 100.0
        print(f"CPU temp: {temp:.1f}°C -> fan duty: {duty}%")
    except Exception as e:
        print(f"Error: failed to set fan duty cycle: {e}", file=sys.stderr)

def cleanup(signum=None, frame=None):
    global running
    running = False
    if fan is not None:
        try:
            fan.value = 0
            fan.close()
        except Exception:
            pass
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting.")
        sys.exit(0)

def main():
    global fan
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as e:
        print(f"Error: failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    last_temp = None
    print("Fan control started. Press Ctrl+C to exit.")

    while running:
        temp = get_cpu_temp()
        if temp is not None:
            last_temp = temp
            set_fan_speed(temp)
        elif last_temp is not None:
            print(f"Keeping last known fan speed (CPU temp: {last_temp:.1f}°C).")
        else:
            print("No valid temperature reading available; setting fan to 100% as fail-safe.")
            try:
                fan.value = 1.0
            except Exception as e:
                print(f"Error: failed to set fail-safe duty cycle: {e}", file=sys.stderr)

        for _ in range(POLL_INTERVAL):
            if not running:
                break
            time.sleep(1)

if __name__ == "__main__":
    main()

