import signal
import sys
import time
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

FAN_PIN = 14
PWM_FREQUENCY = 100
CHECK_INTERVAL = 5

TEMP_THRESHOLDS = [70, 60, 50, 40, 32, 25]
FAN_SPEEDS = [100, 85, 70, 50, 25, 15]


class FanController:
    def __init__(self, fan_pin=FAN_PIN, pwm_frequency=PWM_FREQUENCY, temp_thresholds=TEMP_THRESHOLDS, fan_speeds=FAN_SPEEDS):
        if len(temp_thresholds) != len(fan_speeds):
            raise ValueError("Threshold and speed lists must have equal length.")
        self.fan_pin = fan_pin
        self.pwm_frequency = pwm_frequency
        self.temp_thresholds = temp_thresholds
        self.fan_speeds = fan_speeds
        self.fan = PWMOutputDevice(fan_pin, frequency=pwm_frequency, initial_value=0)
        self._running = True

    def get_cpu_temperature(self):
        try:
            with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
                return float(f.read().strip()) / 1000.0
        except (IOError, OSError, ValueError) as e:
            logging.error(f"Error reading CPU temperature: {e}")
            return None

    def calculate_fan_speed(self, temperature):
        for i, threshold in enumerate(self.temp_thresholds):
            if temperature > threshold:
                return self.fan_speeds[i]
        return 0

    def set_fan_speed(self, speed):
        try:
            self.fan.value = speed / 100.0
            logging.info(f"Fan speed set to {speed}%")
        except Exception as e:
            logging.error(f"Error setting fan speed: {e}")

    def run(self):
        logging.info("Fan controller started.")
        while self._running:
            temperature = self.get_cpu_temperature()
            if temperature is not None:
                fan_speed = self.calculate_fan_speed(temperature)
                logging.info(f"Temperature: {temperature:.1f}°C, Fan Speed: {fan_speed}%")
                self.set_fan_speed(fan_speed)
            time.sleep(CHECK_INTERVAL)

    def stop(self):
        self._running = False
        try:
            self.fan.value = 0
            self.fan.close()
            logging.info("Fan stopped and GPIO released.")
        except Exception as e:
            logging.error(f"Error stopping fan: {e}")


def main():
    controller = FanController()
    def signal_handler(signum, frame):
        logging.info(f"Signal {signum} received, shutting down.")
        controller.stop()
        sys.exit(0)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        controller.run()
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        controller.stop()


if __name__ == "__main__":
    main()

