import time
import signal
import sys
import logging
import requests
import board
import adafruit_dht

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
DHT_PIN = board.D4            # BCM GPIO4 (physical pin 7)
THINGSPEAK_CHANNEL_ID = 1234567
THINGSPEAK_WRITE_API_KEY = 'YOUR_API_KEY'
THINGSPEAK_UPDATE_URL = f'https://api.thingspeak.com/update?api_key={THINGSPEAK_WRITE_API_KEY}'

ERROR_LOG_FILE = 'error.log'
TEMP_LOG_FILE = 'temperature.txt'

READ_INTERVAL_SECONDS = 60
DHT_TIMEOUT_SECONDS = 2.0

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_sensor = None
_error_file = None
_temp_file = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _open_log(path):
    """Open a log file in append mode; return the file handle or None on failure."""
    try:
        return open(path, 'a', encoding='utf-8')
    except OSError as exc:
        print(f"[FATAL] Cannot open log file '{path}': {exc}", file=sys.stderr)
        return None


def _log_error(message):
    """Append a timestamped error message to error.log."""
    ts = time.strftime('%Y-%m-%d %H:%M:%S')
    line = f"{ts} - {message}\n"
    if _error_file and not _error_file.closed:
        try:
            _error_file.write(line)
            _error_file.flush()
        except OSError:
            pass
    else:
        print(line, end='')


def _read_temperature(sensor):
    """
    Attempt a DHT22 read with a timeout.
    Returns (temperature_c, error_message).
    """
    try:
        temperature = sensor.temperature
        if temperature is None:
            return None, 'Sensor returned None'
        return temperature, None
    except RuntimeError as exc:
        # adafruit_dht raises RuntimeError on checksum / timing glitches
        return None, str(exc)
    except Exception as exc:
        return None, str(exc)


def _write_to_thingspeak(temperature):
    """POST temperature to ThingSpeak; return True on success."""
    payload = {'field1': temperature}
    try:
        resp = requests.post(THINGSPEAK_UPDATE_URL, data=payload, timeout=10)
        if resp.status_code == 200:
            return True
        _log_error(f"ThingSpeak POST returned HTTP {resp.status_code}: {resp.text}")
        return False
    except requests.exceptions.RequestException as exc:
        _log_error(f"ThingSpeak request failed: {exc}")
        return False


def _write_to_log(temperature):
    """Append a timestamped temperature line to temperature.txt."""
    ts = time.strftime('%Y-%m-%d %H:%M:%S')
    line = f"{ts}, Temperature: {temperature:.2f} C\n"
    if _temp_file and not _temp_file.closed:
        try:
            _temp_file.write(line)
            _temp_file.flush()
        except OSError as exc:
            _log_error(f"Failed to write to log file: {exc}")
    else:
        _log_error(f"Log file closed; cannot write: {line.strip()}")


def _cleanup():
    """Release all resources."""
    global _sensor, _error_file, _temp_file
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None
    for f in (_error_file, _temp_file):
        if f is not None and not f.closed:
            try:
                f.close()
            except OSError:
                pass
    _error_file = None
    _temp_file = None


def main():
    global _sensor, _error_file, _temp_file

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _error_file = _open_log(ERROR_LOG_FILE)
    _temp_file = _open_log(TEMP_LOG_FILE)
    if _error_file is None or _temp_file is None:
        _cleanup()
        sys.exit(1)

    # Initialise DHT22 on GPIO4
    try:
        _sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        _log_error(f"Failed to initialise DHT22 on GPIO4: {exc}")
        _cleanup()
        sys.exit(1)

    print("DHT22 temperature logger started. Press Ctrl+C to stop.")

    while _running:
        temperature, err = _read_temperature(_sensor)

        if temperature is not None:
            _write_to_log(temperature)
            _write_to_thingspeak(temperature)
        else:
            _log_error(f"DHT22 read failed: {err}")

        # Sleep in small increments so signals are caught promptly
        slept = 0.0
        while _running and slept < READ_INTERVAL_SECONDS:
            time.sleep(0.5)
            slept += 0.5

    _cleanup()
    print("\nShutdown complete.")


if __name__ == '__main__':
    main()

