#!/usr/bin/env python3
"""
Raspberry Pi UPS Plus HAT monitor.

Reads power supply and battery INA219 sensors and UPS controller register data
from an INA219 sensor on I2C bus 1.
"""

import signal
import sys
import time

from ina219 import INA219, DeviceRangeError
from smbus2 import SMBus, i2c_msg

# --- Configuration -----------------------------------------------------------
DEVICE_BUS = 1
DEVICE_ADDR = 0x17

SUPPLY_INA219_ADDR = 0x40
BATT_INA219_ADDR = 0x45
SHUNT_RESISTANCE_SUPPLY = 0.00725   # ohms
SHUNT_RESISTANCE_BATT = 0.005       # ohms

# --- Globals for cleanup -----------------------------------------------------
_bus = None
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _close_bus():
    global _bus
    if _bus is not None:
        try:
            _bus.close()
        except Exception:
            pass
        _bus = None


class INA219Sensor:
    """Wrapper around ina219.INA219 with per-read error handling."""

    def __init__(self, shunt_resistance, bus_num, address):
        self.shunt_resistance = shunt_resistance
        self.bus_num = bus_num
        self.address = address
        self.ina = None
        self._init_sensor()

    def _init_sensor(self):
        try:
            self.ina = INA219(
                self.shunt_resistance,
                busnum=self.bus_num,
                address=self.address,
