import subprocess
import time
import signal
import sys
import logging

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    PWMOutputDevice = None
    GPIOZeroError = Exception

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

FAN_PIN = 14
PWM_FREQUENCY = 100
CHECK_INTERVAL = 5

TEMP_THRESHOLDS = [
    (70, 100),
    (60, 85),
    (50, 70),
    (40, 50),
    (32, 25),
    (25, 15),
]

fan = None
running = True


def get_cpu_temperature():
    """Retrieve CPU temperature in Celsius from vcgencmd."""
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True,
            text=True,
            check=True,
            timeout=5
        )
        temp_str = result.stdout.strip()
        return float(temp_str.split('=')[1].split("'")[0])
    except (subprocess.CalledProcessError, IndexError, ValueError, subprocess.TimeoutExpired) as e:
        logging.error(f"Error reading CPU temperature: {e}")
        return None


def get_fan_speed(temperature):
    """Determine fan duty cycle based on temperature thresholds."""
    for threshold, speed in TEMP_THRESHOLDS:
        if temperature > threshold:
            return speed
    return 0


def cleanup(signum=None, frame=None):
    """Release resources and exit cleanly."""
    global running, fan
    running = False
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
        fan = None
    if signum is not None:
        sys.exit(0)


def main():
    global fan

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    if PWMOutputDevice is not None:
        try:
            fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY, initial_value=0)
            logging.info(f"PWM fan control started on GPIO{FAN_PIN} at {PWM_FREQUENCY} Hz.")
        except GPIOZeroError as e:
            logging.warning(f"Failed to initialise PWMOutputDevice on GPIO{FAN_PIN}: {e}")
            logging.warning("Running in degraded mode (no hardware PWM).")
            fan = None
        except Exception as e:
            logging.warning(f"Unexpected error initialising PWMOutputDevice: {e}")
            logging.warning("Running in degraded mode (no hardware PWM).")
            fan = None
    else:
        logging.warning("gpiozero not available; running in degraded mode.")

    last_speed = 0

    while running:
        temperature = get_cpu_temperature()
        if temperature is None:
            logging.warning("Temperature read failed; keeping last fan speed.")
        else:
            speed = get_fan_speed(temperature)
            if speed != last_speed:
                last_speed = speed
                logging.info(f"Temperature: {temperature:.1f}°C -> Fan speed: {speed}%")
                if fan is not None:
                    try:
                        fan.value = speed / 100.0
                    except Exception as e:
                        logging.error(f"Failed to set fan duty cycle: {e}")
            else:
                logging.debug(f"Temperature: {temperature:.1f}°C -> Fan speed: {speed}% (unchanged)")
        time.sleep(CHECK_INTERVAL)

    cleanup()


if __name__ == "__main__":
    main()

