import signal
import sys
import time

from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# --- Configuration -----------------------------------------------------------
SENSOR_PINS = {1: 17, 2: 27, 3: 22}          # sensor_id -> BCM pin
POLL_INTERVAL_S = 1.0                        # seconds between polls

# --- Globals for signal handling --------------------------------------------
_running = True


def _handle_signal(signum, frame):
    """Flag the main loop to exit on SIGINT / SIGTERM."""
    global _running
    _running = False


def main():
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # --- Initialize sensors with pull-up resistors ---------------------------
    sensors = {}
    try:
        for sid, pin in SENSOR_PINS.items():
            sensors[sid] = DigitalInputDevice(pin, pull_up=True, bounce_time=None)
    except GPIOZeroError as exc:
        print(f"ERROR: Failed to initialize GPIO pins {list(SENSOR_PINS.values())}: {exc}",
              file=sys.stderr)
        # Clean up any sensors already opened
        for sid, dev in list(sensors.items()):
            try:
                dev.close()
            except Exception:
                pass
        sys.exit(1)
    except Exception as exc:
        print(f"ERROR: Unexpected GPIO initialization failure: {exc}", file=sys.stderr)
        sys.exit(1)

    print(f"Monitoring sensors on pins {list(SENSOR_PINS.values())} "
          f"(active-high, pull-up). Polling every {POLL_INTERVAL_S:.1f}s.")
    print("Press Ctrl+C to exit.\n")

    # --- Main polling loop ---------------------------------------------------
    try:
        while _running:
            for sid, dev in sensors.items():
                try:
                    if dev.is_active:          # HIGH == active
                        print(f"Response for sensor {sid}")
                except DeviceClosed:
                    print(f"ERROR: Sensor {sid} device closed unexpectedly.",
                          file=sys.stderr)
                    _running = False
                    break
                except GPIOZeroError as exc:
                    print(f"ERROR: GPIO read failure on sensor {sid}: {exc}",
                          file=sys.stderr)
                except Exception as exc:
                    print(f"ERROR: Unexpected read failure on sensor {sid}: {exc}",
                          file=sys.stderr)

            if not _running:
                break

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < POLL_INTERVAL_S:
                time.sleep(0.05)
                slept += 0.05

    finally:
        # --- Clean resource release on every exit path -----------------------
        for sid, dev in list(sensors.items()):
            try:
                dev.close()
            except Exception as exc:
                print(f"WARNING: Could not close sensor {sid}: {exc}",
                      file=sys.stderr)
        print("\nGPIO resources released. Exiting.")


if __name__ == "__main__":
    main()

