import sys
import time
import signal
import threading
import RPi.GPIO as GPIO

# Constants
RECEIVE_INTERVAL = 0.1  # seconds

# Global state
server_running = False
receive_thread = None
log_file_path = None
log_file = None

# Help messages
help_messages = {
    "help": "Shows help information. Usage: help [command]",
    "start": "Starts the server and creates a log file. Usage: start <filename>",
    "stop": "Stops the server. Usage: stop",
    "display": "Displays the contents of the log file. Usage: display",
    "send": "Sends data using DOG.send(). Usage: send <data>",
    "write": "Writes data directly to the log file. Usage: write <data>",
    "exit": "Exits the server. Usage: exit",
}

def help_command(args):
    """Displays help information for commands."""
    if len(args) == 1:
        print("Available commands:")
        for cmd in help_messages:
            print(f"  {cmd}")
        print("\nType 'help <command>' for more information.")
    elif len(args) == 2:
        command = args[1].lower()
        if command in help_messages:
            print(help_messages[command])
        else:
            print(f"No help found for '{command}'.")
    else:
        print("Invalid help command usage. Usage: help [command]")

def start_command(args):
    """Starts the server and creates a log file."""
    global server_running, receive_thread, log_file_path, log_file

    if server_running:
        print("Server is already running.")
        return

    if len(args) != 2:
        print("Invalid start command usage. Usage: start <filename>")
        return

    filename = args[1]
    log_file_path = filename

    try:
        log_file = open(log_file_path, "w")
        log_file.write("Server started.\n")
        log_file.flush()
    except IOError as e:
        print(f"Error creating log file: {e}")
        return

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        if log_file:
            log_file.close()
        return

    server_running = True
    print(f"Server started. Logging to: {log_file_path}")

    receive_thread = threading.Thread(target=receive_data, daemon=True)
    receive_thread.start()

def stop_command(args):
    """Stops the server."""
    global server_running, receive_thread, log_file

    if not server_running:
        print("Server is not running.")
        return

    server_running = False
    if receive_thread and receive_thread.is_alive():
        receive_thread.join(timeout=1.0)
        if receive_thread.is_alive():
            print("Warning: receive thread did not stop cleanly.")
    receive_thread = None

    if log_file:
        try:
            log_file.write("Server stopped.\n")
            log_file.flush()
            log_file.close()
        except IOError as e:
            print(f"Error closing log file: {e}")
        finally:
            log_file = None

    print("Server stopped.")

def display_command(args):
    """Displays the contents of the log file."""
    if not log_file_path:
        print("No log file is currently open.")
        return

    try:
        with open(log_file_path, "r") as f:
            print(f.read())
    except IOError as e:
        print(f"Error reading log file: {e}")

def send_command(args):
    """Sends data using DOG.send()."""
    if not server_running:
        print("Server must be started first. Use the 'start' command.")
        return

    if len(args) < 2:
        print("Invalid send command usage. Usage: send <data>")
        return

    data = " ".join(args[1:])
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")

def write_command(args):
    """Writes data directly to the log file."""
    if not log_file_path:
        print("No log file is currently open.")
        return

    if len(args) < 2:
        print("Invalid write command usage. Usage: write <data>")
        return

    data = " ".join(args[1:])
    try:
        with open(log_file_path, "a") as f:
            f.write(data + "\n")
            f.flush()
        print(f"Wrote to log: {data}")
    except IOError as e:
        print(f"Error writing to log file: {e}")

def exit_command(args):
    """Exits the server."""
    global server_running, receive_thread, log_file

    stop_command(args)
    GPIO.cleanup()
    print("GPIO cleaned up. Exiting.")
    sys.exit(0)

def receive_data():
    """Background thread: polls DOG.receive() every RECEIVE_INTERVAL seconds."""
    global server_running, log_file

    while server_running:
        try:
            data = DOG.receive()
            if data:
                if log_file:
                    try:
                        log_file.write(data + "\n")
                        log_file.flush()
                    except IOError as e:
                        print(f"Error writing to log file: {e}")
                else:
                    print(f"Received (no log file): {data}")
        except Exception as e:
            print(f"Error receiving data: {e}")
        time.sleep(RECEIVE_INTERVAL)

def process_command(command):
    """Parses and executes a command."""
    args = command.split()
    if not args:
        return

    command_name = args[0].lower()
    command_map = {
        "help": help_command,
        "start": start_command,
        "stop": stop_command,
        "display": display_command,
        "send": send_command,
        "write": write_command,
        "exit": exit_command,
    }

    if command_name in command_map:
        command_map[command_name](args)
    else:
        print(f"Unknown command: {command_name}. Type 'help' for available commands.")

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print(f"\nReceived signal {signum}. Shutting down...")
    exit_command([])

def main():
    """Main entry point."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("Starting DOG Server...")
    print("Type 'help' for available commands.")

    while True:
        try:
            command = input("> ").strip()
            process_command(command)
        except EOFError:
            print("\nEOF received. Exiting.")
            exit_command([])
        except Exception as e:
            print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

