import time
import requests
import sys

# Configuration
VOLTAGE_PIN = 17
ALERT_ENDPOINT = 'http://example.com/alert'
POLL_INTERVAL = 1  # seconds
REQUEST_TIMEOUT = 5  # seconds

def setup_gpio():
    """Initialize GPIO with BCM numbering and configure the voltage pin as input with pull-up."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(VOLTAGE_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

def check_power_status():
    """Read the voltage pin and return True if power is present (HIGH), False otherwise."""
    try:
        return GPIO.input(VOLTAGE_PIN) == GPIO.HIGH
    except Exception as e:
        print(f"Error reading GPIO pin {VOLTAGE_PIN}: {e}", file=sys.stderr)
        return False

def send_alert():
    """Send an HTTP POST request to the alert endpoint with a timeout."""
    try:
        response = requests.post(
            ALERT_ENDPOINT,
            json={'alert': 'Power failure detected'},
            timeout=REQUEST_TIMEOUT
        )
        response.raise_for_status()
        print(f"Alert sent successfully (HTTP {response.status_code}).")
    except requests.exceptions.Timeout:
        print(f"Alert request timed out after {REQUEST_TIMEOUT} seconds.", file=sys.stderr)
    except requests.exceptions.ConnectionError as e:
        print(f"Connection error sending alert: {e}", file=sys.stderr)
    except requests.exceptions.HTTPError as e:
        print(f"HTTP error sending alert: {e}", file=sys.stderr)
    except requests.exceptions.RequestException as e:
        print(f"Error sending alert: {e}", file=sys.stderr)

def cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup failed: {e}", file=sys.stderr)

def main():
    setup_gpio()
    try:
        while True:
            power_present = check_power_status()
            if power_present:
                print("Power is present.")
            else:
                print("Power failure detected!")
                send_alert()
            time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

