import asyncio
import json
import logging
import os
import signal
import sys
import time
from pathlib import Path

import psutil
import sounddevice as sd
import numpy as np

try:
    import tflite_runtime.interpreter as tflite
except ImportError:
    import tensorflow.lite as tflite

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    LED = None
    GPIOZeroError = Exception

CONFIG_FILE = "config.json"

class AudioProcessor:
    def __init__(self, config):
        self.config = config
        self.logger = logging.getLogger(__name__)
        self.audio_device_index = None
        self.interpreter = None
        self.input_details = None
        self.output_details = None
        self.alert_led = None
        self.running = True
        self._init_audio()
        self._init_tflite()
        self._init_gpio()

    def _init_audio(self):
        try:
            devices = sd.query_devices()
            input_devices = [d for d in devices if d['max_input_channels'] > 0]
            if not input_devices:
                raise RuntimeError("No input audio devices found.")
            self.audio_device_index = input_devices[0]['index']
            self.logger.info(f"Using audio device index: {self.audio_device_index}")
        except Exception as e:
            self.logger.error(f"Error initializing audio: {e}")
            raise

    def _init_tflite(self):
        try:
            model_path = self.config.get("tflite_model_path", "model.tflite")
            if not Path(model_path).exists():
                raise FileNotFoundError(f"Model file not found: {model_path}")
            self.interpreter = tflite.Interpreter(model_path=model_path)
            self.interpreter.allocate_tensors()
            self.input_details = self.interpreter.get_input_details()
            self.output_details = self.interpreter.get_output_details()
            self.logger.info("TFLite model loaded successfully.")
        except Exception as e:
            self.logger.error(f"Error initializing TFLite: {e}")
            raise

    def _init_gpio(self):
        if LED is None:
            self.logger.warning("gpiozero not available; LED alert disabled.")
            return
        try:
            gpio_pin = self.config.get("gpio_pin", 17)
            self.alert_led = LED(gpio_pin)
            self.logger.info(f"LED alert initialized on GPIO {gpio_pin}.")
        except GPIOZeroError as e:
            self.logger.error(f"Error initializing GPIO: {e}")
            self.alert_led = None
        except Exception as e:
            self.logger.error(f"Unexpected error initializing GPIO: {e}")
            self.alert_led = None

    def trigger_alert(self):
        if self.alert_led:
            try:
                self.alert_led.on()
                self.logger.warning("Alert triggered (LED ON).")
            except Exception as e:
                self.logger.error(f"Error triggering alert: {e}")
        else:
            self.logger.warning("Alert triggered (LED not available).")

    def cleanup(self):
        if self.alert_led:
            try:
                self.alert_led.off()
                self.alert_led.close()
            except Exception:
                pass
        self.running = False

    async def capture_audio(self):
        try:
            samplerate = self.config.get("audio_samplerate", 16000)
            chunk_size = self.config.get("audio_chunk_size", 16000)
            while self.running:
                try:
                    audio_data = sd.rec(chunk_size, dtype='float32', samplerate=samplerate, device=self.audio_device_index, channels=1)
                    sd.wait()
                    if audio_data is None or audio_data.size == 0:
                        self.logger.warning("Empty audio chunk received.")
                        continue
                    yield audio_data.flatten()
                except sd.PortAudioError as e:
                    self.logger.error(f"Audio device error: {e}")
                    await asyncio.sleep(1)
                except Exception as e:
                    self.logger.error(f"Unexpected error during audio capture: {e}")
                    await asyncio.sleep(1)
        except Exception as e:
            self.logger.error(f"Fatal error in audio capture task: {e}")

    async def process_audio(self, audio_stream):
        try:
            while self.running:
                try:
                    audio_data = await asyncio.wait_for(audio_stream.__anext__(), timeout=5.0)
                except StopAsyncIteration:
                    self.logger.info("Audio stream ended.")
                    break
                except asyncio.TimeoutError:
                    self.logger.warning("Timeout waiting for audio chunk.")
                    continue
                except Exception as e:
                    self.logger.error(f"Error reading audio chunk: {e}")
                    continue

                try:
                    input_data = np.expand_dims(audio_data, axis=0).astype(np.float32)
                    self.interpreter.set_tensor(self.input_details[0]['index'], input_data)
                    self.interpreter.invoke()
                    output_data = self.interpreter.get_tensor(self.output_details[0]['index'])
                    sentiment_score = float(output_data[0][0])
                    self.logger.debug(f"Sentiment score: {sentiment_score}")

                    positive_threshold = self.config.get("positive_threshold", 0.7)
                    negative_threshold = self.config.get("negative_threshold", 0.3)

                    if sentiment_score > positive_threshold:
                        self.logger.info("Positive sentiment detected!")
                        self.trigger_alert()
                    elif sentiment_score < negative_threshold:
                        self.logger.info("Negative sentiment detected!")
                        self.trigger_alert()
                except Exception as e:
                    self.logger.error(f"Error processing audio: {e}")
        except Exception as e:
            self.logger.error(f"Fatal error in audio processing task: {e}")

    async def monitor_system(self):
        while self.running:
            try:
                cpu_percent = psutil.cpu_percent(interval=None)
                memory_percent = psutil.virtual_memory().percent
                disk_percent = psutil.disk_usage("/").percent
                self.logger.info(f"CPU: {cpu_percent}%, Memory: {memory_percent}%, Disk: {disk_percent}%")
                await asyncio.sleep(self.config.get("system_monitor_interval", 60))
            except Exception as e:
                self.logger.error(f"Error monitoring system: {e}")
                await asyncio.sleep(10)

    async def send_heartbeat(self):
        while self.running:
            try:
                heartbeat_url = self.config.get("heartbeat_url", "http://localhost:8000/heartbeat")
                import aiohttp
                async with aiohttp.ClientSession() as session:
                    async with session.post(heartbeat_url, json={"status": "running"}) as resp:
                        self.logger.info(f"Heartbeat sent, status: {resp.status}")
            except Exception as e:
                self.logger.error(f"Error sending heartbeat: {e}")
            await asyncio.sleep(self.config.get("heartbeat_interval", 60))

    async def check_config_updates(self):
        while self.running:
            try:
                config_url = self.config.get("config_url", "http://localhost:8000/config")
                import aiohttp
                async with aiohttp.ClientSession() as session:
                    async with session.get(config_url) as resp:
                        if resp.status == 200:
                            new_config = await resp.json()
                            self.config.update(new_config)
                            self.logger.info("Configuration updated from cloud.")
                        else:
                            self.logger.warning(f"Failed to fetch config: {resp.status}")
            except Exception as e:
                self.logger.error(f"Error checking for config updates: {e}")
            await asyncio.sleep(self.config.get("config_check_interval", 300))

async def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        return config
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
        return None
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON format in configuration file: {config_file}")
        return None
    except Exception as e:
        logging.error(f"Error loading configuration: {e}")
        return None

async def main():
    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
    config = await load_config(CONFIG_FILE)
    if not config:
        sys.exit(1)

    processor = AudioProcessor(config)

    loop = asyncio.get_running_loop()
    stop_event = asyncio.Event()

    def signal_handler():
        logging.info("Shutdown signal received.")
        stop_event.set()

    for sig in (signal.SIGINT, signal.SIGTERM):
        try:
            loop.add_signal_handler(sig, signal_handler)
        except NotImplementedError:
            pass

    audio_stream = processor.capture_audio()
    tasks = [
        asyncio.create_task(processor.process_audio(audio_stream)),
        asyncio.create_task(processor.monitor_system()),
        asyncio.create_task(processor.send_heartbeat()),
        asyncio.create_task(processor.check_config_updates())
    ]

    try:
        await stop_event.wait()
    finally:
        processor.running = False
        for task in tasks:
            task.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)
        processor.cleanup()
        logging.info("Application shutdown complete.")

if __name__ == "__main__":
    asyncio.run(main())

