import time
import signal
import sys
import board
import busio
import adafruit_tsl2561
from gpiozero import PWMLED

# Constants
LED_PIN = 18
PWM_FREQUENCY = 1000
UPDATE_INTERVAL = 1.0
TSL2561_ADDRESS = 0x39

# Global state
led = None
sensor = None
running = True

def signal_handler(sig, frame):
    global running
    running = False

def initialize_hardware():
    global led, sensor
    try:
        led = PWMLED(LED_PIN, frequency=PWM_FREQUENCY)
        led.value = 0.0
    except Exception as e:
        print(f"Error initializing LED on GPIO {LED_PIN}: {e}")
        sys.exit(1)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_tsl2561.TSL2561(i2c, address=TSL2561_ADDRESS)
        sensor.enabled = True
        print(f"TSL2561 detected at I2C address 0x{TSL2561_ADDRESS:02X}")
    except ValueError as e:
        print(f"Error: TSL2561 not found at address 0x{TSL2561_ADDRESS:02X}. Check wiring. Details: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Error initializing TSL2561: {e}")
        sys.exit(1)

def read_light_intensity():
    try:
        lux = sensor.lux
        if lux is None:
            print("Warning: Sensor returned None for lux.")
            return None
        return lux
    except OSError as e:
        print(f"I2C bus error reading TSL2561: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading TSL2561: {e}")
        return None

def set_led_brightness(brightness_percent):
    try:
        brightness_percent = max(0.0, min(100.0, brightness_percent))
        led.value = brightness_percent / 100.0
    except Exception as e:
        print(f"Error setting LED brightness: {e}")

def cleanup():
    global led, sensor
    if led is not None:
        led.value = 0.0
        led.close()
    if sensor is not None:
        try:
            sensor.enabled = False
        except Exception:
            pass
    print("\nCleanup complete. Exiting.")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_hardware()
    brightness = 0.0

    try:
        while running:
            lux = read_light_intensity()
            if lux is not None:
                brightness = min(100.0, max(0.0, lux))
                set_led_brightness(brightness)
                print(f"Lux: {lux:.2f}, LED Brightness: {brightness:.2f}%")
            else:
                print(f"Keeping previous LED brightness: {brightness:.2f}%")
            time.sleep(UPDATE_INTERVAL)
    except Exception as e:
        print(f"Fatal error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

