import signal
import sys
import time
import logging
from gpiozero import OutputDevice, InputDevice

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21
START_SIGNAL = 0
END_SIGNAL = 1
TRANSMIT_DELAY = 0.0005
RECEPTION_TIMEOUT = 1

running = True

def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down...")
    running = False

def char_to_bits(char):
    try:
        binary = bin(ord(char))[2:].zfill(7)
        return [int(bit) for bit in binary]
    except Exception as e:
        logging.error(f"Error converting character to bits: {e}")
        return []

def bits_to_char(bits):
    try:
        binary_string = ''.join(map(str, bits))
        char = chr(int(binary_string, 2))
        return char
    except Exception as e:
        logging.error(f"Error converting bits to character: {e}")
        return ''

def transmit_data(data, data_out, timer_out):
    global running
    try:
        timer_out.on()
        for bit in char_to_bits(START_SIGNAL):
            if not running:
                return False
            timer_out.off()
            data_out.value = bit
            time.sleep(TRANSMIT_DELAY)
            timer_out.on()
            time.sleep(TRANSMIT_DELAY)
        timer_out.off()
        for char in data:
            if not running:
                return False
            for bit in char_to_bits(char):
                timer_out.off()
                data_out.value = bit
                time.sleep(TRANSMIT_DELAY)
                timer_out.on()
                time.sleep(TRANSMIT_DELAY)
        for bit in char_to_bits(END_SIGNAL):
            if not running:
                return False
            timer_out.off()
            data_out.value = bit
            time.sleep(TRANSMIT_DELAY)
            timer_out.on()
            time.sleep(TRANSMIT_DELAY)
        timer_out.off()
        return True
    except Exception as e:
        logging.error(f"Error during data transmission: {e}")
        return False

def receive_data(data_in, timer_in):
    global running
    try:
        start_time = time.time()
        received_bits = []
        while running:
            if time.time() - start_time > RECEPTION_TIMEOUT:
                logging.warning("Reception timeout reached.")
                return ""
            if timer_in.value == 1:
                received_bits.append(data_in.value)
                time.sleep(TRANSMIT_DELAY)
                if len(received_bits) % 7 == 0:
                    char = bits_to_char(received_bits[-7:])
                    if char == chr(END_SIGNAL):
                        return "".join(bits_to_char(received_bits[i:i+7]) for i in range(0, len(received_bits)-7, 7))
                    if char == chr(START_SIGNAL):
                        received_bits = []
    except Exception as e:
        logging.error(f"Error during data reception: {e}")
        return ""
    return ""

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    data_out = None
    timer_out = None
    data_in = None
    timer_in = None
    try:
        data_out = OutputDevice(DATA_OUT_PIN)
        timer_out = OutputDevice(TIMER_OUT_PIN)
        data_in = InputDevice(DATA_IN_PIN)
        timer_in = InputDevice(TIMER_IN_PIN)
        while running:
            user_input = input("Enter data to transmit (or 'q' to quit): ")
            if user_input.lower() == 'q':
                break
            if transmit_data(user_input, data_out, timer_out):
                received_data = receive_data(data_in, timer_in)
                if received_data:
                    logging.info(f"Received data: {received_data}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if data_out:
            data_out.close()
        if timer_out:
            timer_out.close()
        if data_in:
            data_in.close()
        if timer_in:
            timer_in.close()
        logging.info("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

