from gpiozero import Button, LED, DeviceClosed, BadPinFactory

DOOR_REED_PIN = 19
SIREN_PIN = 26
BOUNCE_TIME = 0.05
SAMPLE_INTERVAL = 0.4
NUM_SAMPLES = 8

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        reed = Button(DOOR_REED_PIN, pull_up=False, bounce_time=BOUNCE_TIME)
        siren = LED(SIREN_PIN)
    except (DeviceClosed, BadPinFactory) as exc:
        print(f"Error: failed to initialize GPIO devices: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: unexpected GPIO initialization failure: {exc}", file=sys.stderr)
        sys.exit(1)

    armed = True
    print("Classroom home-security demo started. System armed.")
    print("Monitoring door (GPIO19). Press Ctrl+C to stop.\n")

    try:
        for i in range(NUM_SAMPLES):
            if not _running:
                break

            try:
                door_open = reed.is_pressed  # True when pin reads HIGH (reed switch open)
            except Exception as exc:
                print(f"Error reading door state: {exc}", file=sys.stderr)
                break

            if armed and door_open:
                try:
                    siren.on()
                except Exception as exc:
                    print(f"Error turning on siren: {exc}", file=sys.stderr)
                    break
                print(f"Sample {i}: Door opened! Alarm triggered (siren ON).")
            else:
                try:
                    siren.off()
                except Exception:
                    pass

            time.sleep(SAMPLE_INTERVAL)
    finally:
        try:
            siren.off()
        except Exception:
            pass
        reed.close()
        siren.close()
        print("\nGPIO resources released. Demo finished.")


if __name__ == "__main__":
    main()

