    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

FAN_PIN = 12
PWM_FREQUENCY = 25000

fan = None


def cleanup(signum=None, frame=None):
    global fan
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
        fan = None
    if signum is not None:
        sys.exit(0)


def main():
    global fan

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        fan = PWMOutputDevice(
            pin=FAN_PIN,
            frequency=PWM_FREQUENCY,
            initial_value=0.0,
        )
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Warning: Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        print("Running in software-PWM mode (no hardware PWM available).", file=sys.stderr)
        fan = None
    except Exception as e:
        print(f"Warning: Unexpected error initializing GPIO{FAN_PIN}: {e}", file=sys.stderr)
        print("Running in software-PWM mode (no hardware PWM available).", file=sys.stderr)
        fan = None

