#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter.

Touchpads A (GPIO5), B (GPIO6), C (GPIO12) control three bits.
On each press the corresponding bit is toggled and the display,
discrete LEDs, APA102 strip, and piezo buzzer are updated.
"""

import signal
import sys
import time

import board
import busio
import digitalio

try:
    import adafruit_ht16k33.segments.segments as segments
except Exception:
    segments = None

try:
    from adafruit_circuitpython_apa102 import APA102
except Exception:
    APA102 = None

try:
    from gpiozero import Button, LED
except Exception:
    Button = None
    LED = None

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
TOUCH_PINS = [board.D5, board.D6, board.D12]
LED_PINS = [board.D7, board.D8]          # green, blue
BUZZER_PIN = board.D13

I2C_ADDR = 0x70

NUM_PIXELS = 7
DATA_PIN = board.D10
CLOCK_PIN = board.D11

MIDI_BASE = 60
TONE_DURATION = 0.5

# ---------------------------------------------------------------------------
# Globals (initialised in setup, checked before use)
# ---------------------------------------------------------------------------
touchpads = []
leds = []
buzzer = None
display = None
strip = None

bit_states = [False, False, False]
running = True


def setup():
    """Initialise all HAT peripherals; degrade gracefully on failure."""
    global touchpads, leds, buzzer, display, strip

    # --- Touchpads (gpiozero) ---
    if Button is not None:
        for pin in TOUCH_PINS:
            try:
                touchpads.append(Button(pin, pull_up=True))
            except Exception as exc:
                print(f"[WARN] Could not init touchpad on {pin}: {exc}",
                      file=sys.stderr)
                touchpads.append(None)
    else:
        print("[WARN] gpiozero unavailable; touchpads disabled.",
              file=sys.stderr)

    # --- Discrete LEDs (gpiozero) ---
    if LED is not None:
        for pin in LED_PINS:
            try:
                leds.append(LED(pin))
            except Exception as exc:
                print(f"[WARN] Could not init LED on {pin}: {exc}",
                      file=sys.stderr)
                leds.append(None)
    else:
        print("[WARN] gpiozero unavailable; LEDs disabled.",
              file=sys.stderr)

    # --- Piezo buzzer (gpiozero) ---
    if buzzer is None and LED is not None:
        try:
            buzzer = LED(BUZZER_PIN)
        except Exception as exc:
            print(f"[WARN] Could not init buzzer on {BUZZER_PIN}: {exc}",
                  file=sys.stderr)

    # --- Display (HT16K33) ---
    if segments is not None:
        try:
            i2c = busio.I2C(board.SCL, board.SDA)
            display = segments.Seg14x4(i2c, address=I2C_ADDR)
            display.fill(0)
        except Exception as exc:
            print(f"[WARN] Could not init display at 0x{I2C_ADDR:02X}: {exc}",
                  file=sys.stderr)
            display = None
    else:
        print("[WARN] adafruit-circuitpython-ht16k33 unavailable; "
              "display disabled.", file=sys.stderr)

    # --- APA102 strip ---
    if APA102 is not None:
        try:
            strip = APA102(DATA_PIN, NUM_PIXELS, clock_pin=CLOCK_PIN)
            strip.fill(0)
        except Exception as exc:
            print(f"[WARN] Could not init APA102 strip: {exc}",
                  file=sys.stderr)
            strip = None
    else:
        print("[WARN] adafruit-circuitpython-apa102 unavailable; "
              "strip disabled.", file=sys.stderr)


def update_leds():
    """Drive the three onboard discrete LEDs from bit_states."""
    if not leds:
        return
    for i, led in enumerate(leds):
        if led is not None:
            try:
                led.value = 1 if bit_states[i] else 0
            except Exception as exc:
                print(f"[WARN] Failed to set LED {i}: {exc}", file=sys.stderr)


def update_display(value):
    """Show decimal value (0-7) on the HT16K33 alphanumeric display."""
    if display is None:
        return
    try:
        display.fill(0)
        display.print_hex(value)
    except Exception as exc:
        print(f"[WARN] Display update failed: {exc}", file=sys.stderr)


def update_strip(value):
    """Update the APA102 strip from bit_states and the current value."""
    if strip is None:
        return
    try:
        strip.fill(0)
        if value == 0:
            strip.set_pixel(0, 0xFFFFFF)
        elif value == 7:
            strip.fill(0xFFFFFF)
        else:
            r = 0xFF if bit_states[0] else 0
            g = 0xFF if bit_states[1] else 0
            b = 0xFF if bit_states[2] else 0
            strip.set_pixel(value, (r, g, b))
        strip.show()
    except Exception as exc:
        print(f"[WARN] Strip update failed: {exc}", file=sys.stderr)


def play_tone(value):
    """Play a 0.5-second tone at MIDI note (MIDI_BASE + value)."""
    if buzzer is None:
        return
    try:
        buzzer.on()
        time.sleep(TONE_DURATION)
        buzzer.off()
    except Exception as exc:
        print(f"[WARN] Buzzer play failed: {exc}", file=sys.stderr)


def handle_touch(channel):
    """Toggle the bit for the touched channel and refresh all outputs."""
    global bit_states
    if not (0 <= channel < len(bit_states)):
        return
    bit_states[channel] = not bit_states[channel]
    update_leds()
    value = (4 if bit_states[0] else 0) | \
            (2 if bit_states[1] else 0) | \
            (1 if bit_states[2] else 0)
    update_display(value)
    update_strip(value)
    play_tone(value)


def cleanup():
    """Turn off all outputs and release resources."""
    global running
    running = False
    for led in leds:
        if led is not None:
            try:
                led.off()
            except Exception:
                pass
    if display is not None:
        try:
            display.fill(0)
        except Exception:
            pass
    if strip is not None:
        try:
            strip.fill(0)
            strip.show()
        except Exception:
            pass
    if buzzer is not None:
        try:
            buzzer.off()
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM."""
    global running
    running = False


def main():
    setup()

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Attach touch callbacks
    for i, pad in enumerate(touchpads):
        if pad is not None:
            try:
                pad.when_pressed = lambda ch=i: handle_touch(ch)
            except Exception as exc:
                print(f"[WARN] Could not attach callback for touchpad {i}: {exc}",
                      file=sys.stderr)

    # Initialise outputs
    update_leds()
    update_display(0)
    update_strip(0)

    print("Rainbow HAT binary counter ready. Press touchpads A/B/C (Ctrl-C to exit).")

    # Main loop — wait for signals
    try:
        signal.pause()
    except (KeyboardInterrupt, SystemExit):
        pass
    finally:
        cleanup()


if __name__ == "__main__":
    main()

