#!/usr/bin/env python3
"""
notification_light.py

Monitors remote CPU, memory, and disk I/O usage and displays it on three
common-anode RGB LEDs (Kingbright WP710A10 series) on a Raspberry Pi 4.

LED1 (CPU)    R: GPIO17, G: GPIO18, B: GPIO27
LED2 (memory) R: GPIO22, G: GPIO23, B: GPIO24
LED3 (disk I/O) R: GPIO5, G: GPIO6, B: GPIO13

Each channel is driven with hardware PWM at 1000 Hz.  Common anodes are
connected to 3.3 V through a 220 ohm series resistor.

The program receives JSON messages from a remote server and updates the
LED colors via a background thread.  It reconnects with exponential backoff
on connection loss.  On SIGINT/SIGTERM it stops PWM, releases GPIO, closes the
socket, and exits cleanly.
"""

import json
import logging
import math
import signal
import socket
import sys
import threading
import time

import RPi.GPIO as GPIO

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
SERVER_ADDRESS = "192.168.1.100"
SERVER_PORT = 5000

LED_PINS = {
    "cpu":    {"red": 17, "green": 18, "blue": 27},
    "memory": {"red": 22, "green": 23, "blue": 24},
    "disk":   {"red": 5,  "green": 6,  "blue": 13},
}

PWM_FREQUENCY = 1000  # Hz

LOG_FILE = "notification_light.log"

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
log = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
_pwm_by_pin = {}
_lock = threading.Lock()
_shutdown = threading.Event()
_socket = None


def _validate_usage(value: float, component: str) -> float:
    """Clamp *value* to [0, 100] and log a warning if out of range."""
    clamped = max(0.0, min(100.0, float(value)))
    if clamped != value:
        log.warning("%s usage %.2f out of range; clamped to %.2f", component, value, clamped)
    return clamped


def _calculate_color(usage_percent: float) -> tuple[int, int, int]:
    """
    Non-linear mapping:
      - Red   > 66%
      - Green 33%–66%
      - Blue  < 33%
    Returns (red_duty, green_duty, blue_duty) in [0, 100].
    """
    if usage_percent > 66.0:
        red = 100.0
        green = 100.0 * (1.0 - math.sin((usage_percent - 66.0) / 33.0 * (math.pi / 2.0)))
        blue = 0.0
    elif usage_percent > 33.0:
        red = 100.0 * (1.0 - math.sin((usage_percent - 33.0) / 33.0 * (math.pi / 2.0)))
        green = 100.0
        blue = 0.0
    else:
        red = 0.0
        green = 0.0
        blue = 100.0 * usage_percent / 33.0
    return int(red), int(green), int(blue)


def _update_led(component: str, usage_percent: float) -> None:
    """Set the PWM duty cycles for a single LED from *usage_percent*."""
    pins = LED_PINS[component]
    red_duty, green_duty, blue_duty = _calculate_color(_validate_usage(usage_percent, component))
    with _lock:
        for color, pin in (("red", pins["red"]), ("green", pins["green"]), ("blue", pins["blue"])):
            pwm = _pwm_by_pin.get(pin)
            if pwm is not None:
                try:
                    pwm.ChangeDutyCycle({"red": red_duty, "green": green_duty, "blue": blue_duty}[color])
