def _process_message(message: str) -> None:
    """Parse and distribute a JSON message."""
    try:
        data = json.loads(message)
    except (json.JSONDecodeError, TypeError) as exc:
        log.error("Invalid JSON received: %s", exc)
        return

    cpu_usage = data.get("cpu_usage")
    memory_usage = data.get("memory_usage")
    disk_io = data.get("disk_io")

    if cpu_usage is not None:
        _update_led("cpu", cpu_usage)
    if memory_usage is not None:
        _update_led("memory", memory_usage)
    if disk_io is not None:
        _update_led("disk", disk_io)


def _reconnect_loop() -> None:
    """Background thread: connect to the server and read JSON messages."""
    global _socket
    while not _shutdown.is_set():
        try:
            _socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            _socket.settimeout(10)
            _socket.connect((SERVER_ADDRESS, SERVER_PORT))
            log.info("Connected to %s:%d", SERVER_ADDRESS, SERVER_PORT)

            while not _shutdown.is_set():
                try:
                    data = _socket.recv(1024)
                except socket.timeout:
                    continue
                except OSError as exc:
                    log.error("Socket read error: %s", exc)
                    break

                if not data:
                    log.warning("Server closed the connection.")
                    break

                try:
                    message = data.decode("utf-8").strip()
                except UnicodeDecodeError as exc:
                    log.error("Failed to decode message: %s", exc)
                    continue

                if message:
                    log.debug("Received: %s", message)
                    _process_message(message)

        except ConnectionRefusedError:
            log.error("Connection refused by %s:%d", SERVER_ADDRESS, SERVER_PORT)
        except OSError as exc:
            log.error("Connection error: %s", exc)

        if not _shutdown.is_set():
            delay = 1
            while not _shutdown.is_set() and delay <= 60:
                if _shutdown.wait(delay):
                    break
                delay = min(delay * 2, 60)

    if _socket is not None:
        try:
            _socket.close()
        except OSError:
            pass
        _socket = None
    log.info("Reconnect loop exiting.")


def _signal_handler(signum, _frame) -> None:
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    log.info("Received signal %d, shutting down...", signum)
    _shutdown.set()


def _cleanup() -> None:
    """Release all hardware resources."""
    global _socket
    _shutdown.set()

    if _socket is not None:
        try:
            _socket.close()
        except OSError:
            pass
        _socket = None

    with _lock:
        for pin, pwm in list(_pwm_by_pin.items()):
            try:
                pwm.stop()
            except Exception:
                pass
        for pin in LED_PINS.values():
            for p in (pin["red"], pin["green"], pin["blue"]):
                try:
                    GPIO.cleanup(p)
                except Exception:
                    pass

    log.info("GPIO cleaned up.")


def main() -> int:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)

        for pins in LED_PINS.values():
            for pin in (pins["red"], pins["green"], pins["blue"]):
                GPIO.setup(pin, GPIO.OUT)
                GPIO.output(pin, GPIO.LOW)

        for pins in LED_PINS.values():
            for pin in (pins["red"], pins["green"], pins["blue"]):
                pwm = GPIO.PWM(pin, PWM_FREQUENCY)
                pwm.start(0)
                _pwm_by_pin[pin] = pwm

        reconnect_thread = threading.Thread(target=_reconnect_loop, daemon=True)
        reconnect_thread.start()

        while not _shutdown.is_set():
            time.sleep(0.5)

    except Exception as exc:
        log.exception("Fatal error: %s", exc)
        return 1
    finally:
        _cleanup()
    return 0


if __name__ == "__main__":
    sys.exit(main())

