import RPi.GPIO as GPIO
import time
import sys

# GPIO pins for the RGB LED (BCM numbering)
RED_PIN = 17
GREEN_PIN = 27
BLUE_PIN = 22

# PWM frequency in Hz
PWM_FREQ = 200

# Preset colors: (red, green, blue) each 0-255
COLOR_NAMES = {
    "red": (255, 0, 0),
    "green": (0, 255, 0),
    "blue": (0, 0, 255),
    "yellow": (255, 255, 0),
    "cyan": (0, 255, 255),
}

# Global list of PWM objects for cleanup
pwm_channels = []


def setup_gpio():
    """Initialize GPIO mode and create PWM channels for the RGB LED."""
    try:
        GPIO.setmode(GPIO.BCM)
    except Exception as e:
        print(f"Error setting GPIO mode: {e}", file=sys.stderr)
        sys.exit(1)

    for color_pin in (RED_PIN, GREEN_PIN, BLUE_PIN):
        try:
            GPIO.setup(color_pin, GPIO.OUT)
            pwm = GPIO.PWM(color_pin, PWM_FREQ)
            pwm.start(0)
            pwm_channels.append(pwm)
        except Exception as e:
            print(f"Error setting up GPIO pin {color_pin}: {e}", file=sys.stderr)
            cleanup()
            sys.exit(1)


def set_color(red_val, green_val, blue_val):
    """Set the RGB LED color by updating the duty cycles of the PWM channels."""
    try:
        pwm_channels[0].ChangeDutyCycle(red_val)
        pwm_channels[1].ChangeDutyCycle(green_val)
        pwm_channels[2].ChangeDutyCycle(blue_val)
    except Exception as e:
        print(f"Error setting color: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)


def cleanup():
    """Stop all PWM channels and release GPIO resources."""
    for pwm in pwm_channels:
        try:
            pwm.stop()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    print("GPIO cleanup completed.")


def main():
    setup_gpio()
    print("RGB LED fading demo started. Press Ctrl+C to stop.")
    try:
        for color_name, color_values in COLOR_NAMES.items():
            print(f"Showing color: {color_name}")
            set_color(*color_values)
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nDemo interrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

