import requests
import time
from gpiozero import Button
from gpiozero.exc import GPIOZeroError

# Quality control inspection button wired to a Raspberry Pi GPIO pin
# Active-low logic: pressed = fail, not pressed = pass
INSPECTION_BUTTON_PIN = 17
SERVER_ENDPOINT = "http://localhost:8000/quality"


def submit_inspection_report(part_id, defect_count):
    """Submit a JSON inspection report to the quality control server."""
    report = {
        "part_id": part_id,
        "passed": defect_count == 0,
        "defect_count": defect_count,
    }
    try:
        response = requests.post(
            SERVER_ENDPOINT,
            json=report,
            timeout=5,
        )
        print(f"Server status: {response.status_code}")
    except requests.exceptions.Timeout:
        print("Error: server request timed out")
    except requests.exceptions.ConnectionError as e:
        print(f"Error: could not connect to server: {e}")
    except requests.exceptions.RequestException as e:
        print(f"Error: request failed: {e}")


def main():
    """Continuously read the inspection button and submit reports."""
    try:
        button = Button(INSPECTION_BUTTON_PIN, pull_up=True, bounce_time=0.05)
    except GPIOZeroError as e:
        print(f"Error: could not initialize GPIO pin {INSPECTION_BUTTON_PIN}: {e}")
        return

    previous_state = button.is_pressed
    part_id = "PART-204"

    try:
        while True:
            current_state = button.is_pressed
            if current_state != previous_state:
                defect_count = 1 if current_state else 0
                submit_inspection_report(part_id, defect_count)
                previous_state = current_state
            time.sleep(2)
    except KeyboardInterrupt:
        print("\nProgram stopped by user")
    finally:
        button.close()
        print("GPIO resources released")


if __name__ == "__main__":
    main()

