import atexit
import sys
import time
import logging
from adafruit_pca9685 import PCA9685
from board import SCL, SDA
import busio

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class Fuchikoma:
    """
    Controls a robot arm using a PCA9685 PWM servo driver.
    """

    def __init__(self, i2c_address=0x40, pwm_frequency=60, min_pulse=150, max_pulse=600):
        self.min_pulse = min_pulse
        self.max_pulse = max_pulse
        self.pwm_frequency = pwm_frequency
        self.servo_angles = {}
        self.servo_config = {
            "claw": {"channel": 0, "range": (-77, 77)},
            "lock": {"channel": 1, "range": (-77, 77)},
            "water_gun": {"channel": 2, "range": (-77, 77)},
        }

        try:
            self.i2c = busio.I2C(SCL, SDA)
            self.pwm = PCA9685(self.i2c, address=i2c_address)
            self.pwm.frequency = pwm_frequency
            logging.info(f"PCA9685 initialized at I2C address 0x{i2c_address:02X}, frequency {pwm_frequency} Hz")
        except (ValueError, OSError) as e:
            logging.error(f"Failed to initialize PCA9685 at 0x{i2c_address:02X}: {e}")
            sys.exit(1)

        atexit.register(self.cleanup)

    def cleanup(self):
        """Deinitialize all PCA9685 channels and release the I2C bus."""
        try:
            if hasattr(self, 'pwm') and self.pwm is not None:
                for channel in range(16):
                    try:
                        self.pwm.channels[channel].duty_cycle = 0
                    except Exception:
                        pass
                logging.info("All PCA9685 channels deinitialized.")
        except Exception as e:
