import RPi.GPIO as GPIO
import time
import signal
import sys

SERVO_PIN = 18
PWM_FREQ = 50
MIN_ANGLE = 0
MAX_ANGLE = 180
MIN_HR = 40
MAX_HR = 180
DUTY_MIN = 2.5
DUTY_MAX = 12.5

_pwm = None
_running = True


def angle_to_duty(angle):
    if angle < MIN_ANGLE:
        angle = MIN_ANGLE
    elif angle > MAX_ANGLE:
        angle = MAX_ANGLE
    return DUTY_MIN + (angle - MIN_ANGLE) * (DUTY_MAX - DUTY_MIN) / (MAX_ANGLE - MIN_ANGLE)


def cleanup(signum=None, frame=None):
    global _pwm, _running
    _running = False
    if _pwm is not None:
        try:
            _pwm.stop()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)


def main():
    global _pwm
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(SERVO_PIN, GPIO.OUT)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        cleanup()
        sys.exit(1)

    try:
        _pwm = GPIO.PWM(SERVO_PIN, PWM_FREQ)
        _pwm.start(0)
    except Exception as e:
        print(f"PWM initialization failed: {e}")
        cleanup()
        sys.exit(1)

    simulated_readings = [62, 75, 88, 110, 95]
    try:
        for heart_rate in simulated_readings:
            if not _running:
                break
            angle = (heart_rate - MIN_HR) * (MAX_ANGLE - MIN_ANGLE) / (MAX_HR - MIN_HR)
            duty = angle_to_duty(angle)
            _pwm.ChangeDutyCycle(duty)
            print(f"Heart Rate: {heart_rate} bpm, Angle: {angle:.1f} degrees")
            time.sleep(0.8)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

