import socket
import json
import time
import logging
import signal
import sys
import threading

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
SERVER_ADDRESS = '127.0.0.1'
SERVER_PORT = 9099
GPS_READ_INTERVAL = 1.0  # seconds

# Global state
tracking_state = "stopped"
gps_position = {"lat": 0.0, "lon": 0.0}
state_lock = threading.Lock()
shutdown_event = threading.Event()

# GPS module initialization
gps_module = None


def initialize_gps():
    """Initialize the GPS module. Returns True on success, False on failure."""
    global gps_module
    try:
        import serial
        # Attempt to open serial port for Adafruit Ultimate GPS (UART)
        gps_module = serial.Serial('/dev/serial0', baudrate=9600, timeout=1)
        logging.info("GPS module initialized via UART")
        return True
    except serial.SerialException as e:
        logging.warning(f"Serial GPS init failed: {e}. Falling back to simulated.")
        gps_module = None
        return False
    except Exception as e:
        logging.warning(f"GPS init error: {e}. Falling back to simulated.")
        gps_module = None
        return False


def read_gps_position():
    """Read GPS coordinates from the module or simulate them.
    Returns a dict with lat and lon, or None on failure."""
    global gps_module
    if gps_module is not None:
        try:
            # Simplified NMEA parsing: read a line and extract lat/lon
            line = gps_module.readline().decode('utf-8', errors='ignore').strip()
            if not line.startswith('$GPRMC'):
                return None
            parts = line.split(',')
            if len(parts) < 4:
                return None
            lat = parts[3]
            lon = parts[5]
            # Convert to float (simplified parsing, real code would parse N/S/E/W)
            lat_deg = float(lat[:2])
            lat_min = float(lat[2:])
            lon_deg = float(lon[:3])
            lon_min = float(lon[3:])
            return {"lat": lat_deg + lat_min / 60.0, "lon": lon_deg + lon_min / 60.0}
        except Exception as e:
            logging.error(f"GPS read error: {e}")
            return None
    else:
        # Simulated coordinates
        return {"lat": 37.7749, "lon": -122.4194}


def handle_command(command):
    """Process a remote control command and update tracking state.
    Returns a JSON response string."""
    global tracking_state, gps_position
    with state_lock:
        if command == "start":
            tracking_state = "running"
            logging.info("Tracking started")
            return json.dumps({"status": "started"})
        elif command == "stop":
            tracking_state = "stopped"
            logging.info("Tracking stopped")
            return json.dumps({"status": "stopped"})
        elif command == "report":
            if tracking_state == "running":
                new_pos = read_gps_position()
                if new_pos is not None:
                    gps_position = new_pos
                return json.dumps({"status": "reported", "lat": gps_position["lat"], "lon": gps_position["lon"]})
            else:
                return json.dumps({"status": "error", "message": "Tracking not started"})
        else:
            return json.dumps({"status": "error", "message": "Invalid command"})


def handle_client(connection, address):
    """Handle a single client connection."""
    try:
        data = connection.recv(1024).decode('utf-8', errors='ignore').strip()
        if not data:
            return
        logging.info(f"Received command from {address}: {data}")
        response = handle_command(data)
        connection.sendall(response.encode('utf-8'))
    except Exception as e:
        logging.error(f"Error handling client {address}: {e}")
    finally:
        connection.close()


def signal_handler(signum, frame):
    """Handle shutdown signals gracefully."""
    logging.info(f"Received signal {signum}, shutting down...")
    shutdown_event.set()


def main():
    """Main entry point: set up server, GPS, and accept connections."""
    global gps_module

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize GPS
    gps_available = initialize_gps()
    if not gps_available:
        logging.warning("No GPS module available, using simulated coordinates.")

    # Create TCP socket
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        server_socket.bind((SERVER_ADDRESS, SERVER_PORT))
        server_socket.listen(5)
        server_socket.settimeout(2.0)  # Allow periodic check for shutdown
        logging.info(f"Listening on {SERVER_ADDRESS}:{SERVER_PORT}")
    except socket.error as e:
        logging.error(f"Failed to bind/listen on {SERVER_ADDRESS}:{SERVER_PORT}: {e}")
        if gps_module:
            gps_module.close()
        sys.exit(1)

    try:
        while not shutdown_event.is_set():
            try:
                connection, address = server_socket.accept()
                logging.info(f"Accepted connection from {address}")
                client_thread = threading.Thread(target=handle_client, args=(connection, address))
                client_thread.daemon = True
                client_thread.start()
            except socket.timeout:
                continue
            except Exception as e:
                if not shutdown_event.is_set():
                    logging.error(f"Accept error: {e}")
    finally:
        logging.info("Shutting down...")
        server_socket.close()
        if gps_module:
            gps_module.close()
        logging.info("Server stopped")


if __name__ == "__main__":
    main()

