    led2 = None


def signal_handler(sig, frame):
    """Handle Ctrl+C for graceful shutdown."""
    print("\nCtrl+C detected. Cleaning up GPIO...")
    cleanup()
    sys.exit(0)


def initialize_gpio():
    """Initialize the two LED pins as outputs using gpiozero."""
    global led1, led2
    try:
        led1 = LED(LED_PIN_1)
        led2 = LED(LED_PIN_2)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during GPIO initialization: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)


def turn_on_leds():
    """Turn both LEDs on."""
    try:
        led1.on()
        led2.on()
    except Exception as e:
        print(f"Error turning on LEDs: {e}", file=sys.stderr)
        raise


def turn_off_leds():
    """Turn both LEDs off."""
    try:
        led1.off()
        led2.off()
    except Exception as e:
        print(f"Error turning off LEDs: {e}", file=sys.stderr)
        raise


def toggle_leds(cycles):
    """Recursively toggle both LEDs on for 1 second and off for 1 second."""
    if cycles <= 0:
        return
    try:
        turn_on_leds()
        time.sleep(1)
        turn_off_leds()
        time.sleep(1)
    except Exception:
        cleanup()
        sys.exit(1)
    toggle_leds(cycles - 1)


