import random
import time
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

# Configuration
LED_PIN = 17
LIGHT_THRESHOLD = 50
NUM_CYCLES = 5
DELAY_SECONDS = 2


def simulate_light_level() -> int:
    """Simulate a light level as a random integer between 0 and 100 inclusive."""
    return random.randint(0, 100)


def control_led(led: LED, light_level: int) -> None:
    """Control the LED based on the simulated light level."""
    if light_level < LIGHT_THRESHOLD:
        led.on()
        print("LED ON: Light level too low!")
    else:
        led.off()
        print("LED OFF: Light level adequate.")


def main() -> None:
    """Main function to simulate light sensor and control LED."""
    try:
        # gpiozero uses BCM numbering by default; no need to specify board.BCM
        with LED(LED_PIN) as led:
            for cycle in range(1, NUM_CYCLES + 1):
                light_level = simulate_light_level()
                print(f"Cycle {cycle}/{NUM_CYCLES}: Light Level = {light_level}%")
                control_led(led, light_level)
                if cycle < NUM_CYCLES:
                    time.sleep(DELAY_SECONDS)

    except KeyboardInterrupt:
        print("\nScript interrupted by user. Cleaning up...")
    except GPIOZeroError as e:
        print(f"GPIO error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        # Ensure LED is off and GPIO resources are released
        try:
            led.off()
            led.close()
        except NameError:
            pass  # led was never created due to early exit
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

