import time
import datetime
import sys

# Configuration
PIR_PIN = 4
DEBOUNCE_SECONDS = 60
POLL_INTERVAL = 1  # seconds

def setup_gpio():
    """Initialize GPIO mode and set PIR pin as input with internal pull-down."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup warning: {e}")

def is_feeding_time(now):
    """Return True if current time is between 7:00-8:00 AM or 6:00-7:00 PM."""
    hour = now.hour
    return (7 <= hour < 8) or (18 <= hour < 19)

def main():
    setup_gpio()
    last_feeding_time = None
    try:
        while True:
            try:
                motion_detected = GPIO.input(PIR_PIN)
            except Exception as e:
                print(f"GPIO read error: {e}")
                time.sleep(POLL_INTERVAL)
                continue

            if motion_detected:
                now = datetime.datetime.now()
                timestamp = now.strftime("%Y-%m-%d %H:%M:%S")
                print(f"Motion detected at {timestamp}")

                if is_feeding_time(now):
                    if last_feeding_time is None or (now - last_feeding_time).total_seconds() > DEBOUNCE_SECONDS:
                        print(f"Feeding initiated at {timestamp}")
                        last_feeding_time = now
                        # Cooldown: ignore motion for DEBOUNCE_SECONDS
                        time.sleep(DEBOUNCE_SECONDS)
                    else:
                        print("Not feeding time or recently fed.")
                else:
                    print("Not feeding time or recently fed.")

            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

