import serial
import time
import signal
import sys
from gpiozero import PWMOutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERVO_PIN = 17

serial_connection = None
servo = None

def cleanup(signum=None, frame=None):
    global serial_connection, servo
    if servo is not None:
        servo.close()
        servo = None
    if serial_connection is not None and serial_connection.is_open:
        serial_connection.close()
        serial_connection = None
    if signum is not None:
        sys.exit(0)

def move_servo(angle):
    if not (0 <= angle <= 180):
        print("Error: Angle must be between 0 and 180 degrees.")
        return
    duty_cycle = angle / 18.0 + 2.0
    servo.value = duty_cycle / 100.0
    time.sleep(1)
    servo.value = 0

def main():
    global serial_connection, servo
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)
    try:
        servo = PWMOutputDevice(SERVO_PIN, frequency=50, initial_value=0)
    except Exception as e:
        print(f"Error initializing servo on GPIO {SERVO_PIN}: {e}")
        serial_connection.close()
        sys.exit(1)
    try:
        while True:
            try:
                data = serial_connection.readline().decode('ascii', errors='replace').strip()
                if data:
                    try:
                        angle = int(data)
                        move_servo(angle)
                    except ValueError:
                        print(f"Invalid data received: {data}")
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                time.sleep(1)
    finally:
        cleanup()

if __name__ == '__main__':
    main()

