import signal
import sys
import time
import logging

try:
    import serial
    from pymodbus.client import ModbusSerialClient
    from pymodbus.exceptions import ModbusIOException, ModbusException
    from pymodbus.payload import BinaryPayloadDecoder
    from pymodbus.constants import Endian
except ImportError as e:
    logging.error(f"Missing required library: {e}. Install with: pip install pymodbus pyserial")
    raise

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class Servo:
    """
    Modbus RTU servo motor controller for Raspberry Pi.

    Provides read/write access to servo parameters via Modbus function codes
    FC 3 (read holding registers) and FC 6/16 (write holding registers).
    """

    # ------------------------------------------------------------------
    # Register map
    # ------------------------------------------------------------------
    # Read-only registers (FC 3)
    STATUS = {
        'R/W': 'R',
        'Register': 0x3000,
        'functioncode': 3,
        'read_length': 2,
    }
    VelocityFeedback = {
        'R/W': 'R',
        'Register': 0x3B00,
        'functioncode': 3,
        'read_length': 2,
    }
    PositionFeedback = {
        'R/W': 'R',
        'Register': 0x3700,
        'functioncode': 3,
        'read_length': 2,
    }

    # Write-only registers (FC 6)
    CONTROL = {
        'R/W': 'W',
        'Register': 0x3100,
        'functioncode': 6,
        'Value': {'Stop': 0x0006, 'Start': 0x000F},
    }
    OPMODE = {
        'R/W': 'W',
        'Register': 0x3500,
        'functioncode': 6,
        'Value': {'Position': 1},
    }

    # Write-only registers (FC 16)
    VelocityCommand = {
        'R/W': 'W',
        'Register': 0x6F00,
        'functioncode': 16,
    }
    PositionCommand = {
        'R/W': 'W',
        'Register': 0x4000,
        'functioncode': 16,
    }

    # ------------------------------------------------------------------
    # Connection parameters
    # ------------------------------------------------------------------
    SERIAL_PORT = '/dev/serial0'
    BAUDRATE = 115200
    TIMEOUT = 1.0
    UNIT_ID = 1

    def __init__(self, port=SERIAL_PORT, baudrate=BAUDRATE, timeout=TIMEOUT, unit_id=UNIT_ID):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.unit_id = unit_id
        self.client = None
        self._connect()

    # ------------------------------------------------------------------
    # Connection management
    # ------------------------------------------------------------------
    def _connect(self):
        """Open the serial port and create a Modbus RTU client."""
        try:
            self.client = ModbusSerialClient(
                port=self.port,
                baudrate=self.baudrate,
                parity='N',
                stopbits=1,
                bytesize=8,
                timeout=self.timeout,
            )
            if not self.client.connect():
                raise serial.SerialException(f"Failed to open serial port {self.port}")
            logger.info(f"Connected to servo controller on {self.port} @ {self.baudrate} baud")
        except (serial.SerialException, OSError) as e:
            logger.warning(f"Could not open serial port {self.port}: {e}. "
                           f"Running in degraded mode (all I/O operations will fail).")
            self.client = None

    def close(self):
        """Release the serial connection cleanly."""
        if self.client is not None:
            try:
                self.client.close()
                logger.info("Serial connection closed.")
            except Exception as e:
                logger.error(f"Error closing serial connection: {e}")
            finally:
                self.client = None

    # ------------------------------------------------------------------
    # Modbus register access
    # ------------------------------------------------------------------
    def _read_register(self, register_info):
        """Read a single holding register via Modbus FC 3."""
        if self.client is None:
            raise RuntimeError("Serial connection not established.")
        if register_info.get('functioncode') != 3:
            raise ValueError("Invalid function code for read operation.")

        read_length = register_info.get('read_length', 1)
        result = self.client.read_holding_registers(
            address=register_info['Register'],
            count=read_length,
            slave=self.unit_id,
        )
        if result.isError():
            raise ModbusIOException(f"Modbus error reading register 0x{register_info['Register']:04X}: {result}")

        decoder = BinaryPayloadDecoder.fromRegisters(
            result.registers,
            byteorder=Endian.BIG,
            wordorder=Endian.LITTLE,
        )
        if read_length == 2:
            return decoder.decode_16bit_uint()
        return decoder.decode_16bit_uint()

    def _write_register(self, register_info, value):
        """Write a single holding register via Modbus FC 6."""
        if self.client is None:
            raise RuntimeError("Serial connection not established.")
        if register_info.get('functioncode') != 6:
            raise ValueError("Invalid function code for write operation.")

        result = self.client.write_register(
            address=register_info['Register'],
            value=value,
            slave=self.unit_id,
        )
        if result.isError():
            raise ModbusIOException(f"Modbus error writing register 0x{register_info['Register']:04X}: {result}")
        return True

    def _write_registers(self, register_info, values):
        """Write multiple holding registers via Modbus FC 16."""
        if self.client is None:
            raise RuntimeError("Serial connection not established.")
        if register_info.get('functioncode') != 16:
            raise ValueError("Invalid function code for write operation.")

        result = self.client.write_registers(
            address=register_info['Register'],
            values=values,
            slave=self.unit_id,
        )
        if result.isError():
            raise ModbusIOException(f"Modbus error writing registers 0x{register_info['Register']:04X}: {result}")
        return True

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def read_status(self):
        """Read the servo status register (0x3000)."""
        return self._read_register(self.STATUS)

    def read_velocity_feedback(self):
        """Read the velocity feedback register (0x3B00)."""
        return self._read_register(self.VelocityFeedback)

    def read_position_feedback(self):
        """Read the position feedback register (0x3700)."""
        return self._read_register(self.PositionFeedback)

    def stop(self):
        """Send the 'Stop' command (0x0006) to the CONTROL register (0x3100)."""
        return self._write_register(self.CONTROL, self.CONTROL['Value']['Stop'])

    def start(self):
        """Send the 'Start' command (0x000F) to the CONTROL register (0x3100)."""
        return self._write_register(self.CONTROL, self.CONTROL['Value']['Start'])

    def set_position_mode(self):
        """Set the operating mode to 'Position' (1) in OPMODE register (0x3500)."""
        return self._write_register(self.OPMODE, self.OPMODE['Value']['Position'])

    def set_velocity_command(self, velocity):
        """Set the velocity command in the VelocityCommand register (0x6F00)."""
        return self._write_register(self.VelocityCommand, velocity)

    def set_position_command(self, position):
        """Set the position command in the PositionCommand register (0x4000)."""
        return self._write_registers(self.PositionCommand, [position & 0xFFFF, (position >> 16) & 0xFFFF])


# ----------------------------------------------------------------------
# Signal handling for clean shutdown
# ----------------------------------------------------------------------
_servo_instance = None


def _signal_handler(signum, frame):
    logger.info(f"Signal {signum} received, shutting down.")
    if _servo_instance is not None:
        _servo_instance.close()
    sys.exit(0)


def main():
    global _servo_instance
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _servo_instance = Servo()
    try:
        logger.info(f"Status: {_servo_instance.read_status()}")
        logger.info(f"Velocity Feedback: {_servo_instance.read_velocity_feedback()}")
        logger.info(f"Position Feedback: {_servo_instance.read_position_feedback()}")

        _servo_instance.set_position_mode()
        _servo_instance.set_velocity_command(100)
        _servo_instance.set_position_command(10000)
        _servo_instance.start()
        time.sleep(1)
        _servo_instance.stop()

        logger.info("Demo sequence completed successfully.")
    except (ModbusIOException, ModbusException, RuntimeError) as e:
        logger.error(f"Modbus communication error: {e}")
    except Exception as e:
        logger.error(f"Unexpected error: {e}")
    finally:
        _servo_instance.close()


if __name__ == '__main__':
    main()

