import time
import signal
import sys

try:
    from gpiozero import OutputDevice, Servo
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero library is required. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)


class Laser:
    """Controls a laser module via gpiozero.OutputDevice."""

    def __init__(self, pin=17):
        self.pin = pin
        try:
            self.laser = OutputDevice(pin)
        except GPIOZeroError as e:
            print(f"Error initializing laser on GPIO{pin}: {e}")
            raise

    def on(self):
        try:
            self.laser.on()
        except DeviceClosed:
            print(f"Error: laser device on GPIO{self.pin} is closed.")
            raise

    def off(self):
        try:
            self.laser.off()
        except DeviceClosed:
            print(f"Error: laser device on GPIO{self.pin} is closed.")
            raise

    def close(self):
        try:
            self.laser.close()
        except Exception:
            pass


class Aim:
    """Controls servo motors for laser aiming using gpiozero.Servo."""

    def __init__(self, ld=0.1, sd=0.05):
        self.ld = ld
        self.sd = sd
        self.hp = [0.05, 0.10, 0.15, 0.20, 0.25, 0.30, 0.35, 0.40, 0.45, 0.50]
        self.vp = [0.55, 0.60, 0.65, 0.70, 0.75, 0.80, 0.85, 0.90, 0.95, 1.00]
        self.neutral = 10

        try:
            self.h = Servo(18, min_pulse_width=0.0005, max_pulse_width=0.0025)
            self.v = Servo(19, min_pulse_width=0.0005, max_pulse_width=0.0025)
        except GPIOZeroError as e:
            print(f"Error initializing servos: {e}")
            raise

    def move(self, hpos, vpos):
        try:
            self.h.value = self.hp[hpos]
            self.v.value = self.vp[vpos]
        except IndexError:
            print(f"Error: servo position index {hpos}/{vpos} out of range.")
            raise
        except DeviceClosed:
            print("Error: servo device is closed.")
            raise

    def aim(self, nums):
        laser = Laser()
        try:
            for b in nums:
                if b < 1 or b > len(self.hp):
                    print(f"Warning: target index {b} out of range, skipping.")
                    continue
                self.move(b - 1, b - 1)
                time.sleep(self.sd / 2)
                laser.on()
                time.sleep(self.ld)
                laser.off()
                self.move(self.neutral, self.neutral)
                time.sleep(self.sd / 2)
        except KeyboardInterrupt:
            print("\nAiming interrupted by user.")
        except Exception as e:
            print(f"Error during aiming: {e}")
        finally:
            laser.off()
            laser.close()
            self.move(self.neutral, self.neutral)
            self.h.close()
            self.v.close()


def main():
    try:
        aim = Aim(ld=0.1, sd=0.05)
        aim.aim([1, 2, 3, 4, 5])
    except Exception as e:
        print(f"Initialization failed: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()

