import time
import signal
import sys

try:
    from adafruit_servokit import ServoKit
except ImportError:
    print("Error: adafruit_servokit library not found. Install with: pip install adafruit-circuitpython-servokit")
    sys.exit(1)

# Constants for servo control
GRAB_ANGLE = 90
RELEASE_ANGLE = 150
SERVO_STEP_DEGREES = 5
SERVO_STEP_DELAY = 0.04
SERVO_COUNT = 16
I2C_BUS = 1
I2C_ADDRESS = 0x40

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def initialize_servokit():
    """Initializes the ServoKit object with error handling."""
    try:
        kit = ServoKit(channels=SERVO_COUNT, i2c=None, address=I2C_ADDRESS)
        return kit
    except (OSError, ValueError) as e:
        print(f"Error initializing ServoKit on I2C bus {I2C_BUS} at address 0x{I2C_ADDRESS:02X}: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing ServoKit: {e}")
        return None


def move_servo(kit, servo_num, target_angle):
    """Moves a servo to a target angle in 5-degree increments."""
    if not 0 <= servo_num < SERVO_COUNT:
        print(f"Error: Servo number {servo_num} out of range (0-{SERVO_COUNT - 1}).")
        return False

    if not 0 <= target_angle <= 180:
        print(f"Error: Target angle {target_angle} out of range (0-180).")
        return False

    try:
        current_angle = kit.servo[servo_num].angle
        if current_angle is None:
            current_angle = 0

        step = SERVO_STEP_DEGREES if target_angle > current_angle else -SERVO_STEP_DEGREES
        angle = current_angle

        while _running:
            if (step > 0 and angle >= target_angle) or (step < 0 and angle <= target_angle):
                break
            angle += step
            # Clamp to target to avoid overshoot
            if step > 0:
                angle = min(angle, target_angle)
            else:
                angle = max(angle, target_angle)

            kit.servo[servo_num].angle = angle
            time.sleep(SERVO_STEP_DELAY)

        return True

    except (OSError, ValueError) as e:
        print(f"Error moving servo {servo_num} to {target_angle} degrees: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error moving servo {servo_num}: {e}")
        return False


def grab_object(kit, servo_num=0):
    """Grabs an object using the specified servo."""
    print(f"Grabbing object with servo {servo_num}...")
    return move_servo(kit, servo_num, GRAB_ANGLE)


def release_object(kit, servo_num=0):
    """Releases an object using the specified servo."""
    print(f"Releasing object with servo {servo_num}...")
    return move_servo(kit, servo_num, RELEASE_ANGLE)


def main():
    """Main function to demonstrate object manipulation."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    kit = initialize_servokit()
    if kit is None:
        print("Failed to initialize ServoKit. Exiting.")
        sys.exit(1)

    try:
        if grab_object(kit, 0):
            time.sleep(1)
            release_object(kit, 0)
        else:
            print("Failed to move servo 0 during grab/release sequence.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Clean resource release on all exit paths
        print("Cleaning up resources...")
        try:
            # Turn off all PWM signals to release servos
            for i in range(SERVO_COUNT):
                kit.servo[i].angle = None
        except Exception:
            pass
        print("Exiting program.")


if __name__ == "__main__":
    main()

