import logging
import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")

NUTRIENT_PUMP_PIN = 20
GROW_LIGHT_PIN = 21

nutrient_pump = None
grow_light = None


def apply_intent(intent_name):
    """Drive the actuator corresponding to the recognized intent."""
    if intent_name == "pump_on":
        nutrient_pump.on()
        logging.info("Nutrient pump turned ON")
    elif intent_name == "pump_off":
        nutrient_pump.off()
        logging.info("Nutrient pump turned OFF")
    elif intent_name == "light_toggle":
        grow_light.toggle()
        logging.info("Grow light toggled")
    else:
        logging.warning("Unknown intent: %s", intent_name)


def parse_phrase(phrase):
    """Return the recognized intent name for a plain English phrase."""
    normalized = phrase.lower()
    if "pump" in normalized and "on" in normalized:
        return "pump_on"
    if "pump" in normalized and "off" in normalized:
        return "pump_off"
    if "light" in normalized and ("toggle" in normalized or "switch" in normalized):
        return "light_toggle"
    return None


def cleanup(signum=None, frame=None):
    """Turn off all actuators and release resources."""
    global nutrient_pump, grow_light
    for device, name in ((nutrient_pump, "nutrient_pump"), (grow_light, "grow_light")):
        if device is not None:
            try:
                device.off()
                device.close()
            except Exception as exc:
                logging.error("Error closing %s: %s", name, exc)
    if signum is not None:
        sys.exit(0)


def main():
    global nutrient_pump, grow_light
    try:
        nutrient_pump = OutputDevice(NUTRIENT_PUMP_PIN)
        grow_light = OutputDevice(GROW_LIGHT_PIN)
    except GPIOZeroError as exc:
        logging.error("Failed to initialize actuators: %s", exc)
        sys.exit(1)
    except Exception as exc:
        logging.error("Unexpected error during actuator init: %s", exc)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    test_phrases = ["turn the pump on", "switch the light", "turn pump off", "unknown command"]
    for phrase in test_phrases:
        intent = parse_phrase(phrase)
        logging.info("Phrase: '%s' -> intent: %s", phrase, intent)
        if intent is not None:
            apply_intent(intent)
        else:
            logging.warning("No intent recognized for phrase: %s", phrase)

    cleanup()


if __name__ == "__main__":
    main()

