import signal
import sys
import logging
from datetime import datetime
from smbus2 import SMBus, i2c_msg

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class DS1338:
    """Driver for the DS1338 I2C RTC chip using smbus2."""

    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06
    REG_CONTROL = 0x07

    def __init__(self, i2c_bus=1, i2c_address=0x68):
        self.i2c_address = i2c_address
        self.bus = None
        try:
            self.bus = SMBus(i2c_bus)
            self._read_register(self.REG_SECONDS)
            logging.info(f"DS1338 initialized on bus {i2c_bus} at address 0x{i2c_address:02X}")
        except OSError as e:
            logging.error(f"Failed to initialize DS1338 at 0x{i2c_address:02X}: {e}")
            if self.bus:
                self.bus.close()
            raise

    def _write_register(self, register, value):
        if not (0 <= value <= 0xFF):
            raise ValueError(f"Value {value} out of byte range for register 0x{register:02X}")
        self.bus.write_byte_data(self.i2c_address, register, value)

    def _read_register(self, register):
        return self.bus.read_byte_data(self.i2c_address, register)

    @staticmethod
    def _bcd_to_int(bcd):
        return (bcd >> 4) * 10 + (bcd & 0x0F)

    @staticmethod
    def _int_to_bcd(value):
        if not (0 <= value <= 99):
            raise ValueError(f"Value {value} out of BCD range (0-99)")
        return ((value // 10) << 4) | (value % 10)

    def read_seconds(self):
        return self._bcd_to_int(self._read_register(self.REG_SECONDS) & 0x7F)

    def read_minutes(self):
        return self._bcd_to_int(self._read_register(self.REG_MINUTES))

    def read_hours(self):
        raw = self._read_register(self.REG_HOURS)
        return self._bcd_to_int(raw & 0x3F)

    def read_day(self):
        return self._bcd_to_int(self._read_register(self.REG_DAY))

    def read_date(self):
        return self._bcd_to_int(self._read_register(self.REG_DATE))

    def read_month(self):
        return self._bcd_to_int(self._read_register(self.REG_MONTH))

    def read_year(self):
        return self._bcd_to_int(self._read_register(self.REG_YEAR))

    def read_all(self):
        return (
            self.read_seconds(),
            self.read_minutes(),
            self.read_hours(),
            self.read_day(),
            self.read_date(),
            self.read_month(),
            self.read_year(),
        )

    def read_datetime(self, century=21):
        try:
            year = self.read_year()
            month = self.read_month()
            date = self.read_date()
            hours = self.read_hours()
            minutes = self.read_minutes()
            seconds = self.read_seconds()
            full_year = (century - 1) * 100 + year
            return datetime(full_year, month, date, hours, minutes, seconds)
        except ValueError as e:
            logging.error(f"Invalid datetime values read from RTC: {e}")
            return None

    def write_seconds(self, seconds):
        self._write_register(self.REG_SECONDS, self._int_to_bcd(seconds))

    def write_minutes(self, minutes):
        self._write_register(self.REG_MINUTES, self._int_to_bcd(minutes))

    def write_hours(self, hours):
        self._write_register(self.REG_HOURS, self._int_to_bcd(hours))

    def write_day(self, day):
        self._write_register(self.REG_DAY, self._int_to_bcd(day))

    def write_date(self, date):
        self._write_register(self.REG_DATE, self._int_to_bcd(date))

    def write_month(self, month):
        self._write_register(self.REG_MONTH, self._int_to_bcd(month))

    def write_year(self, year):
        self._write_register(self.REG_YEAR, self._int_to_bcd(year % 100))

    def write_all(self, seconds=None, minutes=None, hours=None, day=None, date=None, month=None, year=None):
        if seconds is not None:
            self.write_seconds(seconds)
        if minutes is not None:
            self.write_minutes(minutes)
        if hours is not None:
            self.write_hours(hours)
        if day is not None:
            self.write_day(day)
        if date is not None:
            self.write_date(date)
        if month is not None:
            self.write_month(month)
        if year is not None:
            self.write_year(year)

    def close(self):
        if self.bus:
            self.bus.close()
            self.bus = None


def _signal_handler(signum, frame):
    logging.info(f"Received signal {signum}, shutting down.")
    sys.exit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    rtc = None
    try:
        rtc = DS1338(i2c_bus=1, i2c_address=0x68)
        now = datetime.now()
        rtc.write_all(
            seconds=now.second,
            minutes=now.minute,
            hours=now.hour,
            day=now.isoweekday(),
            date=now.day,
            month=now.month,
            year=now.year,
        )
        logging.info(f"RTC time set to: {rtc.read_datetime()}")
    except OSError as e:
        logging.error(f"I2C communication error: {e}")
    except ValueError as e:
        logging.error(f"Value error: {e}")
    finally:
        if rtc:
            rtc.close()


if __name__ == "__main__":
    main()

