#!/usr/bin/env python3
"""
CO2 sensor reader for Raspberry Pi Zero W.

Reads ASCII CO2 concentration (ppm) from a serial sensor on /dev/ttyUSB0
at 9600 baud, logs each sample with an ISO-8601 timestamp, and prints
the value every 5 seconds.  Handles decode errors, I/O errors, and
graceful shutdown on SIGINT/SIGTERM.
"""

import signal
import sys
import time
from datetime import datetime

import serial

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
READ_TIMEOUT = 1          # seconds
SAMPLE_INTERVAL = 5       # seconds between samples
LOG_FILE = "co2_readings_log.txt"

_running = True


def _handle_signal(signum, frame):
    """Flag the main loop to exit cleanly on SIGINT / SIGTERM."""
    global _running
    _running = False


def open_serial_port():
    """Open the serial port or exit on failure."""
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)


def read_co2_concentration(ser):
    """
    Read one line from the serial port and return the CO2 ppm as an int.

    Returns None if the line is empty, non-numeric, or a decode error occurs.
    """
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    text = raw.decode("ascii", errors="replace").strip()
    if not text:
        return None

    try:
        return int(text)
    except ValueError:
        print(f"Error: non-numeric data received: {text!r}", file=sys.stderr)
        return None


def log_reading(co2_value):
    """Append a timestamped CO2 reading to the log file."""
    timestamp = datetime.now().isoformat(timespec="seconds")
    line = f"{timestamp} - CO2 Concentration: {co2_value} ppm\n"
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as fh:
            fh.write(line)
    except IOError as exc:
        print(f"Error writing to log file: {exc}", file=sys.stderr)


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = open_serial_port()

    try:
        while _running:
            co2_value = read_co2_concentration(ser)
            if co2_value is not None:
                print(f"CO2 Concentration: {co2_value} ppm")
                log_reading(co2_value)
            time.sleep(SAMPLE_INTERVAL)
    finally:
        if ser.is_open:
            ser.close()
        print("Serial port closed. Exiting.")


if __name__ == "__main__":
    main()

