import serial
import time
import signal
import sys
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def main():
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    alarm = OutputDevice(ALARM_PIN, active_high=True, initial_value=False)

    try:
        while running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                radiation = float(line)
            except ValueError:
                print(f"Warning: non-numeric data received: '{line}'", file=sys.stderr)
                continue

            if radiation > RADIATION_THRESHOLD:
                alarm.on()
            else:
                alarm.off()

            time.sleep(1)

    except KeyboardInterrupt:
        pass
    finally:
        try:
            alarm.off()
            alarm.close()
        except Exception:
            pass
        try:
            ser.close()
        except Exception:
            pass

if __name__ == '__main__':
    main()

