ALARM_PIN = 18
THRESHOLD = 50.0
POLL_INTERVAL = 1

running = True

def signal_handler(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    alarm = OutputDevice(ALARM_PIN, initial_value=False)

    try:
        while running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial I/O error: {e}", file=sys.stderr)
                time.sleep(POLL_INTERVAL)
                continue

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                radiation_level = float(line)
            except ValueError:
                print(f"Invalid data received (not numeric): {line!r}", file=sys.stderr)
                continue

            print(f"Radiation Level: {radiation_level:.2f} µSv/h")

            if radiation_level > THRESHOLD:
                if not alarm.is_active:
                    print("ALARM: Radiation level exceeds threshold!")
                alarm.on()
            else:
                if alarm.is_active:
                    print("ALARM: Radiation level back to normal")
                alarm.off()

            time.sleep(POLL_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if ser.is_open:
            ser.close()
        alarm.close()
        print("Resources released. Exiting.")

if __name__ == "__main__":
    main()

