import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'

running = True

def signal_handler(sig, frame):
    global running
    running = False

def parse_gps_data(gps_data):
    if not gps_data.startswith('$GPGGA'):
        return None, None, None

    parts = gps_data.split(',')
    if len(parts) < 10:
        return None, None, None

    fix_quality = parts[6]
    if fix_quality != '1':
        return None, None, None

    latitude = parts[2]
    latitude_dir = parts[3]
    longitude = parts[4]
    longitude_dir = parts[5]

    if not latitude or not longitude:
        return None, None, None

    return latitude, latitude_dir, longitude, longitude_dir

def log_coordinates(latitude, latitude_dir, longitude, longitude_dir, log_file):
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    log_entry = f"{timestamp}, {latitude} {latitude_dir}, {longitude} {longitude_dir}\n"
    try:
        with open(log_file, 'a') as f:
            f.write(log_entry)
        print(f"Data logged to {log_file}")
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

    try:
        while running:
            try:
                raw_data = ser.readline()
                if not raw_data:
                    continue

                gps_data = raw_data.decode('ascii', errors='replace').strip()

                latitude, latitude_dir, longitude, longitude_dir = parse_gps_data(gps_data)

                if latitude and longitude:
                    print(f"Latitude: {latitude} {latitude_dir}, Longitude: {longitude} {longitude_dir}")
                    log_coordinates(latitude, latitude_dir, longitude, longitude_dir, LOG_FILE)

            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                time.sleep(1)
            except Exception as e:
                print(f"Error processing GPS data: {e}")
                time.sleep(1)

    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

