    if not gps_data.startswith('$GPGGA'):
        return None, None, None

    parts = gps_data.split(',')
    if len(parts) < 10:
        return None, None, None

    fix_quality = parts[6]
    if fix_quality != '1':
        return None, None, None

    latitude = parts[2]
    latitude_dir = parts[3]
    longitude = parts[4]
    longitude_dir = parts[5]

    if not latitude or not longitude:
        return None, None, None

    return latitude, latitude_dir, longitude, longitude_dir

