    try:
        serial_port = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return

    try:
        while not stop_event.is_set():
            try:
                raw_data = serial_port.readline()
                if not raw_data:
                    continue

                data = raw_data.decode('ascii', errors='replace').strip()
                if not data:
                    continue

                try:
                    flow_rate = float(data)
                    print(f"Flow Rate: {flow_rate} L/min")
                    log_flow_rate(flow_rate)
                except ValueError:
                    print(f"Invalid data received (not a float): '{data}'")

                stop_event.wait(READ_INTERVAL)

            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                break
    finally:
