            reader_thread.join(timeout=1)
    except KeyboardInterrupt:
        stop_event.set()
    finally:
        if reader_thread.is_alive():
            stop_event.set()
            reader_thread.join(timeout=2)
        print("Program terminated.")


if __name__ == '__main__':
    main()

