import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


@dataclass
class GPS_readings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellite_count: Optional[int] = None


class GPSReader:
    """Reads NMEA GPS data from a serial port and parses GPGGA sentences."""

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser: Optional[serial.Serial] = None

    def connect(self) -> bool:
        """Open the serial port; return True on success, False on failure."""
        try:
            self.ser = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logging.info("Connected to GPS on %s at %d baud", self.port, self.baudrate)
            return True
        except serial.SerialException as exc:
            logging.error("Failed to open serial port %s: %s", self.port, exc)
            self.ser = None
            return False
        except Exception as exc:
            logging.error("Unexpected error opening %s: %s", self.port, exc)
            self.ser = None
            return False

    def disconnect(self) -> None:
        """Close the serial port if open; idempotent and never raises."""
        if self.ser is not None:
            try:
                if self.ser.is_open:
                    self.ser.close()
                logging.info("Serial port closed.")
            except Exception as exc:
                logging.error("Error closing serial port: %s", exc)
            finally:
                self.ser = None

    def _verify_checksum(self, sentence: str) -> bool:
        """Validate the NMEA checksum: *XX at end of data field after '*'."""
        if "*" not in sentence:
            return False
        body, _, csum_str = sentence.partition("*")
        if not body.startswith("$"):
            return False
        expected = csum_str.strip().upper()
        calculated = "{:02X}".format(
            reduce(lambda a, b: a ^ ord(b), body[1:], 0)
        )
        return calculated == expected

    def _parse_gpgga(self, data: str) -> Optional[GPS_readings]:
        """Parse a GPGGA sentence; return None on any validation/parse error."""
        if not data.startswith("$GPGGA"):
            return None
        if not self._verify_checksum(data):
            logging.warning("GPGGA checksum mismatch: %s", data.strip())
            return None

        fields = data.split(",")
        if len(fields) < 15:
            logging.warning("GPGGA sentence too short: %s", data.strip())
            return None

        talker = fields[0]
        if talker != "$GPGGA":
            logging.warning("Unexpected talker: %s", talker)
            return None

        try:
            lat_raw = fields[2]
            lon_raw = fields[4]
            if not lat_raw or not lon_raw:
                logging.warning("Empty lat/lon in GPGGA: %s", data.strip())
                return None

            lat_deg = float(lat_raw[:2])
            lat_min = float(lat_raw[2:])
            latitude = lat_deg + lat_min / 60.0
            if fields[3] == "S":
                latitude = -latitude

            lon_deg = float(lon_raw[:3])
            lon_min = float(lon_raw[3:])
            longitude = lon_deg + lon_min / 60.0
            if fields[5] == "W":
                longitude = -longitude

            altitude = float(fields[9]) if fields[9] else None
            satellites = int(fields[7]) if fields[7] else None
        except ValueError as exc:
            logging.warning("Numeric parse error in GPGGA: %s - %s", data.strip(), exc)
            return None
        except Exception as exc:
            logging.warning("Unexpected parse error in GPGGA: %s - %s", data.strip(), exc)
            return None

        return GPS_readings(
            latitude=latitude,
            longitude=longitude,
            altitude=altitude,
            satellite_count=satellites,
        )

    def read_data(self) -> Optional[GPS_readings]:
        """Read one line from the serial port and parse GPGGA; return readings or None."""
        if self.ser is None or not self.ser.is_open:
            logging.error("Serial port not open; cannot read.")
            return None

        try:
            raw = self.ser.readline()
        except serial.SerialException as exc:
            logging.error("Serial read error: %s", exc)
            return None
        except Exception as exc:
            logging.error("Unexpected read error: %s", exc)
            return None

        if not raw:
            return None  # timeout, no data

        try:
            line = raw.decode("ascii", errors="replace").strip()
        except Exception as exc:
            logging.warning("Decode error: %s", exc)
            return None

        if not line:
            return None

        return self._parse_gpgga(line)


def main() -> None:
    gps = GPSReader(port="/dev/serial0", baudrate=9600, timeout=1.0)

    def _signal_handler(signum, frame):
        logging.info("Signal %d received, shutting down.", signum)
        gps.disconnect()
        sys.exit(0)

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not gps.connect():
        logging.error("Could not connect to GPS. Exiting.")
        sys.exit(1)

    try:
        while True:
            readings = gps.read_data()
            if readings is not None:
                logging.info(
                    "GPS: lat=%.6f, lon=%.6f, alt=%s, sats=%s",
                    readings.latitude or 0.0,
                    readings.longitude or 0.0,
                    readings.altitude,
                    readings.satellite_count,
                )
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received.")
    finally:
        gps.disconnect()


if __name__ == "__main__":
    main()

