import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
LOG_FILE = 'power_consumption.log'

running = True

def signal_handler(signum, frame):
    global running
    running = False

def log_power_data(power_value):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Power: {power_value} W\n'
    try:
        with open(LOG_FILE, 'a') as logfile:
            logfile.write(log_entry)
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f'Opened {SERIAL_PORT} at {BAUD_RATE} baud.')

        while running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f'Serial read error: {e}', file=sys.stderr)
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                power = float(line)
                log_power_data(power)
            except ValueError:
                print(f'Warning: Non-numeric data received: {line!r}', file=sys.stderr)

    except serial.SerialException as e:
        print(f'Error opening serial port: {e}', file=sys.stderr)
    except OSError as e:
        print(f'OS error: {e}', file=sys.stderr)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print('Serial port closed.')

if __name__ == '__main__':
    main()

