from flask import Flask, request, jsonify
import serial
import time
import json

app = Flask(__name__)

data_store = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": False},
]

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600


def get_serial_response():
    """Open the serial port, send *IDN?, read 0.1 s, return text/html."""
    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        ser.reset_input_buffer()
        ser.write(b'*IDN?\n')
        time.sleep(0.1)
        raw = ser.read(ser.in_waiting or 1024)
        if not raw:
            return 'No response from device', 503
        return raw.decode('utf-8', errors='replace').replace('\n', '<br>'), 200
    except serial.SerialException as e:
        return f'Serial error: {e}', 503
    except Exception as e:
        return f'Unexpected error: {e}', 500
    finally:
        if ser is not None and ser.is_open:
            ser.close()


@app.route('/version')
def version():
    response, status = get_serial_response()
    return response, status


@app.route('/getdata')
def get_data():
    return jsonify(data_store)


@app.route('/getset/<int:item_id>')
def get_set_item(item_id):
    item = next((i for i in data_store if i['id'] == item_id), None)
    if item is None:
        return jsonify({'error': 'Item not found'}), 404
    return jsonify(item)


@app.route('/getpost/<int:item_id>/<name>')
def get_post_item(item_id, name):
    new_item = {"id": item_id, "name": name, "done": False}
    data_store.append(new_item)
    return jsonify(data_store)


@app.route('/postjson', methods=['POST', 'GET'])
def post_json():
    if request.method == 'POST':
        try:
            if request.is_json:
                data = request.get_json(silent=False)
            else:
                data = request.form

            name = data.get('name', '')
            done = data.get('done', False)
            if isinstance(done, str):
                done = done.lower() in ('true', '1', 'yes')
            elif isinstance(done, bool):
                done = done
            else:
                done = False

            new_id = (data_store[-1]['id'] + 1) if data_store else 1
            new_item = {"id": new_id, "name": name, "done": done}
            data_store.append(new_item)
            return jsonify(data_store)
        except (KeyError, TypeError, ValueError) as e:
            return jsonify({'error': f'Invalid input: {e}'}), 400
    else:
        return jsonify(data_store)


if __name__ == '__main__':
    app.run(host='0.0.0.0')

