import serial
import time
import sys

BLUETOOTH_PORT = "/dev/rfcomm4"
BAUD_RATE = 38400


def create_bluetooth_connection(port, baudrate):
    """Establishes a serial connection to the Bluetooth device."""
    try:
        conn = serial.Serial(port, baudrate, timeout=1)
        return conn
    except serial.SerialException as e:
        raise RuntimeError(f"Error opening serial port {port}: {e}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error opening serial port {port}: {e}")


def send_command(connection, command):
    """Sends a command to the Bluetooth device with error handling."""
    try:
        full_command = f"X{command}\n"
        connection.write(full_command.encode("utf-8"))
        connection.flush()
        time.sleep(0.1)
    except serial.SerialException as e:
        raise RuntimeError(f"Error sending command: {e}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error sending command: {e}")


def main():
    bluetooth_connection = None
    try:
        bluetooth_connection = create_bluetooth_connection(BLUETOOTH_PORT, BAUD_RATE)
        print(f"Connected to Bluetooth device on {BLUETOOTH_PORT} at {BAUD_RATE} baud.")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.lower() == "exit":
                break

            try:
                send_command(bluetooth_connection, user_command)
                print(f"Sent: {user_command}")
            except RuntimeError as e:
                print(f"Error: {e}")

    except RuntimeError as e:
        print(f"Fatal Error: {e}", file=sys.stderr)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        if bluetooth_connection is not None and bluetooth_connection.is_open:
            bluetooth_connection.close()
            print("Bluetooth connection closed.")


if __name__ == "__main__":
    main()

